#[cfg(target_os = "none")]
const MINI_UART_IO_OFFSET: usize = 0x40;
#[cfg(target_os = "none")]
const MINI_UART_IER_OFFSET: usize = 0x44;
#[cfg(target_os = "none")]
const MINI_UART_IIR_OFFSET: usize = 0x48;
#[cfg(target_os = "none")]
const MINI_UART_LCR_OFFSET: usize = 0x4c;
#[cfg(target_os = "none")]
const MINI_UART_MCR_OFFSET: usize = 0x50;
#[cfg(target_os = "none")]
const MINI_UART_LSR_OFFSET: usize = 0x54;
#[cfg(target_os = "none")]
const MINI_UART_CNTL_OFFSET: usize = 0x60;
#[cfg(target_os = "none")]
const AUX_ENABLES_OFFSET: usize = 0x04;
#[cfg(target_os = "none")]
const MINI_UART_LSR_RX_READY: u32 = 1;
#[cfg(target_os = "none")]
const MINI_UART_LSR_TX_EMPTY: u32 = 1 << 5;
#[cfg(target_os = "none")]
const MINI_UART_TX_SPIN_LIMIT: usize = 65_536;
const MINI_UART_RX_DRAIN_LIMIT: usize = 128;
const MINI_UART_RX_QUEUE_CAPACITY: usize = 512;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct SerialRuntimeRxQueue {
    bytes: [u8; MINI_UART_RX_QUEUE_CAPACITY],
    head: usize,
    len: usize,
    drops: u32,
}

impl SerialRuntimeRxQueue {
    const fn new() -> Self {
        Self {
            bytes: [0; MINI_UART_RX_QUEUE_CAPACITY],
            head: 0,
            len: 0,
            drops: 0,
        }
    }

    fn reset(&mut self) {
        *self = Self::new();
    }

    fn push(&mut self, byte: u8) -> bool {
        if self.len == MINI_UART_RX_QUEUE_CAPACITY {
            self.drops = self.drops.saturating_add(1);
            return false;
        }
        let tail = (self.head + self.len) % MINI_UART_RX_QUEUE_CAPACITY;
        self.bytes[tail] = byte;
        self.len += 1;
        true
    }

    fn pop(&mut self) -> Option<u8> {
        if self.len == 0 {
            return None;
        }
        let byte = self.bytes[self.head];
        self.head = (self.head + 1) % MINI_UART_RX_QUEUE_CAPACITY;
        self.len -= 1;
        Some(byte)
    }
}

/// Shared-buffer descriptor passed over the pointer-free driver-task ring.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DriverFrameDescriptor {
    /// Offset into the ring/shared-buffer arena.
    pub offset: u32,
    /// Valid payload length at `offset`.
    pub len: u16,
    /// Role-specific primitive flags.
    pub flags: u16,
}

impl DriverFrameDescriptor {
    const fn empty() -> Self {
        Self {
            offset: 0,
            len: 0,
            flags: 0,
        }
    }

    fn in_ring_payload(self) -> bool {
        let offset = self.offset as usize;
        let len = self.len as usize;
        len <= MAX_DRIVER_TASK_FRAME_BYTES
            && offset >= DRIVER_TASK_RING_FRAME_OFFSET
            && offset
                .checked_add(len)
                .is_some_and(|end| end <= DRIVER_TASK_RING_PAGE_BYTES)
    }

    fn in_ring_page_payload(self) -> bool {
        let offset = self.offset as usize;
        let len = self.len as usize;
        offset >= DRIVER_TASK_RING_FRAME_OFFSET
            && offset
                .checked_add(len)
                .is_some_and(|end| end <= DRIVER_TASK_RING_PAGE_BYTES)
    }

    fn in_runtime_payload(self, shared_payload_bytes: usize) -> bool {
        if self.in_ring_page_payload() {
            return true;
        }
        let offset = self.offset as usize;
        let len = self.len as usize;
        offset >= DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE as usize
            && offset
                .checked_add(len)
                .is_some_and(|end| end <= DRIVER_TASK_RING_PAGE_BYTES + shared_payload_bytes)
    }
}

/// Primitive budget grant encoded in the root/driver ring ABI.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DriverTaskBudgetGrant {
    /// Maximum HAL operations admitted for the command.
    pub max_ops: u16,
    /// Maximum frames admitted for the command.
    pub max_frames: u16,
    /// Maximum bytes admitted for the command.
    pub max_bytes: u32,
}

/// Fixed command record consumed by isolated driver runtimes.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DriverTaskCommandRecord {
    /// Monotonic root-assigned sequence number.
    pub sequence: u32,
    /// Primitive command opcode.
    pub opcode: u16,
    /// Role-specific primitive flags.
    pub flags: u16,
    /// Opcode-specific primitive argument.
    pub arg0: u32,
    /// Second opcode-specific primitive argument.
    pub arg1: u32,
    /// Auxiliary role-specific argument.
    pub aux0: u32,
    /// Second auxiliary role-specific argument.
    pub aux1: u32,
    /// Per-command service budget.
    pub budget: DriverTaskBudgetGrant,
    /// Shared-buffer descriptor for frame-bearing commands.
    pub frame: DriverFrameDescriptor,
}

/// Completion record written by isolated driver runtimes.
#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DriverTaskCompletionRecord {
    /// Completed command sequence.
    pub sequence: u32,
    /// Primitive completion code.
    pub code: u16,
    /// Fault code or role-specific detail.
    pub detail: u16,
    /// Role-specific primitive result.
    pub result: u32,
    /// Shared-buffer descriptor for frame-bearing completions.
    pub frame: DriverFrameDescriptor,
}

impl DriverTaskCompletionRecord {
    const fn progress(sequence: u32, result: u32) -> Self {
        Self {
            sequence,
            code: COMPLETION_PROGRESS,
            detail: FAULT_NONE,
            result,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn progress_with_detail(sequence: u32, detail: u16, result: u32) -> Self {
        Self {
            sequence,
            code: COMPLETION_PROGRESS,
            detail,
            result,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn frame_ready(sequence: u32, len: u16) -> Self {
        Self {
            sequence,
            code: COMPLETION_FRAME_READY,
            detail: FAULT_NONE,
            result: len as u32,
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len,
                flags: 0,
            },
        }
    }

    const fn frame_ready_at(sequence: u32, offset: u32, len: u16) -> Self {
        Self {
            sequence,
            code: COMPLETION_FRAME_READY,
            detail: FAULT_NONE,
            result: len as u32,
            frame: DriverFrameDescriptor {
                offset,
                len,
                flags: 0,
            },
        }
    }

    const fn frame_ready_with_descriptor(sequence: u32, frame: DriverFrameDescriptor) -> Self {
        Self {
            sequence,
            code: COMPLETION_FRAME_READY,
            detail: FAULT_NONE,
            result: frame.len as u32,
            frame,
        }
    }

    const fn idle(sequence: u32) -> Self {
        Self {
            sequence,
            code: COMPLETION_IDLE,
            detail: FAULT_NONE,
            result: 0,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn idle_with_detail(sequence: u32, detail: u16, result: u32) -> Self {
        Self {
            sequence,
            code: COMPLETION_IDLE,
            detail,
            result,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn budget_exhausted(sequence: u32, detail: u16) -> Self {
        Self {
            sequence,
            code: COMPLETION_BUDGET_EXHAUSTED,
            detail,
            result: 0,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn fault(sequence: u32, detail: u16) -> Self {
        Self {
            sequence,
            code: COMPLETION_FAULT,
            detail,
            result: 0,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn fault_with_result(sequence: u32, detail: u16, result: u32) -> Self {
        Self {
            sequence,
            code: COMPLETION_FAULT,
            detail,
            result,
            frame: DriverFrameDescriptor::empty(),
        }
    }

    const fn fault_with_result_and_frame(
        sequence: u32,
        detail: u16,
        result: u32,
        frame: DriverFrameDescriptor,
    ) -> Self {
        Self {
            sequence,
            code: COMPLETION_FAULT,
            detail,
            result,
            frame,
        }
    }
}

/// Service one fixed-layout command without using root pointers.
#[must_use]
pub fn service_command(
    task_key: usize,
    command: DriverTaskCommandRecord,
) -> DriverTaskCompletionRecord {
    if command.sequence == 0 {
        return DriverTaskCompletionRecord::idle(0);
    }
    if command.opcode == OPCODE_SHUTDOWN {
        return DriverTaskCompletionRecord::progress(command.sequence, 1);
    }
    if command.opcode == OPCODE_SERVICE && command.arg0 == 0 {
        return DriverTaskCompletionRecord::progress(command.sequence, task_key as u32);
    }
    let Some(role) = role_for_hot_path(command.arg0) else {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    };
    if command.arg1 != role {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_COMMAND_VALIDATED,
        command.aux0,
    );
    if command.aux0 == DRIVER_RUNTIME_INIT_AUX {
        return service_runtime_init(command);
    }
    if RUNTIME_INIT_HOT_PATH.load(Ordering::Acquire) != command.arg0 {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_MISMATCH,
            command.aux0,
        );
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_READY,
        command.aux0,
    );
    if command_is_engine_init_aux(command.aux0) {
        publish_service_dispatch_progress(command);
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DISPATCH,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_ENTER,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_AUX_MATCH,
            command.aux0,
        );
        if command.opcode != OPCODE_SERVICE || command.frame.len != 0 {
            return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
        }
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_FRAME_READY,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_BEGIN,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_MARK_ENTER,
            command.aux0,
        );
        match mark_engine_initialized(command) {
            Ok(detail) => {
                publish_runtime_progress(
                    command.sequence,
                    DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DONE,
                    command.aux0,
                );
                return DriverTaskCompletionRecord::progress_with_detail(
                    command.sequence,
                    detail,
                    1,
                );
            }
            Err(detail) => {
                return DriverTaskCompletionRecord::fault(command.sequence, detail);
            }
        }
    }
    if !opcode_matches_hot_path(command.opcode, command.arg0) {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    publish_service_dispatch_progress(command);

    match command.arg0 {
        HOT_PATH_SERIAL_CONSOLE => service_serial(command),
        HOT_PATH_USB_KEYBOARD => service_usb_keyboard(command),
        HOT_PATH_HDMI_TEXT => service_hdmi_text(command),
        HOT_PATH_GENET_NIC => service_genet_runtime(command),
        HOT_PATH_CYW43_WIFI => service_cyw43_runtime(command),
        HOT_PATH_SDIO_HOST => service_sdio_host(command),
        HOT_PATH_PCIE_ROOT => service_pcie_root(command),
        _ => DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND),
    }
}

#[must_use]
const fn command_expects_reply(command: DriverTaskCommandRecord) -> bool {
    command.flags & DRIVER_RUNTIME_COMMAND_FLAG_ONE_WAY == 0
}

const RUNTIME_IDLE_POLL_PROGRESS_INTERVAL: u32 = 256;

#[must_use]
const fn runtime_idle_poll_progress_due(idle_polls: u32) -> bool {
    idle_polls == 1 || (idle_polls != 0 && idle_polls % RUNTIME_IDLE_POLL_PROGRESS_INTERVAL == 0)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RuntimeCommandAdmission {
    None,
    OneWay,
    NeedsReplyCap,
}

#[must_use]
const fn runtime_command_admission(
    command: DriverTaskCommandRecord,
    last_sequence: u32,
) -> RuntimeCommandAdmission {
    if command.sequence == 0 || command.sequence == last_sequence {
        RuntimeCommandAdmission::None
    } else if command_expects_reply(command) {
        RuntimeCommandAdmission::NeedsReplyCap
    } else {
        RuntimeCommandAdmission::OneWay
    }
}

#[cfg(target_os = "none")]
#[derive(Clone, Copy)]
struct RuntimeCommandIntake {
    command: DriverTaskCommandRecord,
    reply_cap_available: bool,
}

#[cfg(target_os = "none")]
fn read_runtime_command_record() -> DriverTaskCommandRecord {
    driver_task_shared_invalidate_range(
        DRIVER_TASK_RING_VADDR,
        core::mem::size_of::<DriverTaskCommandRecord>(),
    );
    driver_task_shared_load_barrier();
    // SAFETY: Root maps one command/completion ring page at the fixed
    // driver-local address before starting the runtime.
    unsafe { core::ptr::read_volatile(DRIVER_TASK_RING_VADDR as *const DriverTaskCommandRecord) }
}

#[cfg(target_os = "none")]
fn poll_runtime_command(
    last_sequence: u32,
    task_key_marker: u32,
    publish_ring_read_begin: bool,
) -> Option<RuntimeCommandIntake> {
    if publish_ring_read_begin {
        publish_runtime_progress(
            0,
            pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_RING_READ_BEGIN,
            task_key_marker,
        );
    }
    let mut command = read_runtime_command_record();
    match runtime_command_admission(command, last_sequence) {
        RuntimeCommandAdmission::None => return None,
        RuntimeCommandAdmission::OneWay => {
            return Some(RuntimeCommandIntake {
                command,
                reply_cap_available: false,
            });
        }
        RuntimeCommandAdmission::NeedsReplyCap => {}
    }

    publish_runtime_progress(
        command.sequence,
        pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_POLL_BEGIN,
        command.aux0,
    );

    let mut badge: sel4_sys::seL4_Word = 0;
    // SAFETY: The root task minted `DRIVER_TASK_CHILD_COMMAND_SLOT` into the
    // child CSpace before resuming this TCB. The runtime reads the shared ring
    // before this endpoint poll so one-way bounded turns can make progress even
    // if endpoint wakeup telemetry is inconclusive. Endpoint polling is still
    // required for commands that need a reply cap.
    let tag = unsafe { sel4_sys::seL4_Poll(DRIVER_TASK_CHILD_COMMAND_SLOT, &mut badge) };
    let ipc_delivered = tag.length() != 0;
    let ipc_sequence = if ipc_delivered {
        // SAFETY: Root uses MR0 to carry the primitive request sequence when it
        // sends or calls the command endpoint.
        unsafe { sel4_sys::seL4_GetMR(0) as u32 }
    } else {
        0
    };
    if ipc_delivered && (command.sequence == 0 || command.sequence != ipc_sequence) {
        for _ in 0..8 {
            command = read_runtime_command_record();
            if command.sequence != 0 && command.sequence == ipc_sequence {
                break;
            }
            core::hint::spin_loop();
        }
    }
    if command.sequence == 0 || command.sequence == last_sequence {
        return None;
    }
    let expects_reply = command_expects_reply(command);
    if expects_reply && !ipc_delivered {
        publish_runtime_progress(
            command.sequence,
            pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_REPLY_PENDING,
            command.aux0,
        );
        return None;
    }
    if expects_reply && ipc_sequence != 0 && command.sequence != ipc_sequence {
        publish_runtime_progress(
            command.sequence,
            pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_RUNTIME_REPLY_PENDING,
            ipc_sequence,
        );
        return None;
    }
    Some(RuntimeCommandIntake {
        command,
        reply_cap_available: expects_reply,
    })
}

#[must_use]
fn validate_runtime_init_descriptor(
    command: DriverTaskCommandRecord,
    descriptor: DriverRuntimeInitDescriptor,
) -> DriverTaskCompletionRecord {
    if command.opcode != OPCODE_SERVICE
        || command.frame.len as usize != core::mem::size_of::<DriverRuntimeInitDescriptor>()
    {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if !descriptor.valid()
        || descriptor.hot_path != command.arg0
        || descriptor.role_bit != command.arg1
    {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    RUNTIME_DESCRIPTOR.store(descriptor);
    RUNTIME_INIT_HOT_PATH.store(descriptor.hot_path, Ordering::Release);
    RUNTIME_INIT_FLAGS.store(descriptor.flags, Ordering::Release);
    mark_descriptor_ready(descriptor.hot_path);
    if descriptor.hot_path == HOT_PATH_HDMI_TEXT
        && descriptor_resources_ready(&descriptor, HOT_PATH_HDMI_TEXT)
    {
        hdmi_render_boot_diagnostics(&descriptor);
        HDMI_RUNTIME_FLAGS.fetch_or(
            ENGINE_STATE_INITIALIZED
                | ENGINE_STATE_DESCRIPTOR_READY
                | ENGINE_STATE_RESOURCE_READY
                | ENGINE_STATE_HW_READY,
            Ordering::AcqRel,
        );
    }
    if descriptor.hot_path == HOT_PATH_PCIE_ROOT {
        let _ = adopt_hal_prepared_pcie_runtime_descriptor(descriptor);
    }
    DriverTaskCompletionRecord::progress(command.sequence, descriptor.hot_path)
}

#[cfg(target_os = "none")]
fn service_runtime_init(command: DriverTaskCommandRecord) -> DriverTaskCompletionRecord {
    if !command.frame.in_ring_payload() {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    let descriptor_addr = DRIVER_TASK_RING_VADDR + command.frame.offset as usize;
    // SAFETY: The frame descriptor is bounds-checked against the fixed ring
    // page. Root stages `DriverRuntimeInitDescriptor` at an aligned offset in
    // the ring payload before submitting the init command.
    let descriptor =
        unsafe { core::ptr::read_volatile(descriptor_addr as *const DriverRuntimeInitDescriptor) };
    validate_runtime_init_descriptor(command, descriptor)
}

#[cfg(not(target_os = "none"))]
fn service_runtime_init(command: DriverTaskCommandRecord) -> DriverTaskCompletionRecord {
    DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE)
}

/// Host-test helper for exercising runtime init without mapping the fixed ring.
#[cfg(test)]
#[must_use]
fn service_runtime_init_for_test(
    command: DriverTaskCommandRecord,
    descriptor: DriverRuntimeInitDescriptor,
) -> DriverTaskCompletionRecord {
    validate_runtime_init_descriptor(command, descriptor)
}

fn role_for_hot_path(hot_path: u32) -> Option<u32> {
    match hot_path {
        HOT_PATH_SERIAL_CONSOLE => Some(ROLE_SERIAL),
        HOT_PATH_USB_KEYBOARD => Some(ROLE_USB),
        HOT_PATH_HDMI_TEXT => Some(ROLE_DISPLAY),
        HOT_PATH_GENET_NIC | HOT_PATH_CYW43_WIFI => Some(ROLE_NET),
        HOT_PATH_SDIO_HOST => Some(ROLE_SDIO),
        HOT_PATH_PCIE_ROOT => Some(ROLE_PCIE),
        _ => None,
    }
}

fn opcode_matches_hot_path(opcode: u16, hot_path: u32) -> bool {
    if hot_path == HOT_PATH_HDMI_TEXT {
        opcode == OPCODE_SUBMIT_FRAME
    } else {
        opcode == OPCODE_SERVICE
    }
}

const fn command_is_engine_init_aux(aux0: u32) -> bool {
    matches!(
        aux0,
        DRIVER_RUNTIME_ENGINE_INIT_AUX
            | DRIVER_RUNTIME_LOCAL_SEAT_INIT_AUX
            | DRIVER_RUNTIME_NET_INIT_AUX
    )
}

fn publish_service_dispatch_progress(command: DriverTaskCommandRecord) {
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH,
        command.aux0,
    );
    let phase = match command.arg0 {
        HOT_PATH_HDMI_TEXT => DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH_HDMI,
        HOT_PATH_USB_KEYBOARD => DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH_USB,
        HOT_PATH_SDIO_HOST => DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH_SDIO,
        HOT_PATH_CYW43_WIFI => DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH_CYW43,
        _ => DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH,
    };
    if phase != DRIVER_RUNTIME_RING_PROGRESS_SERVICE_DISPATCH {
        publish_runtime_progress(command.sequence, phase, command.aux0);
    }
}

fn runtime_flags_for_hot_path(hot_path: u32) -> Option<&'static AtomicU32> {
    match hot_path {
        HOT_PATH_USB_KEYBOARD => Some(&USB_RUNTIME_FLAGS),
        HOT_PATH_HDMI_TEXT => Some(&HDMI_RUNTIME_FLAGS),
        HOT_PATH_GENET_NIC => Some(&GENET_RUNTIME_FLAGS),
        HOT_PATH_CYW43_WIFI => Some(&CYW43_RUNTIME_FLAGS),
        HOT_PATH_SDIO_HOST => Some(&SDIO_RUNTIME_FLAGS),
        HOT_PATH_PCIE_ROOT => Some(&PCIE_RUNTIME_FLAGS),
        _ => None,
    }
}

fn mark_descriptor_ready(hot_path: u32) {
    if let Some(flags) = runtime_flags_for_hot_path(hot_path) {
        flags.fetch_or(ENGINE_STATE_DESCRIPTOR_READY, Ordering::AcqRel);
    }
}

fn adopt_hal_prepared_pcie_runtime_descriptor(descriptor: DriverRuntimeInitDescriptor) -> bool {
    if !descriptor_resources_ready(&descriptor, HOT_PATH_PCIE_ROOT) {
        return false;
    }
    PCIE_RUNTIME_STATE.with_mut(|state| {
        state.reset();
        state.initialized = true;
        state.link_ready = true;
        state.last_status = PCIE_STATUS_PORT | PCIE_STATUS_DL_ACTIVE | PCIE_STATUS_PHY_LINK_UP;
        state.cfg_vendor_device = PCIE_VL805_PCI_VENDOR_DEVICE;
        state.cfg_class_revision = PCIE_VL805_EXPECTED_CLASS_REV;
    });
    PCIE_RUNTIME_FLAGS.fetch_or(
        ENGINE_STATE_INITIALIZED
            | ENGINE_STATE_DESCRIPTOR_READY
            | ENGINE_STATE_RESOURCE_READY
            | ENGINE_STATE_HW_READY,
        Ordering::AcqRel,
    );
    true
}

#[inline(never)]
fn mark_engine_initialized(command: DriverTaskCommandRecord) -> Result<u16, u16> {
    let hot_path = command.arg0;
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DESCRIPTOR_LOADED,
        command.aux0,
    );
    RUNTIME_DESCRIPTOR.with_ref(|descriptor| {
        if descriptor.hot_path != hot_path
            || RUNTIME_INIT_HOT_PATH.load(Ordering::Acquire) != hot_path
        {
            publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_MISMATCH,
                command.aux0,
            );
            return Err(DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_MISMATCH as u16);
        }
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DESCRIPTOR_READY,
            command.aux0,
        );
        let Some(flags) = runtime_flags_for_hot_path(hot_path) else {
            publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED,
                command.aux0,
            );
            return Err(DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED as u16);
        };
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_BEGIN,
            command.aux0,
        );
        if !descriptor_resources_ready_with_progress(
            descriptor,
            hot_path,
            command.sequence,
            command.aux0,
        ) {
            publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED,
                command.aux0,
            );
            return Err(DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED as u16);
        }
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCES_READY,
            command.aux0,
        );
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_HW_BEGIN,
            command.aux0,
        );
        let detail = runtime_engine_init(command.sequence, command.aux0, hot_path, descriptor);
        match detail {
            Ok(_) => publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_HW_DONE,
                command.aux0,
            ),
            Err(_) => publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_HW_FAILED,
                command.aux0,
            ),
        }
        let detail = detail?;
        let mut bits = ENGINE_STATE_INITIALIZED | ENGINE_STATE_DESCRIPTOR_READY;
        bits |= ENGINE_STATE_RESOURCE_READY | ENGINE_STATE_HW_READY;
        flags.fetch_or(bits, Ordering::AcqRel);
        Ok(detail)
    })
}

fn reset_sdio_register_shadows() {
    SDIO_TRANSFER_MODE_SHADOW.store(0, Ordering::Release);
    SDIO_BLOCK_SIZE_COUNT_SHADOW.store(0, Ordering::Release);
}

#[inline(never)]
fn runtime_engine_init(
    sequence: u32,
    aux0: u32,
    hot_path: u32,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Result<u16, u16> {
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RUNTIME_ENTRY,
        aux0,
    );
    match hot_path {
        HOT_PATH_USB_KEYBOARD => runtime_engine_init_usb(sequence, aux0, descriptor),
        HOT_PATH_HDMI_TEXT => runtime_engine_init_hdmi(descriptor),
        HOT_PATH_GENET_NIC => runtime_engine_init_genet(),
        HOT_PATH_CYW43_WIFI => {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_ENGINE_INIT_BRANCH,
                aux0,
            );
            runtime_engine_init_cyw43(sequence, aux0, descriptor)
        }
        HOT_PATH_SDIO_HOST => runtime_engine_init_sdio(sequence, aux0),
        HOT_PATH_PCIE_ROOT => runtime_engine_init_pcie(),
        _ => Ok(FAULT_NONE),
    }
}

#[inline(never)]
fn runtime_engine_init_usb(
    sequence: u32,
    aux0: u32,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Result<u16, u16> {
    usb_runtime_init(sequence, aux0, descriptor).ok_or(FAULT_DEVICE_UNAVAILABLE)
}

#[inline(never)]
fn runtime_engine_init_hdmi(descriptor: &DriverRuntimeInitDescriptor) -> Result<u16, u16> {
    hdmi_render_boot_diagnostics(descriptor);
    Ok(FAULT_NONE)
}

#[inline(never)]
fn runtime_engine_init_genet() -> Result<u16, u16> {
    GENET_RUNTIME_STATE.with_mut(|state| {
        genet_runtime_init(state)
            .then_some(FAULT_NONE)
            .ok_or(FAULT_DEVICE_UNAVAILABLE)
    })
}

#[inline(never)]
fn runtime_engine_init_cyw43(
    sequence: u32,
    aux0: u32,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Result<u16, u16> {
    CYW43_RUNTIME_STATE.with_mut(|state| {
        cyw43_runtime_init(sequence, aux0, state, descriptor)
            .then_some(FAULT_NONE)
            .ok_or(FAULT_DEVICE_UNAVAILABLE)
    })
}

#[inline(never)]
fn runtime_engine_init_sdio(sequence: u32, aux0: u32) -> Result<u16, u16> {
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_SDIO_ENGINE_INIT_BRANCH,
        aux0,
    );
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_SDIO_SHADOW_RESET_BEGIN,
        aux0,
    );
    reset_sdio_register_shadows();
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_SDIO_SHADOW_RESET_DONE,
        aux0,
    );
    sdio_runtime_init(sequence, aux0)
}

#[inline(never)]
fn runtime_engine_init_pcie() -> Result<u16, u16> {
    PCIE_RUNTIME_STATE.with_mut(|state| {
        pcie_runtime_init(state)
            .then_some(FAULT_NONE)
            .ok_or(FAULT_DEVICE_UNAVAILABLE)
    })
}

fn descriptor_resource_range_count(descriptor: &DriverRuntimeInitDescriptor) -> usize {
    usize::from(descriptor.resource_range_count).min(DRIVER_RUNTIME_INIT_MAX_RESOURCE_RANGES)
}

fn descriptor_bus_link_count(descriptor: &DriverRuntimeInitDescriptor) -> usize {
    usize::from(descriptor.bus_link_count).min(DRIVER_RUNTIME_INIT_MAX_BUS_LINKS)
}

fn descriptor_valid_resource_ranges(descriptor: &DriverRuntimeInitDescriptor) -> bool {
    if usize::from(descriptor.resource_range_count) > DRIVER_RUNTIME_INIT_MAX_RESOURCE_RANGES {
        return false;
    }
    let mut index = 0usize;
    while index < descriptor_resource_range_count(descriptor) {
        if !descriptor.resource_ranges[index].valid() {
            return false;
        }
        index += 1;
    }
    true
}

fn descriptor_valid_bus_links(descriptor: &DriverRuntimeInitDescriptor) -> bool {
    if usize::from(descriptor.bus_link_count) > DRIVER_RUNTIME_INIT_MAX_BUS_LINKS {
        return false;
    }
    let mut index = 0usize;
    while index < descriptor_bus_link_count(descriptor) {
        if !descriptor.bus_links[index].valid() {
            return false;
        }
        index += 1;
    }
    true
}

fn descriptor_valid_ref(descriptor: &DriverRuntimeInitDescriptor) -> bool {
    if descriptor.magic != DRIVER_RUNTIME_INIT_MAGIC
        || descriptor.version != DRIVER_RUNTIME_INIT_VERSION
        || descriptor.len as usize != core::mem::size_of::<DriverRuntimeInitDescriptor>()
        || descriptor.hot_path < HOT_PATH_SERIAL_CONSOLE
        || descriptor.hot_path > HOT_PATH_PCIE_ROOT
        || descriptor.role_bit == 0
        || (descriptor.flags & DRIVER_RUNTIME_INIT_REQUIRED_FLAGS)
            != DRIVER_RUNTIME_INIT_REQUIRED_FLAGS
        || descriptor.shared_page_count == 0
        || usize::from(descriptor.mmio_page_count) > DRIVER_RUNTIME_INIT_MAX_MMIO_PAGES
        || usize::from(descriptor.dma_page_count) > DRIVER_RUNTIME_INIT_MAX_DMA_PAGES
        || usize::from(descriptor.shared_page_count) > DRIVER_RUNTIME_INIT_MAX_SHARED_PAGES
        || usize::from(descriptor.irq_count) > DRIVER_RUNTIME_INIT_MAX_IRQS
        || usize::from(descriptor.bus_link_count) > DRIVER_RUNTIME_INIT_MAX_BUS_LINKS
        || usize::from(descriptor.resource_range_count) > DRIVER_RUNTIME_INIT_MAX_RESOURCE_RANGES
    {
        return false;
    }
    if descriptor.irq_count == 0 {
        if descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY == 0 {
            return false;
        }
    } else if descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_IRQS_BOUND == 0 {
        return false;
    }
    if descriptor.bus_link_count != 0 && descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_BUS_LINKS == 0
    {
        return false;
    }
    descriptor_valid_resource_ranges(descriptor) && descriptor_valid_bus_links(descriptor)
}

fn descriptor_resource_pages_by_kind(descriptor: &DriverRuntimeInitDescriptor, kind: u16) -> u16 {
    let mut total = 0u16;
    let mut index = 0usize;
    while index < descriptor_resource_range_count(descriptor) {
        let range = descriptor.resource_ranges[index];
        if range.kind == kind {
            total = total.saturating_add(range.page_count);
        }
        index += 1;
    }
    total
}

fn descriptor_resource_pages_or_count(
    descriptor: &DriverRuntimeInitDescriptor,
    kind: u16,
    fallback: u16,
) -> u16 {
    let pages = descriptor_resource_pages_by_kind(descriptor, kind);
    if pages == 0 {
        fallback
    } else {
        pages
    }
}

fn descriptor_has_resource_range_at(
    descriptor: &DriverRuntimeInitDescriptor,
    kind: u16,
    tag: u32,
    expected_vaddr: u64,
    min_pages: u16,
) -> bool {
    let mut index = 0usize;
    while index < descriptor_resource_range_count(descriptor) {
        let range = descriptor.resource_ranges[index];
        if range.kind == kind
            && range.tag == tag
            && range.vaddr == expected_vaddr
            && range.page_count >= min_pages
        {
            return true;
        }
        index += 1;
    }
    false
}

fn descriptor_has_resource_range(
    descriptor: &DriverRuntimeInitDescriptor,
    kind: u16,
    tag: u32,
) -> bool {
    let mut index = 0usize;
    while index < descriptor_resource_range_count(descriptor) {
        let range = descriptor.resource_ranges[index];
        if range.kind == kind && range.tag == tag && range.page_count != 0 {
            return true;
        }
        index += 1;
    }
    false
}

fn descriptor_has_pointer_free_bus_link(
    descriptor: &DriverRuntimeInitDescriptor,
    owner_hot_path: u32,
    channel_id: u32,
) -> bool {
    let mut index = 0usize;
    while index < descriptor_bus_link_count(descriptor) {
        let link = descriptor.bus_links[index];
        if link.owner_hot_path == owner_hot_path
            && link.channel_id == channel_id
            && link.flags & DRIVER_RUNTIME_BUS_LINK_FLAG_POINTER_FREE != 0
        {
            return true;
        }
        index += 1;
    }
    false
}

fn descriptor_hdmi_ready(descriptor: &DriverRuntimeInitDescriptor) -> bool {
    descriptor_valid_ref(descriptor)
        && descriptor.hot_path == HOT_PATH_HDMI_TEXT
        && descriptor.flags & DRIVER_RUNTIME_INIT_FLAG_FRAMEBUFFER != 0
        && descriptor.framebuffer.valid()
}

fn publish_resource_check_progress(progress: Option<(u32, u32)>, phase: u32) {
    if let Some((sequence, aux0)) = progress {
        publish_runtime_progress(sequence, phase, aux0);
    }
}

fn descriptor_resources_ready_with_progress(
    descriptor: &DriverRuntimeInitDescriptor,
    hot_path: u32,
    sequence: u32,
    aux0: u32,
) -> bool {
    descriptor_resources_ready_checked(descriptor, hot_path, Some((sequence, aux0)))
}

fn descriptor_resources_ready(descriptor: &DriverRuntimeInitDescriptor, hot_path: u32) -> bool {
    descriptor_resources_ready_checked(descriptor, hot_path, None)
}

fn descriptor_resources_ready_checked(
    descriptor: &DriverRuntimeInitDescriptor,
    hot_path: u32,
    progress: Option<(u32, u32)>,
) -> bool {
    if !descriptor_valid_ref(descriptor) {
        publish_resource_check_progress(
            progress,
            DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DESCRIPTOR_INVALID,
        );
        return false;
    }
    publish_resource_check_progress(
        progress,
        DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DESCRIPTOR_VALID,
    );
    if descriptor.hot_path != hot_path {
        publish_resource_check_progress(
            progress,
            DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_MISMATCH,
        );
        return false;
    }
    publish_resource_check_progress(
        progress,
        DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_READY,
    );
    let mmio_pages = descriptor_resource_pages_or_count(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
        descriptor.mmio_page_count,
    );
    let dma_pages = descriptor_resource_pages_or_count(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        descriptor.dma_page_count,
    );
    let shared_pages = descriptor_resource_pages_or_count(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_SHARED,
        descriptor.shared_page_count,
    );
    publish_resource_check_progress(progress, DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_TOTALS_READY);
    match hot_path {
        HOT_PATH_USB_KEYBOARD => {
            if mmio_pages < USB_REQUIRED_MMIO_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_TAG_USB_XHCI,
                    DRIVER_TASK_DEVICE_MMIO_VADDR as u64,
                    USB_REQUIRED_MMIO_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if dma_pages < USB_REQUIRED_DMA_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_DMA,
                    DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
                    DRIVER_TASK_DMA_BUFFER_VADDR as u64,
                    USB_REQUIRED_DMA_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_READY,
            );
            if shared_pages < USB_REQUIRED_SHARED_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            if !descriptor_has_pointer_free_bus_link(
                descriptor,
                HOT_PATH_PCIE_ROOT,
                DRIVER_RUNTIME_BUS_LINK_CHANNEL_USB_PCIE,
            ) {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_BUS_LINK_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_BUS_LINK_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        HOT_PATH_HDMI_TEXT => {
            if mmio_pages < HDMI_REQUIRED_MMIO_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if dma_pages < HDMI_REQUIRED_DMA_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_READY,
            );
            if shared_pages < HDMI_REQUIRED_SHARED_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            if !descriptor_hdmi_ready(descriptor)
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_FRAMEBUFFER,
                    DRIVER_RUNTIME_RESOURCE_TAG_HDMI_FRAMEBUFFER,
                    DRIVER_RUNTIME_FRAMEBUFFER_VADDR,
                    1,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_FRAMEBUFFER_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_FRAMEBUFFER_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        HOT_PATH_GENET_NIC => {
            if mmio_pages < GENET_REQUIRED_MMIO_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_TAG_GENET_REGS,
                    DRIVER_TASK_DEVICE_MMIO_VADDR as u64,
                    GENET_REQUIRED_MMIO_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if dma_pages < GENET_REQUIRED_DMA_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_DMA,
                    DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
                    DRIVER_TASK_DMA_BUFFER_VADDR as u64,
                    GENET_REQUIRED_DMA_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_READY,
            );
            if shared_pages < GENET_REQUIRED_SHARED_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        HOT_PATH_CYW43_WIFI => {
            if mmio_pages < CYW43_REQUIRED_MMIO_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if dma_pages < CYW43_REQUIRED_DMA_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_READY,
            );
            if shared_pages < CYW43_REQUIRED_SHARED_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_SHARED,
                    DRIVER_RUNTIME_RESOURCE_TAG_CYW43_CONTROL,
                    DRIVER_TASK_SHARED_BUFFER_VADDR as u64,
                    CYW43_REQUIRED_SHARED_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            if descriptor_has_resource_range(
                descriptor,
                DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                DRIVER_RUNTIME_RESOURCE_TAG_SDIO_HOST,
            ) {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_FORBIDDEN_PRESENT,
                );
                return false;
            }
            if !descriptor_has_pointer_free_bus_link(
                descriptor,
                HOT_PATH_SDIO_HOST,
                DRIVER_RUNTIME_BUS_LINK_CHANNEL_CYW43_SDIO,
            ) {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_BUS_LINK_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_BUS_LINK_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        HOT_PATH_SDIO_HOST => {
            if mmio_pages < SDIO_REQUIRED_MMIO_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_TAG_SDIO_HOST,
                    DRIVER_TASK_DEVICE_MMIO_VADDR as u64,
                    SDIO_REQUIRED_MMIO_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if dma_pages < SDIO_REQUIRED_DMA_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_DMA_READY,
            );
            if shared_pages < SDIO_REQUIRED_SHARED_PAGES {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        HOT_PATH_PCIE_ROOT => {
            if mmio_pages < PCIE_REQUIRED_MMIO_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
                    DRIVER_RUNTIME_RESOURCE_TAG_PCIE_HOST,
                    DRIVER_TASK_DEVICE_MMIO_VADDR as u64,
                    PCIE_REQUIRED_MMIO_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_MMIO_READY,
            );
            if shared_pages < PCIE_REQUIRED_SHARED_PAGES
                || !descriptor_has_resource_range_at(
                    descriptor,
                    DRIVER_RUNTIME_RESOURCE_KIND_SHARED,
                    DRIVER_RUNTIME_RESOURCE_TAG_SHARED_CONTROL,
                    DRIVER_TASK_SHARED_BUFFER_VADDR as u64,
                    PCIE_REQUIRED_SHARED_PAGES,
                )
            {
                publish_resource_check_progress(
                    progress,
                    DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_MISSING,
                );
                return false;
            }
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_SHARED_READY,
            );
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_ROLE_READY,
            );
            true
        }
        _ => {
            publish_resource_check_progress(
                progress,
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_MISMATCH,
            );
            false
        }
    }
}

fn engine_initialized(flags: &AtomicU32) -> bool {
    flags.load(Ordering::Acquire) & ENGINE_STATE_INITIALIZED != 0
}

fn runtime_resource_range(
    descriptor: &DriverRuntimeInitDescriptor,
    kind: u16,
    tag: u32,
) -> Option<DriverRuntimeResourceRangeDescriptor> {
    let mut index = 0usize;
    while index < descriptor.resource_range_count as usize {
        let range = descriptor.resource_ranges[index];
        if range.kind == kind && range.tag == tag {
            return Some(range);
        }
        index += 1;
    }
    None
}

fn runtime_shared_buffer_bytes(descriptor: &DriverRuntimeInitDescriptor) -> usize {
    let mut index = 0usize;
    while index < descriptor.resource_range_count as usize {
        let range = descriptor.resource_ranges[index];
        if range.kind == DRIVER_RUNTIME_RESOURCE_KIND_SHARED
            && range.vaddr == DRIVER_TASK_SHARED_BUFFER_VADDR as u64
        {
            return range.bytes.min(usize::MAX as u64) as usize;
        }
        index += 1;
    }
    0
}

fn runtime_bus_addr(descriptor: &DriverRuntimeInitDescriptor, paddr: u64) -> u64 {
    (paddr & descriptor.bus_alias_and) | descriptor.bus_alias_or
}

fn runtime_resource_paddr_at(
    descriptor: &DriverRuntimeInitDescriptor,
    range: DriverRuntimeResourceRangeDescriptor,
    offset: usize,
) -> Option<u64> {
    let page = offset / DRIVER_TASK_RING_PAGE_BYTES;
    if page >= usize::from(range.page_count) {
        return None;
    }
    let page_offset = offset % DRIVER_TASK_RING_PAGE_BYTES;
    if range.flags & DRIVER_RUNTIME_RESOURCE_FLAG_PADDR_CONTIGUOUS != 0 {
        return range.paddr.checked_add(offset as u64);
    }
    let index = usize::from(range.first_page_index).checked_add(page)?;
    let paddr = match range.kind {
        DRIVER_RUNTIME_RESOURCE_KIND_DMA => descriptor.dma_pages.get(index)?.paddr,
        DRIVER_RUNTIME_RESOURCE_KIND_SHARED => descriptor.shared_pages.get(index)?.paddr,
        DRIVER_RUNTIME_RESOURCE_KIND_MMIO => descriptor.mmio_pages.get(index)?.paddr,
        _ => 0,
    };
    if paddr == 0 {
        return None;
    }
    paddr.checked_add(page_offset as u64)
}

fn runtime_resource_bus_addr_at(
    descriptor: &DriverRuntimeInitDescriptor,
    range: DriverRuntimeResourceRangeDescriptor,
    offset: usize,
) -> Option<u64> {
    runtime_resource_paddr_at(descriptor, range, offset)
        .map(|paddr| runtime_bus_addr(descriptor, paddr))
}

fn ring_slot(index: u16, slots: usize) -> usize {
    if slots == 0 {
        0
    } else {
        usize::from(index) % slots
    }
}

fn ring_distance(newer: u16, older: u16) -> u16 {
    newer.wrapping_sub(older)
}

const fn genet_rx_owned_len_status() -> u32 {
    ((GENET_RX_BUF_LENGTH as u32) << GENET_DMA_BUFLENGTH_SHIFT) | GENET_DMA_OWN
}

const fn genet_tx_len_status(len: usize) -> u32 {
    ((len as u32) << GENET_DMA_BUFLENGTH_SHIFT)
        | (GENET_DMA_DEFAULT_QTAG << GENET_DMA_TX_QTAG_SHIFT)
        | GENET_DMA_TX_APPEND_CRC
        | GENET_DMA_SOP
        | GENET_DMA_EOP
}

const fn genet_decode_rx_len(len_status: u32) -> usize {
    ((len_status >> GENET_DMA_BUFLENGTH_SHIFT) & GENET_DMA_BUFLENGTH_MASK) as usize
}

const fn genet_ring_end_addr(ring_descs: usize) -> u32 {
    let words = ring_descs.saturating_mul(GENET_DMA_DESC_SIZE) / 4;
    words.saturating_sub(1) as u32
}

const fn genet_ring_buffer_size(ring_descs: usize) -> u32 {
    ((ring_descs as u32) << GENET_DMA_RING_SIZE_SHIFT) | GENET_RX_BUF_LENGTH as u32
}

const fn genet_dma_fc_thresh_value(ring_descs: usize) -> u32 {
    (GENET_DMA_FC_THRESH_LO << 16) | ((ring_descs as u32) >> 4)
}

const fn genet_rx_desc_offset(slot: usize) -> Option<usize> {
    match slot.checked_mul(GENET_DMA_DESC_SIZE) {
        Some(offset) => GENET_RX_OFF.checked_add(offset),
        None => None,
    }
}

const fn genet_tx_desc_offset(slot: usize) -> Option<usize> {
    match slot.checked_mul(GENET_DMA_DESC_SIZE) {
        Some(offset) => GENET_TX_OFF.checked_add(offset),
        None => None,
    }
}

#[inline(never)]
fn service_engine_init(command: DriverTaskCommandRecord) -> Option<DriverTaskCompletionRecord> {
    let init_aux = command_is_engine_init_aux(command.aux0);
    if !init_aux {
        return None;
    }
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_ENTER,
        command.aux0,
    );
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_AUX_MATCH,
        command.aux0,
    );
    if command.opcode != OPCODE_SERVICE {
        return Some(DriverTaskCompletionRecord::fault(
            command.sequence,
            FAULT_REJECTED_COMMAND,
        ));
    }
    if command.frame.len != 0 {
        return Some(DriverTaskCompletionRecord::fault(
            command.sequence,
            FAULT_REJECTED_COMMAND,
        ));
    }
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_FRAME_READY,
        command.aux0,
    );
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_BEGIN,
        command.aux0,
    );
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_MARK_ENTER,
        command.aux0,
    );
    match mark_engine_initialized(command) {
        Ok(detail) => {
            publish_runtime_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_DONE,
                command.aux0,
            );
            Some(DriverTaskCompletionRecord::progress_with_detail(
                command.sequence,
                detail,
                1,
            ))
        }
        Err(detail) => Some(DriverTaskCompletionRecord::fault(command.sequence, detail)),
    }
}

fn service_serial(command: DriverTaskCommandRecord) -> DriverTaskCompletionRecord {
    if command.aux0 == SERIAL_RUNTIME_AUX_INIT {
        SERIAL_RUNTIME_RX_QUEUE.with_mut(SerialRuntimeRxQueue::reset);
        serial_init_mini_uart();
        return DriverTaskCompletionRecord::progress(command.sequence, 1);
    }
    if command.frame.len == 0 {
        let limit = command
            .budget
            .max_bytes
            .min(MAX_DRIVER_TASK_FRAME_BYTES as u32)
            .min(MINI_UART_RX_DRAIN_LIMIT as u32) as usize;
        let read = serial_read_frame(limit);
        return if read == 0 {
            DriverTaskCompletionRecord::idle(command.sequence)
        } else {
            DriverTaskCompletionRecord::frame_ready(command.sequence, read as u16)
        };
    }
    if !command.frame.in_ring_payload() {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    serial_preserve_rx_into_runtime_queue(MINI_UART_RX_DRAIN_LIMIT);
    let limit = serial_frame_budget_limit(command.budget, command.frame.len);
    let written = serial_write_frame(command.frame, limit);
    serial_preserve_rx_into_runtime_queue(MINI_UART_RX_DRAIN_LIMIT);
    if written == 0 {
        DriverTaskCompletionRecord::idle(command.sequence)
    } else {
        DriverTaskCompletionRecord::progress(command.sequence, written as u32)
    }
}

fn serial_frame_budget_limit(budget: DriverTaskBudgetGrant, frame_len: u16) -> usize {
    if budget.max_ops == 0 || budget.max_frames == 0 || budget.max_bytes == 0 {
        return 0;
    }
    (budget.max_ops as usize)
        .min(budget.max_bytes as usize)
        .min(frame_len as usize)
        .min(MAX_DRIVER_TASK_FRAME_BYTES)
}

#[inline(never)]
fn usb_runtime_init(
    sequence: u32,
    aux0: u32,
    descriptor: &DriverRuntimeInitDescriptor,
) -> Option<u16> {
    publish_runtime_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_USB_INIT_ENTRY, aux0);
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_USB_STATE_ACCESS_BEGIN,
        aux0,
    );
    let detail = USB_RUNTIME_STATE.with_mut(|state| {
        if state.initialized {
            if state.keyboard_slot != 0 && state.keyboard_endpoint_id != 0 {
                state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_KEYBOARD_READY;
                return Some(DRIVER_RUNTIME_USB_INIT_DETAIL_KEYBOARD_READY);
            }
            return usb_runtime_enumeration_detail(state).or(Some(state.init_detail));
        }
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_STATE_RESET_BEGIN,
            aux0,
        );
        state.reset();
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_USB_STATE_RESET_DONE,
            aux0,
        );
        publish_runtime_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_USB_HW_ENTRY, aux0);
        let detail = usb_runtime_init_hw(sequence, aux0, descriptor, state)?;
        state.initialized = true;
        Some(detail)
    });
    if detail.is_some() {
        USB_RUNTIME_FLAGS.fetch_or(
            ENGINE_STATE_INITIALIZED | ENGINE_STATE_HW_READY,
            Ordering::AcqRel,
        );
    }
    detail
}

fn genet_runtime_init(state: &mut GenetRuntimeState) -> bool {
    state.reset();
    RUNTIME_DESCRIPTOR.with_ref(|descriptor| {
        let Some(dma_range) = runtime_resource_range(
            descriptor,
            DRIVER_RUNTIME_RESOURCE_KIND_DMA,
            DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
        ) else {
            return false;
        };
        if dma_range.page_count < GENET_REQUIRED_DMA_PAGES {
            return false;
        }
        let initialized = genet_runtime_init_hw(descriptor, state);
        state.initialized = initialized;
        initialized
    })
}

fn service_genet_runtime(command: DriverTaskCommandRecord) -> DriverTaskCompletionRecord {
    if let Some(completion) = service_engine_init(command) {
        return completion;
    }
    if !engine_initialized(&GENET_RUNTIME_FLAGS) {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    if command.frame.len == 0 {
        return match GENET_RUNTIME_STATE
            .with_mut(|state| genet_runtime_poll_rx(state, command.budget))
        {
            GenetRxPoll::Idle => DriverTaskCompletionRecord::idle(command.sequence),
            GenetRxPoll::Frame(read) => {
                GENET_RX_COUNT.fetch_add(1, Ordering::AcqRel);
                GENET_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_RX_PROGRESS, Ordering::AcqRel);
                DriverTaskCompletionRecord::frame_ready(command.sequence, read as u16)
            }
            GenetRxPoll::BudgetExhausted(detail) => {
                DriverTaskCompletionRecord::budget_exhausted(command.sequence, detail)
            }
        };
    }
    if !command.frame.in_ring_payload() {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if let Err(detail) = genet_tx_budget_allows_frame(command.budget, command.frame.len) {
        return DriverTaskCompletionRecord::budget_exhausted(command.sequence, detail);
    }
    let written =
        GENET_RUNTIME_STATE.with_mut(|state| genet_runtime_submit_tx(state, command.frame));
    if written == 0 {
        DriverTaskCompletionRecord::idle(command.sequence)
    } else {
        GENET_TX_COUNT.fetch_add(1, Ordering::AcqRel);
        GENET_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_TX_PROGRESS, Ordering::AcqRel);
        DriverTaskCompletionRecord::progress(command.sequence, written as u32)
    }
}

fn cyw43_runtime_init(
    sequence: u32,
    aux0: u32,
    state: &mut Cyw43RuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
) -> bool {
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_STATE_RESET_BEGIN,
        aux0,
    );
    state.reset();
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_STATE_RESET_DONE,
        aux0,
    );
    let has_direct_sdio_mmio = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
        DRIVER_RUNTIME_RESOURCE_TAG_SDIO_HOST,
    )
    .is_some();
    if has_direct_sdio_mmio {
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_CYW43_FORBIDDEN_SDIO_MMIO,
            aux0,
        );
        return false;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_BUS_LINK_CHECK_BEGIN,
        aux0,
    );
    state.bus_link_ready = descriptor.has_pointer_free_bus_link(
        HOT_PATH_SDIO_HOST,
        DRIVER_RUNTIME_BUS_LINK_CHANNEL_CYW43_SDIO,
    );
    if !state.bus_link_ready {
        return false;
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_BUS_LINK_READY,
        aux0,
    );
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_SHARED_CONTROL_CHECK_BEGIN,
        aux0,
    );
    state.initialized = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_SHARED,
        DRIVER_RUNTIME_RESOURCE_TAG_CYW43_CONTROL,
    )
    .is_some();
    publish_runtime_progress(
        sequence,
        if state.initialized {
            DRIVER_RUNTIME_RING_PROGRESS_CYW43_SHARED_CONTROL_READY
        } else {
            DRIVER_RUNTIME_RING_PROGRESS_CYW43_SHARED_CONTROL_MISSING
        },
        aux0,
    );
    #[cfg(all(not(target_os = "none"), not(test)))]
    {
        if state.initialized {
            state.transport_ready = cyw43_transport_init(state).is_ok();
        }
    }
    state.initialized
}

fn service_cyw43_runtime(command: DriverTaskCommandRecord) -> DriverTaskCompletionRecord {
    if let Some(completion) = service_engine_init(command) {
        return completion;
    }
    if !engine_initialized(&CYW43_RUNTIME_FLAGS) {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    if command.aux0 == DRIVER_RUNTIME_CYW43_COMMAND_AUX {
        return service_cyw43_descriptor_command(command);
    }
    if command.frame.len == 0 {
        let produced = CYW43_RUNTIME_STATE
            .with_mut(|state| cyw43_runtime_poll_rx(state, CYW43_RX_FRAME_FLAG_MASK_DATA));
        return if let Some(frame) = produced {
            CYW43_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_RX_PROGRESS, Ordering::AcqRel);
            DriverTaskCompletionRecord::frame_ready_with_descriptor(command.sequence, frame)
        } else {
            DriverTaskCompletionRecord::idle(command.sequence)
        };
    }
    if !command.frame.in_ring_payload() {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    let encoded = CYW43_RUNTIME_STATE.with_mut(|state| cyw43_stage_sdpcm_tx(state, command.frame));
    if encoded == 0 {
        DriverTaskCompletionRecord::idle(command.sequence)
    } else {
        CYW43_TX_COUNT.fetch_add(1, Ordering::AcqRel);
        CYW43_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_TX_PROGRESS, Ordering::AcqRel);
        DriverTaskCompletionRecord::progress(command.sequence, encoded as u32)
    }
}

fn service_usb_keyboard(command: DriverTaskCommandRecord) -> DriverTaskCompletionRecord {
    if let Some(completion) = service_engine_init(command) {
        return completion;
    }
    if !engine_initialized(&USB_RUNTIME_FLAGS) {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    if command.aux0 == DRIVER_RUNTIME_USB_ENUMERATE_AUX {
        let status = USB_RUNTIME_STATE.with_mut(|state| {
            state.enumeration_retry_cooldown = 0;
            let detail =
                usb_runtime_retry_keyboard_enumeration(command.sequence, command.aux0, state)
                    .or(Some(state.init_detail));
            detail.map(|detail| (detail, usb_runtime_enumeration_result(state)))
        });
        return match status {
            Some((detail, result)) => {
                DriverTaskCompletionRecord::progress_with_detail(command.sequence, detail, result)
            }
            None => DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE),
        };
    }
    if command.frame.len == 0 {
        let produced = USB_RUNTIME_STATE.with_mut(usb_runtime_poll_keyboard);
        return if produced == 0 {
            if USB_RUNTIME_STATE.with_mut(usb_keyboard_endpoint_ready) {
                let result = USB_RUNTIME_STATE.with_mut(usb_keyboard_pending_result);
                let detail = if usb_keyboard_pending_result_has_transfer_event(result) {
                    DRIVER_RUNTIME_USB_SERVICE_DETAIL_FIRST_REPORT_READY
                } else {
                    DRIVER_RUNTIME_USB_SERVICE_DETAIL_FIRST_REPORT_PENDING
                };
                DriverTaskCompletionRecord::progress_with_detail(command.sequence, detail, result)
            } else if let Some((detail, result)) =
                USB_RUNTIME_STATE.with_mut(usb_runtime_enumeration_status)
            {
                DriverTaskCompletionRecord::progress_with_detail(command.sequence, detail, result)
            } else {
                DriverTaskCompletionRecord::idle(command.sequence)
            }
        } else {
            USB_RUNTIME_STATE.with_mut(|state| {
                state.reports = state.reports.saturating_add(1);
            });
            USB_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_RX_PROGRESS, Ordering::AcqRel);
            DriverTaskCompletionRecord::frame_ready(command.sequence, produced as u16)
        };
    }
    #[cfg(not(test))]
    {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    #[cfg(test)]
    {
        if !command.frame.in_ring_payload() || command.frame.len as usize != USB_BOOT_REPORT_BYTES {
            return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
        }
        let report = read_frame_prefix::<USB_BOOT_REPORT_BYTES>(command.frame);
        let produced =
            USB_RUNTIME_STATE.with_mut(|state| usb_keyboard_report_bytes_to_frame(state, report));
        if produced == 0 {
            DriverTaskCompletionRecord::idle(command.sequence)
        } else {
            USB_RUNTIME_STATE.with_mut(|state| {
                state.reports = state.reports.saturating_add(1);
            });
            USB_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_RX_PROGRESS, Ordering::AcqRel);
            DriverTaskCompletionRecord::frame_ready(command.sequence, produced as u16)
        }
    }
}

fn service_hdmi_text(command: DriverTaskCommandRecord) -> DriverTaskCompletionRecord {
    if command_is_engine_init_aux(command.aux0) {
        if let Some(completion) = service_engine_init(command) {
            return completion;
        }
    }
    publish_runtime_progress(
        command.sequence,
        DRIVER_RUNTIME_RING_PROGRESS_HDMI_FRAME_BEGIN,
        command.aux0,
    );
    if !engine_initialized(&HDMI_RUNTIME_FLAGS) {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_HDMI_FRAME_FAILED,
            command.aux0,
        );
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    if command.frame.len == 0 {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_HDMI_FRAME_FAILED,
            command.aux0,
        );
        return DriverTaskCompletionRecord::idle(command.sequence);
    }
    if !command.frame.in_ring_payload() {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_HDMI_FRAME_FAILED,
            command.aux0,
        );
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if RUNTIME_INIT_HOT_PATH.load(Ordering::Acquire) != HOT_PATH_HDMI_TEXT {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_HDMI_FRAME_FAILED,
            command.aux0,
        );
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    if !RUNTIME_DESCRIPTOR.with_ref(|descriptor| descriptor.hdmi_ready()) {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_HDMI_FRAME_FAILED,
            command.aux0,
        );
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    let rendered = hdmi_render_frame(command.frame);
    if rendered == 0 {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_HDMI_FRAME_FAILED,
            command.aux0,
        );
        DriverTaskCompletionRecord::idle(command.sequence)
    } else {
        publish_runtime_progress(
            command.sequence,
            DRIVER_RUNTIME_RING_PROGRESS_HDMI_FRAME_DONE,
            command.aux0,
        );
        HDMI_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_TX_PROGRESS, Ordering::AcqRel);
        DriverTaskCompletionRecord::progress(command.sequence, rendered as u32)
    }
}

fn service_sdio_host(command: DriverTaskCommandRecord) -> DriverTaskCompletionRecord {
    if let Some(completion) = service_engine_init(command) {
        return completion;
    }
    if !engine_initialized(&SDIO_RUNTIME_FLAGS) {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    if command.frame.len != 0 && !command.frame.in_ring_payload() {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if command.frame.len as usize == core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>() {
        return service_sdio_descriptor_command(command);
    }
    let command_index = (command.aux0 >> 16) & 0x3f;
    let flags = (command.aux0 & 0xffff) as u16;
    let data_len = command.frame.len as u32;
    if command_index > 63 {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if data_len != 0 && flags & DRIVER_RUNTIME_SDIO_FLAG_DATA == 0 {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if flags & DRIVER_RUNTIME_SDIO_FLAG_WRITE != 0 && data_len == 0 {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if sdio_response_flag_count(flags) != 1 {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    let Some(response0) =
        sdio_execute_command(command_index as u16, command.aux1, flags, command.frame)
    else {
        let result = sdio_last_transfer_failure();
        let transfer_mode = sdio_transfer_mode_from_flags(
            flags,
            if flags & DRIVER_RUNTIME_SDIO_FLAG_DATA != 0 {
                1
            } else {
                0
            },
        );
        let frame = sdio_write_fault_telemetry_frame(
            command_index as u16,
            command.aux1,
            flags,
            command.frame.len,
            command.frame.len.max(1),
            if flags & DRIVER_RUNTIME_SDIO_FLAG_DATA != 0 {
                1
            } else {
                0
            },
            transfer_mode,
            result,
            command.frame,
        );
        sdio_recover_command_path();
        return DriverTaskCompletionRecord::fault_with_result_and_frame(
            command.sequence,
            FAULT_SDIO_COMMAND_UNAVAILABLE,
            result,
            frame,
        );
    };
    SDIO_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_TX_PROGRESS, Ordering::AcqRel);
    SDIO_CMD_COUNT.fetch_add(1, Ordering::AcqRel);
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.commands = state.commands.saturating_add(1);
        state.last_response = response0;
    });
    if data_len != 0 && flags & DRIVER_RUNTIME_SDIO_FLAG_WRITE == 0 {
        DriverTaskCompletionRecord::frame_ready(command.sequence, command.frame.len)
    } else if data_len != 0 {
        DriverTaskCompletionRecord::progress(command.sequence, data_len)
    } else {
        DriverTaskCompletionRecord::progress(command.sequence, response0)
    }
}

fn service_sdio_descriptor_command(command: DriverTaskCommandRecord) -> DriverTaskCompletionRecord {
    let Some(desc) = read_sdio_command_descriptor(command.frame) else {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    };
    if !desc.valid() {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    if desc.op == DRIVER_RUNTIME_SDIO_OP_HOST_CONFIG {
        if sdio_apply_host_config(desc.addr, desc.flags) {
            return DriverTaskCompletionRecord::progress(command.sequence, 1);
        }
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_SDIO_HOST_CONFIG_FAILED);
    }
    if desc.op == DRIVER_RUNTIME_SDIO_OP_CARD_COMMAND {
        let cmd = desc.len;
        let flags = sdio_descriptor_response_flags(desc.response_kind);
        let frame = DriverFrameDescriptor::empty();
        sdio_clear_last_transfer_failure();
        let Some(response0) = sdio_execute_transfer(cmd, desc.addr, flags, frame, 1, 0) else {
            let result = sdio_last_transfer_failure();
            let telemetry =
                sdio_write_fault_telemetry_frame(cmd, desc.addr, flags, 0, 1, 0, 0, result, frame);
            sdio_recover_command_path();
            return DriverTaskCompletionRecord::fault_with_result_and_frame(
                command.sequence,
                FAULT_SDIO_COMMAND_UNAVAILABLE,
                result,
                telemetry,
            );
        };
        SDIO_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_TX_PROGRESS, Ordering::AcqRel);
        SDIO_CMD_COUNT.fetch_add(1, Ordering::AcqRel);
        SDIO_RUNTIME_STATE.with_mut(|state| {
            state.commands = state.commands.saturating_add(1);
            state.last_response = response0;
        });
        return DriverTaskCompletionRecord::progress(command.sequence, response0);
    }
    let mut frame = DriverFrameDescriptor {
        offset: u32::from(desc.data_offset),
        len: desc.len,
        flags: 0,
    };
    if desc.block_count != 0 {
        let bytes = u32::from(desc.block_count).saturating_mul(u32::from(desc.block_size));
        if bytes > u32::from(u16::MAX) {
            return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
        }
        frame.len = bytes as u16;
    }
    let shared_payload_bytes = RUNTIME_DESCRIPTOR.with_ref(runtime_shared_buffer_bytes);
    if frame.len != 0 && !frame.in_runtime_payload(shared_payload_bytes) {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    let flags = sdio_descriptor_response_flags(desc.response_kind)
        | match desc.op {
            DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE => {
                DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_WRITE
            }
            DRIVER_RUNTIME_SDIO_OP_CMD53_READ => DRIVER_RUNTIME_SDIO_FLAG_DATA,
            _ => 0,
        };
    let (cmd, arg) = match desc.op {
        DRIVER_RUNTIME_SDIO_OP_CMD52_READ => {
            (52, sdio_cmd52_arg(false, desc.function, desc.addr, 0))
        }
        DRIVER_RUNTIME_SDIO_OP_CMD52_WRITE => {
            let value = if desc.len == 0 {
                0
            } else {
                read_runtime_payload_byte(usize::from(desc.data_offset))
            };
            (52, sdio_cmd52_arg(true, desc.function, desc.addr, value))
        }
        DRIVER_RUNTIME_SDIO_OP_CMD53_READ | DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE => (
            53,
            sdio_cmd53_arg(
                desc.op == DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE,
                desc.function,
                desc.addr,
                desc.flags & DriverRuntimeSdioCommandDescriptor::FLAG_INCREMENT != 0,
                desc.block_count,
                desc.len,
            ),
        ),
        DRIVER_RUNTIME_SDIO_OP_POLL_IRQ => (52, sdio_cmd52_arg(false, 0, 0x05, 0)),
        _ => return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND),
    };
    let block_size = if desc.block_count == 0 {
        frame.len.max(1)
    } else {
        desc.block_size
    };
    let block_count = sdio_descriptor_host_block_count(desc.block_count, flags);
    sdio_clear_last_transfer_failure();
    let response0 =
        sdio_execute_transfer(cmd, arg, flags, frame, block_size, block_count).or_else(|| {
            if !sdio_descriptor_transfer_retryable(desc, cmd, flags) {
                return None;
            }
            sdio_recover_command_path();
            sdio_execute_transfer(cmd, arg, flags, frame, block_size, block_count)
        });
    let Some(response0) = response0 else {
        let result = sdio_last_transfer_failure();
        let transfer_mode = sdio_transfer_mode_from_flags(flags, block_count);
        let telemetry = sdio_write_fault_telemetry_frame(
            cmd,
            arg,
            flags,
            frame.len,
            block_size,
            block_count,
            transfer_mode,
            result,
            frame,
        );
        sdio_recover_command_path();
        return DriverTaskCompletionRecord::fault_with_result_and_frame(
            command.sequence,
            FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED,
            result,
            telemetry,
        );
    };
    SDIO_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_TX_PROGRESS, Ordering::AcqRel);
    SDIO_CMD_COUNT.fetch_add(1, Ordering::AcqRel);
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.commands = state.commands.saturating_add(1);
        state.last_response = response0;
    });
    match desc.op {
        DRIVER_RUNTIME_SDIO_OP_CMD52_READ | DRIVER_RUNTIME_SDIO_OP_POLL_IRQ => {
            write_runtime_payload_byte(usize::from(desc.data_offset), (response0 & 0xff) as u8);
            DriverTaskCompletionRecord::frame_ready_at(
                command.sequence,
                u32::from(desc.data_offset),
                1,
            )
        }
        DRIVER_RUNTIME_SDIO_OP_CMD53_READ => {
            DriverTaskCompletionRecord::frame_ready_at(command.sequence, frame.offset, frame.len)
        }
        DRIVER_RUNTIME_SDIO_OP_CMD52_WRITE | DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE => {
            DriverTaskCompletionRecord::progress(command.sequence, u32::from(frame.len))
        }
        _ => DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND),
    }
}

fn sdio_descriptor_transfer_retryable(
    desc: DriverRuntimeSdioCommandDescriptor,
    cmd: u16,
    flags: u16,
) -> bool {
    cmd == SDIO_CMD53
        && desc.op == DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE
        && matches!(desc.function, 1 | 2)
        && flags & (DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_WRITE)
            == (DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_WRITE)
}

fn read_sdio_command_descriptor(
    frame: DriverFrameDescriptor,
) -> Option<DriverRuntimeSdioCommandDescriptor> {
    if !frame.in_ring_payload()
        || frame.len as usize != core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>()
    {
        return None;
    }
    let offset = frame.offset as usize;
    driver_task_shared_invalidate_range(
        DRIVER_TASK_RING_VADDR + offset,
        core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>(),
    );
    driver_task_shared_load_barrier();
    Some(DriverRuntimeSdioCommandDescriptor {
        op: read_ring_u16(offset),
        function: read_ring_byte(offset + 2),
        response_kind: read_ring_byte(offset + 3),
        addr: read_ring_u32(offset + 4),
        data_offset: read_ring_u16(offset + 8),
        len: read_ring_u16(offset + 10),
        block_size: read_ring_u16(offset + 12),
        block_count: read_ring_u16(offset + 14),
        flags: read_ring_u16(offset + 16),
        reserved: read_ring_u16(offset + 18),
        timeout_us: read_ring_u32(offset + 20),
    })
}

fn read_cyw43_command_descriptor(
    frame: DriverFrameDescriptor,
) -> Option<DriverRuntimeCyw43CommandDescriptor> {
    if !frame.in_ring_payload()
        || frame.len as usize != core::mem::size_of::<DriverRuntimeCyw43CommandDescriptor>()
    {
        return None;
    }
    let offset = frame.offset as usize;
    driver_task_shared_invalidate_range(
        DRIVER_TASK_RING_VADDR + offset,
        core::mem::size_of::<DriverRuntimeCyw43CommandDescriptor>(),
    );
    driver_task_shared_load_barrier();
    Some(DriverRuntimeCyw43CommandDescriptor {
        op: read_ring_u16(offset),
        flags: read_ring_u16(offset + 2),
        target_addr: read_ring_u32(offset + 4),
        payload_offset: read_ring_u16(offset + 8),
        payload_len: read_ring_u16(offset + 10),
        total_len: read_ring_u32(offset + 12),
        arg0: read_ring_u32(offset + 16),
        arg1: read_ring_u32(offset + 20),
        reserved: read_ring_u32(offset + 24),
    })
}

fn cyw43_descriptor_invalid_result(desc: DriverRuntimeCyw43CommandDescriptor) -> u32 {
    let known_op = desc.op == DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT
        || desc.op == DRIVER_RUNTIME_CYW43_OP_FIRMWARE_PREP
        || desc.op == DRIVER_RUNTIME_CYW43_OP_FIRMWARE_CHUNK
        || desc.op == DRIVER_RUNTIME_CYW43_OP_NVRAM_CHUNK
        || desc.op == DRIVER_RUNTIME_CYW43_OP_NVRAM_TAIL
        || desc.op == DRIVER_RUNTIME_CYW43_OP_RELEASE
        || desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME
        || desc.op == DRIVER_RUNTIME_CYW43_OP_ETH_TX
        || desc.op == DRIVER_RUNTIME_CYW43_OP_RX_POLL
        || desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL
        || desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE;
    let known_flags = match desc.op {
        DRIVER_RUNTIME_CYW43_OP_FIRMWARE_CHUNK => {
            desc.flags & !DRIVER_RUNTIME_CYW43_FLAG_FORCE_BYTE_MODE == 0
        }
        DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME | DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE => {
            desc.flags & !DRIVER_RUNTIME_CYW43_FLAG_CONTROL_EXT_HEADER == 0
        }
        DRIVER_RUNTIME_CYW43_OP_RX_POLL | DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL => {
            desc.flags & !DRIVER_RUNTIME_CYW43_FLAG_RX_HINTLESS_FIRSTREAD == 0
        }
        _ => desc.flags == 0,
    };
    let bulk_stream_payload = desc.op == DRIVER_RUNTIME_CYW43_OP_FIRMWARE_CHUNK
        || desc.op == DRIVER_RUNTIME_CYW43_OP_NVRAM_CHUNK;
    let carries_payload = bulk_stream_payload
        || desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME
        || desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE
        || desc.op == DRIVER_RUNTIME_CYW43_OP_ETH_TX;
    let zero_payload = desc.op == DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT
        || desc.op == DRIVER_RUNTIME_CYW43_OP_FIRMWARE_PREP
        || desc.op == DRIVER_RUNTIME_CYW43_OP_NVRAM_TAIL
        || desc.op == DRIVER_RUNTIME_CYW43_OP_RELEASE
        || desc.op == DRIVER_RUNTIME_CYW43_OP_RX_POLL
        || desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL;
    let payload_end = u32::from(desc.payload_offset).saturating_add(u32::from(desc.payload_len));
    let ring_payload = usize::from(desc.payload_offset) >= DRIVER_TASK_RING_FRAME_OFFSET
        && payload_end <= DRIVER_TASK_RING_PAGE_BYTES as u32;
    let shared_payload = desc.payload_offset == DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE
        && payload_end
            <= u32::from(DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE)
                + u32::from(DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES);
    let payload_ok = (carries_payload
        && desc.payload_len != 0
        && (ring_payload || (bulk_stream_payload && shared_payload)))
        || (zero_payload && desc.payload_len == 0);
    let total_len_ok = desc.total_len == 0 || desc.total_len >= u32::from(desc.payload_len);
    let mut result = 0u32;
    if !known_op {
        result |= CYW43_DESCRIPTOR_INVALID_OP;
    }
    if !known_flags {
        result |= CYW43_DESCRIPTOR_INVALID_FLAGS;
    }
    if !payload_ok {
        result |= CYW43_DESCRIPTOR_INVALID_PAYLOAD;
    }
    if !total_len_ok {
        result |= CYW43_DESCRIPTOR_INVALID_TOTAL_LEN;
    }
    result
}

fn cyw43_stream_next_bytes(
    current_bytes: u32,
    current_total_len: u32,
    expected_total_len: u32,
    payload_len: u16,
    logical_payload_len: u16,
    allow_padded_tail: bool,
) -> Option<u32> {
    if expected_total_len == 0 {
        return None;
    }
    if current_total_len != 0 && current_total_len != expected_total_len {
        return None;
    }
    let payload_bytes = u32::from(payload_len);
    let logical_bytes = u32::from(logical_payload_len);
    if logical_bytes == 0 || logical_bytes > payload_bytes {
        return None;
    }
    let next_bytes = current_bytes.checked_add(logical_bytes)?;
    if payload_bytes == logical_bytes && next_bytes <= expected_total_len {
        return Some(next_bytes);
    }
    if !allow_padded_tail || next_bytes != expected_total_len {
        return None;
    }
    if usize::from(payload_len) > CYW43_FIRMWARE_TAIL_PAD_MAX_BYTES {
        return None;
    }
    let pad_align = SDIO_CMD53_BYTE_MODE_MAX as u32;
    let padded_remaining = logical_bytes.checked_add(pad_align - 1)? / pad_align * pad_align;
    (payload_bytes == padded_remaining).then_some(expected_total_len)
}

fn cyw43_stream_logical_payload_len(payload_len: u16, descriptor_logical_len: u32) -> Option<u16> {
    if descriptor_logical_len == 0 {
        Some(payload_len)
    } else {
        u16::try_from(descriptor_logical_len)
            .ok()
            .filter(|len| *len != 0 && *len <= payload_len)
    }
}

fn cyw43_runtime_payload_tail_zero(
    payload_offset: usize,
    logical_payload_len: u16,
    payload_len: u16,
) -> bool {
    for index in usize::from(logical_payload_len)..usize::from(payload_len) {
        if read_runtime_payload_byte(payload_offset + index) != 0 {
            return false;
        }
    }
    true
}

const fn cyw43_transport_progress_result(detail: u16) -> u32 {
    if detail == DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_READY {
        1
    } else {
        0
    }
}

#[cfg(target_os = "none")]
fn cyw43_active_parent_sequence() -> u32 {
    CYW43_ACTIVE_PARENT_SEQUENCE.load(Ordering::Acquire)
}

#[cfg(any(target_os = "none", test))]
const fn cyw43_sdio_owner_progress_sequence(parent_sequence: u32, owner_sequence: u32) -> u32 {
    if parent_sequence != 0 {
        parent_sequence
    } else {
        owner_sequence
    }
}

fn service_cyw43_descriptor_command(
    command: DriverTaskCommandRecord,
) -> DriverTaskCompletionRecord {
    let Some(desc) = read_cyw43_command_descriptor(command.frame) else {
        return DriverTaskCompletionRecord::fault(
            command.sequence,
            FAULT_CYW43_DESCRIPTOR_UNAVAILABLE,
        );
    };
    if !desc.valid() {
        return DriverTaskCompletionRecord::fault_with_result(
            command.sequence,
            FAULT_CYW43_DESCRIPTOR_INVALID,
            cyw43_descriptor_invalid_result(desc),
        );
    }
    cyw43_clear_last_fault();
    let mut exact_fault = None;
    let mut frame_ready = None;
    let mut progress_detail = None;
    let mut rx_idle_reason = None;
    let previous_parent_sequence =
        CYW43_ACTIVE_PARENT_SEQUENCE.swap(command.sequence, Ordering::AcqRel);
    let result = CYW43_RUNTIME_STATE.with_mut(|state| match desc.op {
        DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT => {
            cyw43_transport_init_command(command.sequence, command.aux0, state).map_or_else(
                |detail| {
                    exact_fault = Some(detail);
                    0
                },
                |detail| {
                    progress_detail = Some(detail);
                    cyw43_transport_progress_result(detail)
                },
            )
        }
        DRIVER_RUNTIME_CYW43_OP_FIRMWARE_PREP => cyw43_prepare_firmware_upload_transport(state)
            .map_or_else(
                |detail| {
                    exact_fault = Some(detail);
                    0
                },
                |()| 1,
            ),
        DRIVER_RUNTIME_CYW43_OP_FIRMWARE_CHUNK => {
            let expected_total = desc.total_len.max(u32::from(desc.payload_len));
            let logical_payload_len =
                cyw43_stream_logical_payload_len(desc.payload_len, desc.arg0).unwrap_or(0);
            if let Some(next_bytes) = cyw43_stream_next_bytes(
                state.firmware_bytes,
                state.firmware_total_len,
                expected_total,
                desc.payload_len,
                logical_payload_len,
                true,
            ) {
                if !cyw43_ram_payload_bounds(desc.target_addr, desc.payload_len) {
                    cyw43_record_firmware_range_fault(CYW43_FIRMWARE_RANGE_RAM);
                    0
                } else if !cyw43_runtime_payload_tail_zero(
                    usize::from(desc.payload_offset),
                    logical_payload_len,
                    desc.payload_len,
                ) {
                    cyw43_record_firmware_range_fault(CYW43_FIRMWARE_RANGE_TAIL);
                    0
                } else if !state.firmware_upload_prepared {
                    cyw43_record_last_fault(FAULT_CYW43_FIRMWARE_PREP);
                    0
                } else if cyw43_stage_firmware_chunk(
                    state,
                    desc.target_addr,
                    usize::from(desc.payload_offset),
                    usize::from(desc.payload_len),
                    next_bytes == expected_total,
                    desc.flags & DRIVER_RUNTIME_CYW43_FLAG_FORCE_BYTE_MODE != 0,
                ) {
                    if state.firmware_total_len == 0 {
                        state.firmware_total_len = expected_total;
                    }
                    state.firmware_bytes = next_bytes;
                    state.firmware_uploaded = state.firmware_bytes == state.firmware_total_len;
                    u32::from(desc.payload_len)
                } else {
                    0
                }
            } else {
                cyw43_record_firmware_range_fault(CYW43_FIRMWARE_RANGE_STREAM);
                0
            }
        }
        DRIVER_RUNTIME_CYW43_OP_NVRAM_CHUNK => {
            let expected_total = desc.total_len.max(u32::from(desc.payload_len));
            if let Some(next_bytes) = cyw43_stream_next_bytes(
                state.nvram_bytes,
                state.nvram_total_len,
                expected_total,
                desc.payload_len,
                desc.payload_len,
                false,
            ) {
                if !cyw43_ram_payload_bounds(desc.target_addr, desc.payload_len) {
                    cyw43_record_firmware_range_fault(CYW43_FIRMWARE_RANGE_RAM);
                    0
                } else if !state.firmware_upload_prepared {
                    cyw43_record_last_fault(FAULT_CYW43_FIRMWARE_PREP);
                    0
                } else if cyw43_stage_firmware_chunk(
                    state,
                    desc.target_addr,
                    usize::from(desc.payload_offset),
                    usize::from(desc.payload_len),
                    true,
                    false,
                ) {
                    if state.nvram_total_len == 0 {
                        state.nvram_total_len = expected_total;
                    }
                    state.nvram_bytes = next_bytes;
                    state.nvram_uploaded = state.nvram_bytes == state.nvram_total_len;
                    u32::from(desc.payload_len)
                } else {
                    0
                }
            } else {
                cyw43_record_firmware_range_fault(CYW43_FIRMWARE_RANGE_STREAM);
                0
            }
        }
        DRIVER_RUNTIME_CYW43_OP_NVRAM_TAIL => {
            if !state.firmware_upload_prepared {
                cyw43_record_last_fault(FAULT_CYW43_FIRMWARE_PREP);
                0
            } else if cyw43_ram_payload_bounds(desc.target_addr, 4)
                && cyw43_backplane_write_u32(state, desc.target_addr, desc.arg0)
            {
                state.nvram_tail_uploaded = true;
                state.nvram_tail_magic = desc.arg0;
                4
            } else {
                0
            }
        }
        DRIVER_RUNTIME_CYW43_OP_RELEASE => {
            if state.firmware_stage_len != 0 && !cyw43_flush_firmware_stage(state) {
                0
            } else if cyw43_release_firmware(state, desc.arg0, command.sequence) {
                state.firmware_released = true;
                1
            } else {
                0
            }
        }
        DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME => {
            let frame = DriverFrameDescriptor {
                offset: u32::from(desc.payload_offset),
                len: desc.payload_len,
                flags: 0,
            };
            cyw43_publish_control_rx_progress(
                command.sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_TX_BEGIN,
            );
            let written = cyw43_submit_sdpcm_frame(
                state,
                frame,
                false,
                desc.flags & DRIVER_RUNTIME_CYW43_FLAG_CONTROL_EXT_HEADER != 0,
            );
            if written != 0 {
                cyw43_publish_control_rx_progress(
                    command.sequence,
                    DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_TX_DONE,
                );
            }
            written as u32
        }
        DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE => {
            let frame = DriverFrameDescriptor {
                offset: u32::from(desc.payload_offset),
                len: desc.payload_len,
                flags: 0,
            };
            frame_ready = cyw43_control_exchange(
                state,
                frame,
                desc.flags & DRIVER_RUNTIME_CYW43_FLAG_CONTROL_EXT_HEADER != 0,
                desc.arg0,
                desc.arg1 as u16,
                command.sequence,
            );
            frame_ready.map_or(0, |frame| u32::from(frame.len).saturating_add(1))
        }
        DRIVER_RUNTIME_CYW43_OP_ETH_TX => {
            let frame = DriverFrameDescriptor {
                offset: u32::from(desc.payload_offset),
                len: desc.payload_len,
                flags: 0,
            };
            cyw43_submit_sdpcm_frame(state, frame, true, false) as u32
        }
        DRIVER_RUNTIME_CYW43_OP_RX_POLL => {
            match cyw43_runtime_poll_rx_detailed(
                state,
                CYW43_RX_FRAME_FLAG_MASK_DATA,
                command.sequence,
                desc.flags & DRIVER_RUNTIME_CYW43_FLAG_RX_HINTLESS_FIRSTREAD != 0,
            ) {
                Cyw43RxPollResult::Frame(frame) => {
                    frame_ready = Some(frame);
                    u32::from(frame.len)
                }
                Cyw43RxPollResult::Idle(reason) => {
                    rx_idle_reason = Some(reason);
                    0
                }
            }
        }
        DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL => {
            match cyw43_runtime_poll_rx_detailed(
                state,
                CYW43_RX_FRAME_FLAG_MASK_CONTROL_EVENT,
                command.sequence,
                desc.flags & DRIVER_RUNTIME_CYW43_FLAG_RX_HINTLESS_FIRSTREAD != 0,
            ) {
                Cyw43RxPollResult::Frame(frame) => {
                    frame_ready = Some(frame);
                    u32::from(frame.len)
                }
                Cyw43RxPollResult::Idle(reason) => {
                    rx_idle_reason = Some(reason);
                    0
                }
            }
        }
        _ => 0,
    });
    CYW43_ACTIVE_PARENT_SEQUENCE.store(previous_parent_sequence, Ordering::Release);
    if let Some(detail) = exact_fault {
        let fault_result = cyw43_take_last_fault_result();
        let frame = cyw43_take_last_fault_frame();
        if frame.len == 0 && fault_result == 0 {
            DriverTaskCompletionRecord::fault(command.sequence, detail)
        } else if frame.len == 0 {
            DriverTaskCompletionRecord::fault_with_result(command.sequence, detail, fault_result)
        } else {
            DriverTaskCompletionRecord::fault_with_result_and_frame(
                command.sequence,
                detail,
                fault_result,
                frame,
            )
        }
    } else if let Some(detail) = progress_detail {
        DriverTaskCompletionRecord::progress_with_detail(command.sequence, detail, result)
    } else if result == 0
        && (desc.op == DRIVER_RUNTIME_CYW43_OP_RX_POLL
            || desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL)
    {
        if desc.flags & DRIVER_RUNTIME_CYW43_FLAG_RX_HINTLESS_FIRSTREAD != 0 {
            let reason = rx_idle_reason.unwrap_or(Cyw43RxIdleReason::NoRframe);
            DriverTaskCompletionRecord::idle_with_detail(
                command.sequence,
                cyw43_rx_idle_detail(reason),
                cyw43_rx_idle_result(reason),
            )
        } else {
            DriverTaskCompletionRecord::idle(command.sequence)
        }
    } else if result == 0
        && ((desc.op == DRIVER_RUNTIME_CYW43_OP_ETH_TX && cyw43_take_last_fault_detail().is_none())
            || (desc.op == DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME
                && cyw43_take_last_fault_detail().is_none()))
    {
        DriverTaskCompletionRecord::idle(command.sequence)
    } else if result == 0 {
        let detail =
            cyw43_take_last_fault_detail().unwrap_or_else(|| cyw43_command_fault_detail(desc.op));
        let fault_result = cyw43_take_last_fault_result();
        let frame = cyw43_take_last_fault_frame();
        if frame.len == 0 {
            DriverTaskCompletionRecord::fault_with_result(command.sequence, detail, fault_result)
        } else {
            DriverTaskCompletionRecord::fault_with_result_and_frame(
                command.sequence,
                detail,
                fault_result,
                frame,
            )
        }
    } else if let Some(frame) = frame_ready {
        DriverTaskCompletionRecord::frame_ready_with_descriptor(command.sequence, frame)
    } else {
        DriverTaskCompletionRecord::progress(command.sequence, result)
    }
}

fn cyw43_clear_last_fault() {
    CYW43_LAST_FAULT_DETAIL.store(FAULT_NONE as u32, Ordering::Release);
    CYW43_LAST_FAULT_RESULT.store(0, Ordering::Release);
    CYW43_LAST_FAULT_FRAME_OFFSET.store(0, Ordering::Release);
    CYW43_LAST_FAULT_FRAME_META.store(0, Ordering::Release);
}

fn cyw43_record_last_fault(detail: u16) {
    cyw43_record_last_fault_with_result(detail, 0);
}

fn cyw43_record_last_fault_with_result(detail: u16, result: u32) {
    if detail != FAULT_NONE {
        CYW43_LAST_FAULT_DETAIL.store(u32::from(detail), Ordering::Release);
        CYW43_LAST_FAULT_RESULT.store(result, Ordering::Release);
    }
}

fn cyw43_record_firmware_range_fault(result: u32) {
    cyw43_record_last_fault_with_result(FAULT_CYW43_FIRMWARE_RANGE, result);
}

fn cyw43_record_last_fault_frame(frame: DriverFrameDescriptor) {
    if frame.len == 0 {
        return;
    }
    let meta = u32::from(frame.len) | (u32::from(frame.flags) << 16);
    CYW43_LAST_FAULT_FRAME_OFFSET.store(frame.offset, Ordering::Release);
    CYW43_LAST_FAULT_FRAME_META.store(meta, Ordering::Release);
}

fn cyw43_take_last_fault_detail() -> Option<u16> {
    let detail = CYW43_LAST_FAULT_DETAIL.load(Ordering::Acquire) as u16;
    (detail != FAULT_NONE).then_some(detail)
}

fn cyw43_take_last_fault_result() -> u32 {
    CYW43_LAST_FAULT_RESULT.load(Ordering::Acquire)
}

fn cyw43_take_last_fault_frame() -> DriverFrameDescriptor {
    let meta = CYW43_LAST_FAULT_FRAME_META.load(Ordering::Acquire);
    let len = (meta & 0xffff) as u16;
    if len == 0 {
        DriverFrameDescriptor::empty()
    } else {
        DriverFrameDescriptor {
            offset: CYW43_LAST_FAULT_FRAME_OFFSET.load(Ordering::Acquire),
            len,
            flags: (meta >> 16) as u16,
        }
    }
}

const fn cyw43_command_fault_detail(op: u16) -> u16 {
    match op {
        DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT => FAULT_CYW43_TRANSPORT_INIT,
        DRIVER_RUNTIME_CYW43_OP_FIRMWARE_PREP => FAULT_CYW43_FIRMWARE_PREP,
        DRIVER_RUNTIME_CYW43_OP_FIRMWARE_CHUNK => FAULT_CYW43_FIRMWARE_CHUNK,
        DRIVER_RUNTIME_CYW43_OP_NVRAM_CHUNK => FAULT_CYW43_NVRAM_CHUNK,
        DRIVER_RUNTIME_CYW43_OP_NVRAM_TAIL => FAULT_CYW43_NVRAM_TAIL,
        DRIVER_RUNTIME_CYW43_OP_RELEASE => FAULT_CYW43_RELEASE,
        DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME => FAULT_CYW43_CONTROL_FRAME,
        DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE => FAULT_CYW43_CONTROL_EXCHANGE,
        DRIVER_RUNTIME_CYW43_OP_ETH_TX => FAULT_CYW43_ETH_TX,
        _ => FAULT_CYW43_COMMAND,
    }
}

const fn sdio_descriptor_response_flags(response_kind: u8) -> u16 {
    match response_kind {
        DRIVER_RUNTIME_SDIO_RESP_NONE => DRIVER_RUNTIME_SDIO_FLAG_RESP_NONE,
        DRIVER_RUNTIME_SDIO_RESP_OCR => DRIVER_RUNTIME_SDIO_FLAG_RESP_OCR,
        DRIVER_RUNTIME_SDIO_RESP_SHORT => DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        DRIVER_RUNTIME_SDIO_RESP_SHORT_BUSY => DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT_BUSY,
        DRIVER_RUNTIME_SDIO_RESP_LONG => DRIVER_RUNTIME_SDIO_FLAG_RESP_LONG,
        _ => 0,
    }
}

const fn sdio_cmd52_arg(write: bool, function: u8, addr: u32, value: u8) -> u32 {
    (if write { 1 << 31 } else { 0 })
        | ((function as u32 & 0x7) << 28)
        | ((addr & 0x1ffff) << 9)
        | value as u32
}

const fn sdio_cmd53_arg(
    write: bool,
    function: u8,
    addr: u32,
    increment: bool,
    block_count: u16,
    len: u16,
) -> u32 {
    let block_mode = block_count != 0;
    let count = if block_mode { block_count } else { len };
    (if write { 1 << 31 } else { 0 })
        | ((function as u32 & 0x7) << 28)
        | (if block_mode { 1 << 27 } else { 0 })
        | (if increment { 1 << 26 } else { 0 })
        | ((addr & 0x1ffff) << 9)
        | ((count as u32) & 0x1ff)
}

fn sdio_response_flag_count(flags: u16) -> u32 {
    let response_flags = flags
        & (DRIVER_RUNTIME_SDIO_FLAG_RESP_NONE
            | DRIVER_RUNTIME_SDIO_FLAG_RESP_OCR
            | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT
            | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT_BUSY
            | DRIVER_RUNTIME_SDIO_FLAG_RESP_LONG);
    response_flags.count_ones()
}

const fn sdio_response_kind_from_flags(flags: u16) -> Option<u8> {
    if flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_NONE != 0 {
        Some(DRIVER_RUNTIME_SDIO_RESP_NONE)
    } else if flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_OCR != 0 {
        Some(DRIVER_RUNTIME_SDIO_RESP_OCR)
    } else if flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT != 0 {
        Some(DRIVER_RUNTIME_SDIO_RESP_SHORT)
    } else if flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT_BUSY != 0 {
        Some(DRIVER_RUNTIME_SDIO_RESP_SHORT_BUSY)
    } else if flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_LONG != 0 {
        Some(DRIVER_RUNTIME_SDIO_RESP_LONG)
    } else {
        None
    }
}

const fn sdio_command_waits_for_data_inhibit(flags: u16, has_data: bool) -> bool {
    has_data || flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT_BUSY != 0
}

const SDIO_TRANSFER_FAILURE_STAGE_INHIBIT: u32 = 1;
const SDIO_TRANSFER_FAILURE_STAGE_COMMAND: u32 = 2;
const SDIO_TRANSFER_FAILURE_STAGE_DATA_WAIT: u32 = 3;
const SDIO_TRANSFER_FAILURE_STAGE_DATA_END: u32 = 4;
const SDIO_TRANSFER_FAILURE_STAGE_RESPONSE: u32 = 5;

const fn sdio_transfer_failure_result(stage: u32, status: u32) -> u32 {
    ((stage & 0xff) << 24) | (status & 0x00ff_ffff)
}

fn sdio_clear_last_transfer_failure() {
    SDIO_LAST_TRANSFER_FAILURE.store(0, Ordering::Release);
}

fn sdio_record_transfer_failure(stage: u32, status: u32) {
    SDIO_LAST_TRANSFER_FAILURE.store(
        sdio_transfer_failure_result(stage, status),
        Ordering::Release,
    );
}

fn sdio_last_transfer_failure() -> u32 {
    SDIO_LAST_TRANSFER_FAILURE.load(Ordering::Acquire)
}

const fn sdio_transfer_mode_from_flags(flags: u16, block_count: u16) -> u16 {
    let mut transfer = 0;
    if flags & DRIVER_RUNTIME_SDIO_FLAG_DATA != 0 {
        transfer |= SDHCI_TRNS_BLK_CNT_EN;
        if flags & DRIVER_RUNTIME_SDIO_FLAG_WRITE == 0 {
            transfer |= SDHCI_TRNS_READ;
        }
        if block_count > 1 {
            transfer |= SDHCI_TRNS_MULTI;
        }
    }
    transfer
}

const fn sdio_descriptor_host_block_count(desc_block_count: u16, flags: u16) -> u16 {
    if flags & DRIVER_RUNTIME_SDIO_FLAG_DATA != 0 && desc_block_count == 0 {
        1
    } else {
        desc_block_count
    }
}

fn sdio_write_fault_telemetry_frame(
    cmd: u16,
    arg: u32,
    flags: u16,
    len: u16,
    block_size: u16,
    block_count: u16,
    transfer_mode: u16,
    failure_result: u32,
    payload_frame: DriverFrameDescriptor,
) -> DriverFrameDescriptor {
    let offset = SDIO_FAULT_TELEMETRY_FRAME_OFFSET;
    let (payload_edge, payload_sum) = sdio_fault_payload_digest(flags, payload_frame);
    write_ring_u32(offset, SDIO_FAULT_TELEMETRY_MAGIC);
    write_ring_u32(offset + 4, SDIO_FAULT_TELEMETRY_VERSION);
    write_ring_u32(offset + SDIO_FAULT_TELEMETRY_ARG_OFFSET, arg);
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_CMD_FLAGS_OFFSET,
        u32::from(cmd) | (u32::from(flags) << 16),
    );
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_LEN_BLOCK_OFFSET,
        u32::from(len) | (u32::from(block_size) << 16),
    );
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_COUNT_MODE_OFFSET,
        u32::from(block_count) | (u32::from(transfer_mode) << 16),
    );
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_PRESENT_OFFSET,
        sdio_read32(SDHCI_PRESENT_STATE),
    );
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_INT_STATUS_OFFSET,
        sdio_read32(SDHCI_INT_STATUS),
    );
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_RESPONSE0_OFFSET,
        sdio_read32(SDHCI_RESPONSE),
    );
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_HOST_CLOCK_OFFSET,
        u32::from(sdio_read8(SDHCI_HOST_CONTROL))
            | (u32::from(sdio_read8(SDHCI_POWER_CONTROL)) << 8)
            | (u32::from(sdio_read16(SDHCI_CLOCK_CONTROL)) << 16),
    );
    write_ring_u32(offset + SDIO_FAULT_TELEMETRY_FAILURE_OFFSET, failure_result);
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_BLOCK_REG_OFFSET,
        sdio_read32(SDHCI_BLOCK_SIZE),
    );
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_PAYLOAD_EDGE_OFFSET,
        payload_edge,
    );
    write_ring_u32(
        offset + SDIO_FAULT_TELEMETRY_PAYLOAD_SUM_OFFSET,
        payload_sum,
    );
    DriverFrameDescriptor {
        offset: offset as u32,
        len: SDIO_FAULT_TELEMETRY_BYTES,
        flags: 0,
    }
}

fn sdio_fault_payload_digest(flags: u16, frame: DriverFrameDescriptor) -> (u32, u32) {
    if flags & DRIVER_RUNTIME_SDIO_FLAG_DATA == 0
        || flags & DRIVER_RUNTIME_SDIO_FLAG_WRITE == 0
        || frame.len == 0
    {
        return (0, 0);
    }
    let len = usize::from(frame.len);
    let mut first = 0u8;
    let mut last = 0u8;
    let mut xor = 0u8;
    let mut sum = 0u32;
    let mut index = 0usize;
    while index < len {
        let byte = read_runtime_payload_byte(frame.offset as usize + index);
        if index == 0 {
            first = byte;
        }
        last = byte;
        xor ^= byte;
        sum = sum.wrapping_add(u32::from(byte));
        index = index.saturating_add(1);
    }
    (
        u32::from(first) | (u32::from(last) << 8) | (u32::from(xor) << 16),
        sum,
    )
}

const fn sdio_r5_status(response: u32) -> u32 {
    response & 0xcb00
}

const fn sdio_cmd53_arg_write(arg: u32) -> bool {
    arg & (1 << 31) != 0
}

const fn sdio_cmd53_arg_function(arg: u32) -> u8 {
    ((arg >> 28) & 0x7) as u8
}

const fn sdio_cmd53_arg_addr(arg: u32) -> u32 {
    (arg >> 9) & 0x1ffff
}

const fn sdio_cmd53_arg_is_function1_backplane_write(arg: u32) -> bool {
    sdio_cmd53_arg_write(arg)
        && sdio_cmd53_arg_function(arg) == 1
        && sdio_cmd53_arg_addr(arg) & BACKPLANE_32BIT_FLAG != 0
}

const fn sdio_cmd53_r5_error(cmd: u16, arg: u32, response: u32) -> Option<u32> {
    if cmd != SDIO_CMD53 {
        return None;
    }
    let status = sdio_r5_status(response);
    if status == SDIO_R5_OUT_OF_RANGE && sdio_cmd53_arg_is_function1_backplane_write(arg) {
        return None;
    }
    if status == 0 {
        None
    } else {
        Some(status)
    }
}

#[cfg(target_os = "none")]
fn sdio_execute_command(
    cmd: u16,
    arg: u32,
    flags: u16,
    frame: DriverFrameDescriptor,
) -> Option<u32> {
    sdio_execute_transfer(cmd, arg, flags, frame, frame.len.max(1), 1)
}

#[cfg(target_os = "none")]
fn sdio_execute_transfer(
    cmd: u16,
    arg: u32,
    flags: u16,
    frame: DriverFrameDescriptor,
    block_size: u16,
    block_count: u16,
) -> Option<u32> {
    if cyw43_uses_sdio_bus_link() {
        return sdio_execute_via_bus_link(cmd, arg, flags, frame, block_size, block_count);
    }
    let has_data = flags & DRIVER_RUNTIME_SDIO_FLAG_DATA != 0;
    let write = flags & DRIVER_RUNTIME_SDIO_FLAG_WRITE != 0;
    let short_busy_response = flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT_BUSY != 0;
    if !sdio_wait_inhibit_clear(sdio_command_waits_for_data_inhibit(flags, has_data)) {
        sdio_record_transfer_failure(
            SDIO_TRANSFER_FAILURE_STAGE_INHIBIT,
            sdio_read32(SDHCI_PRESENT_STATE),
        );
        return None;
    }
    sdio_write32(SDHCI_INT_STATUS, SDHCI_INT_COMMAND_DATA_CLEAR_MASK);
    if has_data {
        sdio_write16(SDHCI_BLOCK_SIZE, block_size);
        sdio_write16(SDHCI_BLOCK_COUNT, block_count.max(1));
    } else {
        sdio_write16(SDHCI_TRANSFER_MODE, 0);
    }
    sdio_write32(SDHCI_ARGUMENT, arg);
    if has_data {
        sdio_write16(SDHCI_TRANSFER_MODE, sdio_transfer_mode(write, block_count));
    }
    sdio_write16(SDHCI_COMMAND, sdio_make_command(cmd, flags, has_data));
    let cmd_status = sdio_wait_int(SDHCI_INT_RESPONSE | SDHCI_INT_ERROR);
    if cmd_status & SDHCI_INT_ERROR != 0 || cmd_status == 0 {
        sdio_record_transfer_failure(SDIO_TRANSFER_FAILURE_STAGE_COMMAND, cmd_status);
        return None;
    }
    let response0 = if flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_NONE != 0 {
        0
    } else {
        sdio_read32(SDHCI_RESPONSE)
    };
    if !has_data && short_busy_response && !sdio_wait_inhibit_clear(true) {
        sdio_record_transfer_failure(
            SDIO_TRANSFER_FAILURE_STAGE_INHIBIT,
            sdio_read32(SDHCI_PRESENT_STATE),
        );
        return None;
    }
    if let Some(r5) = sdio_cmd53_r5_error(cmd, arg, response0) {
        sdio_record_transfer_failure(SDIO_TRANSFER_FAILURE_STAGE_RESPONSE, r5);
        return None;
    }
    if has_data && !sdio_transfer_frame(frame, write, block_size) {
        return None;
    }
    Some(response0)
}

#[cfg(target_os = "none")]
fn cyw43_uses_sdio_bus_link() -> bool {
    RUNTIME_INIT_HOT_PATH.load(Ordering::Acquire) == HOT_PATH_CYW43_WIFI
        && RUNTIME_DESCRIPTOR.load().has_pointer_free_bus_link(
            HOT_PATH_SDIO_HOST,
            DRIVER_RUNTIME_BUS_LINK_CHANNEL_CYW43_SDIO,
        )
}

#[cfg(not(target_os = "none"))]
fn cyw43_uses_sdio_bus_link() -> bool {
    false
}

#[cfg(target_os = "none")]
fn sdio_execute_via_bus_link(
    cmd: u16,
    arg: u32,
    flags: u16,
    frame: DriverFrameDescriptor,
    block_size: u16,
    block_count: u16,
) -> Option<u32> {
    if sdio_response_flag_count(flags) != 1 {
        return None;
    }
    let has_data = flags & DRIVER_RUNTIME_SDIO_FLAG_DATA != 0;
    let write = flags & DRIVER_RUNTIME_SDIO_FLAG_WRITE != 0;
    let sequence = CYW43_SDIO_BUS_LINK_SEQ
        .fetch_add(1, Ordering::AcqRel)
        .wrapping_add(1)
        .max(1);
    let command = if has_data {
        let command = sdio_bus_link_descriptor_command(
            sequence,
            cmd,
            arg,
            flags,
            frame,
            block_size,
            block_count,
        )?;
        if write {
            sdio_bus_link_copy_to_owner_payload(frame, CYW43_SDIO_BUS_LINK_DATA_OFFSET)?;
        }
        command
    } else {
        sdio_bus_link_card_command_descriptor_command(sequence, cmd, arg, flags)?
    };
    let completion = sdio_bus_link_call(command)?;
    if completion.sequence != sequence {
        return None;
    }
    if completion.code == COMPLETION_FAULT {
        cyw43_record_last_fault_with_result(completion.detail, completion.result);
        return None;
    }
    if has_data && !write {
        if completion.code != COMPLETION_FRAME_READY
            || !sdio_bus_link_payload_bounds(
                completion.frame.offset as usize,
                completion.frame.len as usize,
            )
        {
            return None;
        }
        let copy_len = usize::from(completion.frame.len).min(usize::from(frame.len));
        sdio_bus_link_copy_from_owner_payload(completion.frame.offset as usize, frame, copy_len)?;
    }
    Some(completion.result)
}

fn cyw43_configure_sdio_host(target_hz: u32, flags: u16) -> bool {
    if !cyw43_uses_sdio_bus_link() {
        return sdio_apply_host_config(target_hz, flags);
    }
    cyw43_configure_sdio_host_via_bus_link(target_hz, flags)
}

#[cfg(target_os = "none")]
fn cyw43_configure_sdio_host_via_bus_link(target_hz: u32, flags: u16) -> bool {
    let sequence = CYW43_SDIO_BUS_LINK_SEQ
        .fetch_add(1, Ordering::AcqRel)
        .wrapping_add(1)
        .max(1);
    let desc = DriverRuntimeSdioCommandDescriptor {
        op: DRIVER_RUNTIME_SDIO_OP_HOST_CONFIG,
        function: 0,
        response_kind: DRIVER_RUNTIME_SDIO_RESP_NONE,
        addr: target_hz,
        data_offset: 0,
        len: 0,
        block_size: 0,
        block_count: 0,
        flags,
        reserved: 0,
        timeout_us: 100_000,
    };
    if !desc.valid() {
        return false;
    }
    sdio_bus_link_write_descriptor(CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET, desc);
    let command = DriverTaskCommandRecord {
        sequence,
        opcode: OPCODE_SERVICE,
        flags: 0,
        arg0: HOT_PATH_SDIO_HOST,
        arg1: ROLE_SDIO,
        aux0: 0,
        aux1: 0,
        budget: DriverTaskBudgetGrant {
            max_ops: 1,
            max_frames: 1,
            max_bytes: 0,
        },
        frame: DriverFrameDescriptor {
            offset: CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET as u32,
            len: core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>() as u16,
            flags: 0,
        },
    };
    sdio_bus_link_call(command).is_some_and(|completion| {
        completion.sequence == sequence
            && completion.code == COMPLETION_PROGRESS
            && completion.result == 1
    })
}

#[cfg(not(target_os = "none"))]
fn cyw43_configure_sdio_host_via_bus_link(_target_hz: u32, _flags: u16) -> bool {
    true
}

#[cfg(target_os = "none")]
const CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET: usize = DRIVER_TASK_RING_FRAME_OFFSET;
#[cfg(target_os = "none")]
const CYW43_SDIO_BUS_LINK_DATA_OFFSET: usize = DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE as usize;
#[cfg(target_os = "none")]
const CYW43_SDIO_BUS_LINK_DATA_BYTES: usize = DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES as usize;
const CYW43_SDIO_BUS_LINK_BASE_ATTEMPTS: usize = 16_384;
const CYW43_SDIO_BUS_LINK_ATTEMPTS_PER_BYTE: usize = 128;
const CYW43_SDIO_BUS_LINK_MAX_ATTEMPTS: usize = 524_288;
const CYW43_SDIO_BUS_LINK_NOTIFY_INTERVAL: usize = 512;

fn cyw43_sdio_bus_link_attempt_limit(command: DriverTaskCommandRecord) -> usize {
    let payload_scaled =
        (command.budget.max_bytes as usize).saturating_mul(CYW43_SDIO_BUS_LINK_ATTEMPTS_PER_BYTE);
    CYW43_SDIO_BUS_LINK_BASE_ATTEMPTS
        .saturating_add(payload_scaled)
        .clamp(
            CYW43_SDIO_BUS_LINK_BASE_ATTEMPTS,
            CYW43_SDIO_BUS_LINK_MAX_ATTEMPTS,
        )
}

#[cfg(target_os = "none")]
fn cyw43_sdio_bus_link_command_result(command: DriverTaskCommandRecord) -> u32 {
    if command.frame.offset as usize != CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET
        || command.frame.len as usize != core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>()
    {
        return (u32::from(command.opcode) << 24)
            | (u32::from(command.arg0 & 0xff) << 16)
            | u32::from(command.frame.len);
    }
    // SAFETY: CYW43 writes this fixed SDIO-owner descriptor immediately before
    // publishing the nested bus-link command; the command frame is checked above.
    let desc = unsafe {
        core::ptr::read_volatile(
            (DRIVER_TASK_SDIO_BUS_RING_VADDR + CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET)
                as *const DriverRuntimeSdioCommandDescriptor,
        )
    };
    (u32::from(desc.op) << 24)
        | (u32::from(desc.function) << 20)
        | (u32::from(desc.flags & 0x0f) << 16)
        | u32::from(desc.len)
}

#[cfg(target_os = "none")]
fn sdio_bus_link_descriptor_command(
    sequence: u32,
    cmd: u16,
    arg: u32,
    flags: u16,
    frame: DriverFrameDescriptor,
    block_size: u16,
    block_count: u16,
) -> Option<DriverTaskCommandRecord> {
    let shared_payload_bytes = RUNTIME_DESCRIPTOR.with_ref(runtime_shared_buffer_bytes);
    if cmd != SDIO_CMD53 || !frame.in_runtime_payload(shared_payload_bytes) || frame.len == 0 {
        return None;
    }
    let response_kind = sdio_response_kind_from_flags(flags)?;
    let write = flags & DRIVER_RUNTIME_SDIO_FLAG_WRITE != 0;
    let block_mode = arg & (1 << 27) != 0;
    let desc = DriverRuntimeSdioCommandDescriptor {
        op: if write {
            DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE
        } else {
            DRIVER_RUNTIME_SDIO_OP_CMD53_READ
        },
        function: ((arg >> 28) & 0x7) as u8,
        response_kind,
        addr: (arg >> 9) & 0x1ffff,
        data_offset: CYW43_SDIO_BUS_LINK_DATA_OFFSET as u16,
        len: frame.len,
        block_size: if block_mode { block_size } else { 0 },
        block_count: if block_mode { block_count } else { 0 },
        flags: if arg & (1 << 26) != 0 {
            DriverRuntimeSdioCommandDescriptor::FLAG_INCREMENT
        } else {
            0
        },
        reserved: 0,
        timeout_us: 100_000,
    };
    if !desc.valid() {
        return None;
    }
    sdio_bus_link_write_descriptor(CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET, desc);
    Some(DriverTaskCommandRecord {
        sequence,
        opcode: OPCODE_SERVICE,
        flags,
        arg0: HOT_PATH_SDIO_HOST,
        arg1: ROLE_SDIO,
        aux0: 0,
        aux1: 0,
        budget: DriverTaskBudgetGrant {
            max_ops: 1,
            max_frames: 1,
            max_bytes: u32::from(frame.len),
        },
        frame: DriverFrameDescriptor {
            offset: CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET as u32,
            len: core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>() as u16,
            flags: 0,
        },
    })
}

#[cfg(target_os = "none")]
fn sdio_bus_link_cmd52_descriptor_command(
    sequence: u32,
    write: bool,
    function: u8,
    addr: u32,
) -> Option<DriverTaskCommandRecord> {
    let desc = DriverRuntimeSdioCommandDescriptor {
        op: if write {
            DRIVER_RUNTIME_SDIO_OP_CMD52_WRITE
        } else {
            DRIVER_RUNTIME_SDIO_OP_CMD52_READ
        },
        function,
        response_kind: DRIVER_RUNTIME_SDIO_RESP_SHORT,
        addr,
        data_offset: CYW43_SDIO_BUS_LINK_DATA_OFFSET as u16,
        len: 1,
        block_size: 0,
        block_count: 0,
        flags: 0,
        reserved: 0,
        timeout_us: 100_000,
    };
    if !desc.valid() {
        return None;
    }
    sdio_bus_link_write_descriptor(CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET, desc);
    Some(DriverTaskCommandRecord {
        sequence,
        opcode: OPCODE_SERVICE,
        flags: DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        arg0: HOT_PATH_SDIO_HOST,
        arg1: ROLE_SDIO,
        aux0: 0,
        aux1: 0,
        budget: DriverTaskBudgetGrant {
            max_ops: 1,
            max_frames: 1,
            max_bytes: 1,
        },
        frame: DriverFrameDescriptor {
            offset: CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET as u32,
            len: core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>() as u16,
            flags: 0,
        },
    })
}

#[cfg(target_os = "none")]
fn sdio_bus_link_card_command_descriptor_command(
    sequence: u32,
    cmd: u16,
    arg: u32,
    flags: u16,
) -> Option<DriverTaskCommandRecord> {
    let response_kind = sdio_response_kind_from_flags(flags)?;
    let desc = DriverRuntimeSdioCommandDescriptor {
        op: DRIVER_RUNTIME_SDIO_OP_CARD_COMMAND,
        function: 0,
        response_kind,
        addr: arg,
        data_offset: 0,
        len: cmd,
        block_size: 0,
        block_count: 0,
        flags: 0,
        reserved: 0,
        timeout_us: 100_000,
    };
    if !desc.valid() {
        return None;
    }
    sdio_bus_link_write_descriptor(CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET, desc);
    Some(DriverTaskCommandRecord {
        sequence,
        opcode: OPCODE_SERVICE,
        flags: 0,
        arg0: HOT_PATH_SDIO_HOST,
        arg1: ROLE_SDIO,
        aux0: 0,
        aux1: 0,
        budget: DriverTaskBudgetGrant {
            max_ops: 1,
            max_frames: 1,
            max_bytes: 0,
        },
        frame: DriverFrameDescriptor {
            offset: CYW43_SDIO_BUS_LINK_DESCRIPTOR_OFFSET as u32,
            len: core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>() as u16,
            flags: 0,
        },
    })
}

#[cfg(target_os = "none")]
fn sdio_bus_link_call(mut command: DriverTaskCommandRecord) -> Option<DriverTaskCompletionRecord> {
    command.flags |= DRIVER_RUNTIME_COMMAND_FLAG_ONE_WAY;
    let completion_reset = DriverTaskCompletionRecord::fault(0, FAULT_REJECTED_COMMAND);
    let attempts = cyw43_sdio_bus_link_attempt_limit(command);
    let progress_sequence =
        cyw43_sdio_owner_progress_sequence(cyw43_active_parent_sequence(), command.sequence);
    publish_runtime_progress(
        progress_sequence,
        pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_CYW43_SDIO_OWNER_SEND_BEGIN,
        DRIVER_RUNTIME_CYW43_COMMAND_AUX,
    );
    // SAFETY: Root maps the SDIO owner command ring into CYW43 at this fixed
    // address and mints the SDIO endpoint cap into the fixed child slot before
    // the CYW43 runtime can be resumed. The bus-link turn publishes one
    // sequence-stamped descriptor, then uses bounded one-way notifications and
    // shared-ring polling so a missed endpoint rendezvous can be retried
    // without moving SDIO ownership back into root.
    unsafe {
        core::ptr::write_volatile(
            (DRIVER_TASK_SDIO_BUS_RING_VADDR + DRIVER_TASK_RING_COMPLETION_OFFSET)
                as *mut DriverTaskCompletionRecord,
            completion_reset,
        );
        core::ptr::write_volatile(
            DRIVER_TASK_SDIO_BUS_RING_VADDR as *mut DriverTaskCommandRecord,
            command,
        );
        driver_task_shared_store_barrier();
        driver_task_shared_clean_range(
            DRIVER_TASK_SDIO_BUS_RING_VADDR,
            core::mem::size_of::<DriverTaskCommandRecord>(),
        );
        driver_task_shared_clean_range(
            DRIVER_TASK_SDIO_BUS_RING_VADDR + DRIVER_TASK_RING_COMPLETION_OFFSET,
            core::mem::size_of::<DriverTaskCompletionRecord>(),
        );
        sel4_sys::seL4_SetMR(0, command.sequence as sel4_sys::seL4_Word);
        let info = sel4_sys::seL4_MessageInfo::new(0, 0, 0, 1);
        sel4_sys::seL4_NBSend(DRIVER_TASK_CHILD_SDIO_BUS_ENDPOINT_SLOT, info);
        publish_runtime_progress(
            progress_sequence,
            pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_CYW43_SDIO_OWNER_SEND_DONE,
            DRIVER_RUNTIME_CYW43_COMMAND_AUX,
        );
        publish_runtime_progress(
            progress_sequence,
            pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_CYW43_SDIO_OWNER_WAIT_BEGIN,
            DRIVER_RUNTIME_CYW43_COMMAND_AUX,
        );
        for attempt in 0..attempts {
            if attempt != 0 && attempt % CYW43_SDIO_BUS_LINK_NOTIFY_INTERVAL == 0 {
                sel4_sys::seL4_SetMR(0, command.sequence as sel4_sys::seL4_Word);
                sel4_sys::seL4_NBSend(DRIVER_TASK_CHILD_SDIO_BUS_ENDPOINT_SLOT, info);
            }
            sel4_sys::seL4_Yield();
            driver_task_shared_invalidate_range(
                DRIVER_TASK_SDIO_BUS_RING_VADDR + DRIVER_TASK_RING_COMPLETION_OFFSET,
                core::mem::size_of::<DriverTaskCompletionRecord>(),
            );
            let observed = core::ptr::read_volatile(
                (DRIVER_TASK_SDIO_BUS_RING_VADDR + DRIVER_TASK_RING_COMPLETION_OFFSET)
                    as *const DriverTaskCompletionRecord,
            );
            if observed.sequence == command.sequence {
                driver_task_shared_load_barrier();
                let mut completion = core::ptr::read_volatile(
                    (DRIVER_TASK_SDIO_BUS_RING_VADDR + DRIVER_TASK_RING_COMPLETION_OFFSET)
                        as *const DriverTaskCompletionRecord,
                );
                if completion.sequence != command.sequence {
                    continue;
                }
                publish_runtime_progress(
                    progress_sequence,
                    pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_CYW43_SDIO_OWNER_REPLY,
                    DRIVER_RUNTIME_CYW43_COMMAND_AUX,
                );
                if completion.code == COMPLETION_FAULT {
                    if let Some(frame) = cyw43_copy_sdio_fault_telemetry(completion.frame) {
                        completion.frame = frame;
                    }
                    cyw43_record_last_fault_with_result(completion.detail, completion.result);
                    cyw43_record_last_fault_frame(completion.frame);
                }
                return Some(completion);
            }
        }
        publish_runtime_progress(
            progress_sequence,
            pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_CYW43_SDIO_OWNER_WAIT_TIMEOUT,
            DRIVER_RUNTIME_CYW43_COMMAND_AUX,
        );
        cyw43_record_last_fault_with_result(
            FAULT_CYW43_TRANSPORT_BUS_LINK,
            cyw43_sdio_bus_link_command_result(command),
        );
        None
    }
}

#[cfg(target_os = "none")]
fn cyw43_copy_sdio_fault_telemetry(frame: DriverFrameDescriptor) -> Option<DriverFrameDescriptor> {
    if frame.len != SDIO_FAULT_TELEMETRY_BYTES || !frame.in_ring_payload() {
        return None;
    }
    driver_task_shared_load_barrier();
    let src = frame.offset as usize;
    for index in 0..usize::from(frame.len) {
        // SAFETY: `frame.in_ring_payload()` bounds-checks the SDIO owner ring
        // frame, and the destination is the CYW43 runtime's own fixed ring
        // payload window reserved for this completion turn.
        let byte = unsafe {
            core::ptr::read_volatile((DRIVER_TASK_SDIO_BUS_RING_VADDR + src + index) as *const u8)
        };
        write_ring_byte(SDIO_FAULT_TELEMETRY_FRAME_OFFSET + index, byte);
    }
    Some(DriverFrameDescriptor {
        offset: SDIO_FAULT_TELEMETRY_FRAME_OFFSET as u32,
        len: frame.len,
        flags: frame.flags,
    })
}

#[cfg(target_os = "none")]
fn sdio_bus_link_write_descriptor(offset: usize, desc: DriverRuntimeSdioCommandDescriptor) {
    // SAFETY: The descriptor offset is page-local, aligned, and reserved for
    // CYW43-to-SDIO bus-link commands in the mapped SDIO owner ring.
    unsafe {
        core::ptr::write_volatile(
            (DRIVER_TASK_SDIO_BUS_RING_VADDR + offset) as *mut DriverRuntimeSdioCommandDescriptor,
            desc,
        );
    }
    driver_task_shared_store_barrier();
    driver_task_shared_clean_range(
        DRIVER_TASK_SDIO_BUS_RING_VADDR + offset,
        core::mem::size_of::<DriverRuntimeSdioCommandDescriptor>(),
    );
}

#[cfg(target_os = "none")]
fn sdio_bus_link_payload_bounds(offset: usize, len: usize) -> bool {
    offset
        .checked_add(len)
        .is_some_and(|end| end <= DRIVER_TASK_RING_PAGE_BYTES + CYW43_SDIO_BUS_LINK_DATA_BYTES)
}

#[cfg(target_os = "none")]
fn read_sdio_bus_payload_byte(offset: usize) -> u8 {
    // SAFETY: Root maps the SDIO owner ring at `DRIVER_TASK_SDIO_BUS_RING_VADDR`
    // and the two-page owner shared data window immediately after it. Callers
    // validate `offset` against that fixed bus-link arena before reading.
    unsafe { core::ptr::read_volatile((DRIVER_TASK_SDIO_BUS_RING_VADDR + offset) as *const u8) }
}

#[cfg(target_os = "none")]
fn write_sdio_bus_payload_byte(offset: usize, value: u8) {
    // SAFETY: Root maps the SDIO owner ring at `DRIVER_TASK_SDIO_BUS_RING_VADDR`
    // and the two-page owner shared data window immediately after it. Callers
    // validate `offset` against that fixed bus-link arena before writing.
    unsafe {
        core::ptr::write_volatile((DRIVER_TASK_SDIO_BUS_RING_VADDR + offset) as *mut u8, value);
    }
}

#[cfg(target_os = "none")]
fn sdio_bus_link_copy_to_owner_payload(
    frame: DriverFrameDescriptor,
    dst_offset: usize,
) -> Option<()> {
    let len = usize::from(frame.len);
    let shared_payload_bytes = RUNTIME_DESCRIPTOR.with_ref(runtime_shared_buffer_bytes);
    if !frame.in_runtime_payload(shared_payload_bytes)
        || !sdio_bus_link_payload_bounds(dst_offset, len)
    {
        return None;
    }
    for index in 0..len {
        write_sdio_bus_payload_byte(
            dst_offset + index,
            read_runtime_payload_byte(frame.offset as usize + index),
        );
    }
    driver_task_shared_store_barrier();
    driver_task_shared_clean_range(DRIVER_TASK_SDIO_BUS_RING_VADDR + dst_offset, len);
    Some(())
}

#[cfg(target_os = "none")]
fn sdio_bus_link_copy_from_owner_payload(
    src_offset: usize,
    frame: DriverFrameDescriptor,
    len: usize,
) -> Option<()> {
    let shared_payload_bytes = RUNTIME_DESCRIPTOR.with_ref(runtime_shared_buffer_bytes);
    let dst_frame = DriverFrameDescriptor {
        offset: frame.offset,
        len: len as u16,
        flags: frame.flags,
    };
    if !frame.in_runtime_payload(shared_payload_bytes)
        || !sdio_bus_link_payload_bounds(src_offset, len)
        || !dst_frame.in_runtime_payload(shared_payload_bytes)
    {
        return None;
    }
    driver_task_shared_invalidate_range(DRIVER_TASK_SDIO_BUS_RING_VADDR + src_offset, len);
    for index in 0..len {
        write_runtime_payload_byte(
            frame.offset as usize + index,
            read_sdio_bus_payload_byte(src_offset + index),
        );
    }
    Some(())
}

const fn sdio_transfer_mode(write: bool, block_count: u16) -> u16 {
    let mut transfer = SDHCI_TRNS_BLK_CNT_EN;
    if !write {
        transfer |= SDHCI_TRNS_READ;
    }
    if block_count > 1 {
        transfer |= SDHCI_TRNS_MULTI;
    }
    transfer
}

const fn sdio_pio_ready_burst_len(block_size: u16, remaining: usize) -> usize {
    let host_window = block_size as usize;
    if host_window == 0 || remaining < host_window {
        remaining
    } else {
        host_window
    }
}

#[cfg(not(target_os = "none"))]
fn sdio_execute_command(
    _cmd: u16,
    _arg: u32,
    _flags: u16,
    _frame: DriverFrameDescriptor,
) -> Option<u32> {
    Some(0)
}

#[cfg(not(target_os = "none"))]
fn sdio_execute_transfer(
    _cmd: u16,
    _arg: u32,
    _flags: u16,
    _frame: DriverFrameDescriptor,
    _block_size: u16,
    _block_count: u16,
) -> Option<u32> {
    Some(0)
}

fn sdio_make_command(cmd: u16, flags: u16, data: bool) -> u16 {
    let mut command = if flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_NONE != 0 {
        SDHCI_CMD_RESP_NONE
    } else if flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_LONG != 0 {
        SDHCI_CMD_RESP_LONG | SDHCI_CMD_CRC
    } else if flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT_BUSY != 0 {
        SDHCI_CMD_RESP_SHORT_BUSY | SDHCI_CMD_CRC | SDHCI_CMD_INDEX
    } else if flags & DRIVER_RUNTIME_SDIO_FLAG_RESP_OCR != 0 {
        SDHCI_CMD_RESP_SHORT
    } else {
        SDHCI_CMD_RESP_SHORT | SDHCI_CMD_CRC | SDHCI_CMD_INDEX
    };
    if data {
        command |= SDHCI_CMD_DATA;
    }
    (cmd << 8) | command
}

fn sdio_wait_inhibit_clear(wait_data: bool) -> bool {
    let mask = if wait_data {
        SDHCI_CMD_INHIBIT | SDHCI_DATA_INHIBIT
    } else {
        SDHCI_CMD_INHIBIT
    };
    for _ in 0..SDHCI_CMD_WAIT_LOOPS {
        if sdio_read32(SDHCI_PRESENT_STATE) & mask == 0 {
            return true;
        }
        core::hint::spin_loop();
    }
    false
}

const fn sdhci_wait_int_ack_bits(mask: u32, status: u32) -> u32 {
    status & (mask | SDHCI_INT_WAIT_ACK_MASK) & !SDHCI_INT_CARD_INT
}

#[cfg(target_os = "none")]
fn sdio_wait_int(mask: u32) -> u32 {
    let error_mask = SDHCI_INT_ERROR
        | SDHCI_INT_TIMEOUT
        | SDHCI_INT_CRC
        | SDHCI_INT_END_BIT
        | SDHCI_INT_INDEX
        | SDHCI_INT_DATA_TIMEOUT
        | SDHCI_INT_DATA_CRC
        | SDHCI_INT_DATA_END_BIT;
    for _ in 0..SDHCI_CMD_WAIT_LOOPS {
        let status = sdio_read32(SDHCI_INT_STATUS);
        if status & (mask | error_mask) != 0 {
            let ack = sdhci_wait_int_ack_bits(mask, status);
            if ack != 0 {
                sdio_write32(SDHCI_INT_STATUS, ack);
            }
            return status;
        }
        core::hint::spin_loop();
    }
    0
}

#[cfg(target_os = "none")]
fn sdio_transfer_frame(frame: DriverFrameDescriptor, write: bool, block_size: u16) -> bool {
    let mut offset = 0usize;
    while offset < frame.len as usize {
        let ready = if write {
            SDHCI_SPACE_AVAILABLE | SDHCI_INT_SPACE_AVAIL
        } else {
            SDHCI_DATA_AVAILABLE | SDHCI_INT_DATA_AVAIL
        };
        if sdio_read32(SDHCI_PRESENT_STATE) & ready == 0 {
            let status = sdio_wait_int(ready | SDHCI_INT_ERROR);
            if status & SDHCI_INT_ERROR != 0 || status == 0 {
                sdio_record_transfer_failure(SDIO_TRANSFER_FAILURE_STAGE_DATA_WAIT, status);
                let _ = sdio_recover_command_path();
                return false;
            }
        }
        let burst_end = offset + sdio_pio_ready_burst_len(block_size, frame.len as usize - offset);
        while offset < burst_end {
            if sdio_read32(SDHCI_PRESENT_STATE) & ready == 0 {
                break;
            }
            let word_len = (burst_end - offset).min(4);
            if write {
                let mut word = 0u32;
                for byte_index in 0..word_len {
                    word |= u32::from(read_runtime_payload_byte(
                        frame.offset as usize + offset + byte_index,
                    )) << (byte_index * 8);
                }
                sdio_write32(SDHCI_BUFFER, word);
            } else {
                let word = sdio_read32(SDHCI_BUFFER);
                for byte_index in 0..word_len {
                    write_runtime_payload_byte(
                        frame.offset as usize + offset + byte_index,
                        ((word >> (byte_index * 8)) & 0xff) as u8,
                    );
                }
            }
            offset = offset.saturating_add(word_len);
        }
    }
    sdio_write32(SDHCI_INT_STATUS, SDHCI_INT_DATA_READY_MASK);
    let status = sdio_wait_int(SDHCI_INT_DATA_FINISH_MASK);
    if status & SDHCI_INT_ERROR == 0 && status != 0 {
        sdio_settle_transfer_data_path();
        true
    } else {
        sdio_record_transfer_failure(SDIO_TRANSFER_FAILURE_STAGE_DATA_END, status);
        let _ = sdio_recover_command_path();
        false
    }
}

#[cfg(target_os = "none")]
fn sdio_settle_transfer_data_path() {
    for _ in 0..SDHCI_CMD_WAIT_LOOPS {
        let present = sdio_read32(SDHCI_PRESENT_STATE);
        if present & (SDHCI_DATA_INHIBIT | SDHCI_DAT_ACTIVE) == 0 {
            return;
        }
        core::hint::spin_loop();
    }
    let present = sdio_read32(SDHCI_PRESENT_STATE);
    sdio_record_transfer_failure(SDIO_TRANSFER_FAILURE_STAGE_DATA_END, present);
    let _ = sdio_recover_command_path();
}

fn service_pcie_root(command: DriverTaskCommandRecord) -> DriverTaskCompletionRecord {
    if let Some(completion) = service_engine_init(command) {
        return completion;
    }
    if !engine_initialized(&PCIE_RUNTIME_FLAGS) {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_DEVICE_UNAVAILABLE);
    }
    let op = (command.aux0 >> 16) as u16;
    let offset = command.aux1 as usize;
    let descriptor = RUNTIME_DESCRIPTOR.load();
    let mmio_limit =
        usize::from(descriptor.mmio_page_count).saturating_mul(DRIVER_TASK_RING_PAGE_BYTES);
    if offset & 0x3 != 0
        || offset
            .checked_add(PCIE_MMIO_ACCESS_BYTES)
            .is_none_or(|end| end > mmio_limit)
    {
        return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
    }
    match op {
        DRIVER_RUNTIME_PCIE_OP_PORT_READ => {
            if command.frame.len != 0 {
                return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
            }
            let value = pcie_read32(offset);
            PCIE_OP_COUNT.fetch_add(1, Ordering::AcqRel);
            PCIE_RUNTIME_STATE.with_mut(|state| {
                state.op_count = state.op_count.saturating_add(1);
            });
            PCIE_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_RX_PROGRESS, Ordering::AcqRel);
            DriverTaskCompletionRecord::progress(command.sequence, value)
        }
        DRIVER_RUNTIME_PCIE_OP_PORT_WRITE => {
            let value = match pcie_frame_write_value(command.frame) {
                Ok(value) => value,
                Err(detail) => {
                    return DriverTaskCompletionRecord::fault(command.sequence, detail);
                }
            };
            pcie_write32(offset, value);
            PCIE_OP_COUNT.fetch_add(1, Ordering::AcqRel);
            PCIE_RUNTIME_STATE.with_mut(|state| {
                state.op_count = state.op_count.saturating_add(1);
            });
            PCIE_RUNTIME_FLAGS.fetch_or(ENGINE_STATE_TX_PROGRESS, Ordering::AcqRel);
            DriverTaskCompletionRecord::progress(command.sequence, 1)
        }
        DRIVER_RUNTIME_PCIE_OP_POSTED_WRITE_FLUSH => {
            if command.frame.len != 0 {
                return DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND);
            }
            if !pcie_runtime_flush_vl805_posted_write() {
                return DriverTaskCompletionRecord::fault(
                    command.sequence,
                    FAULT_DEVICE_UNAVAILABLE,
                );
            }
            PCIE_OP_COUNT.fetch_add(1, Ordering::AcqRel);
            PCIE_RUNTIME_STATE.with_mut(|state| {
                state.op_count = state.op_count.saturating_add(1);
            });
            DriverTaskCompletionRecord::progress(command.sequence, 1)
        }
        _ => DriverTaskCompletionRecord::fault(command.sequence, FAULT_REJECTED_COMMAND),
    }
}

fn pcie_frame_write_value(frame: DriverFrameDescriptor) -> Result<u32, u16> {
    if frame.len == 0 {
        return Ok(0);
    }
    if frame.len != 4 || !frame.in_ring_payload() {
        return Err(FAULT_REJECTED_COMMAND);
    }
    Ok(read_ring_u32(frame.offset as usize))
}

#[cfg_attr(target_os = "none", allow(dead_code))]
const CYW43_TRANSPORT_PHASE_LIMIT: usize = 8;
const CYW43_TRANSPORT_COMMAND_BURST_STEPS: usize = 1;
const CYW43_SDIO_CARD_INIT_ATTEMPTS: usize = 2;
const CYW43_SDIO_CARD_INIT_POLL_ATTEMPTS: u16 = 64;
const CYW43_SDIO_CARD_INIT_RETRY_SETTLE_SPINS: usize = 512;
const CYW43_CARD_INIT_PHASE_HOST_CONFIG: u8 = 0;
const CYW43_CARD_INIT_PHASE_CMD0: u8 = 1;
const CYW43_CARD_INIT_PHASE_CMD5_OCR: u8 = 2;
const CYW43_CARD_INIT_PHASE_CMD5_READY: u8 = 3;
const CYW43_CARD_INIT_PHASE_CMD3_RCA: u8 = 4;
const CYW43_CARD_INIT_PHASE_CMD7_SELECT: u8 = 5;
const CYW43_CARD_INIT_PHASE_DONE: u8 = 6;

#[cfg_attr(target_os = "none", allow(dead_code))]
fn cyw43_transport_init(state: &mut Cyw43RuntimeState) -> Result<(), u16> {
    let mut count = 0usize;
    while count < CYW43_TRANSPORT_PHASE_LIMIT {
        if cyw43_transport_init_step(0, DRIVER_RUNTIME_CYW43_COMMAND_AUX, state)?
            == DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_READY
        {
            return Ok(());
        }
        count = count.saturating_add(1);
    }
    Err(FAULT_CYW43_TRANSPORT_INIT)
}

fn cyw43_transport_init_command(
    sequence: u32,
    aux0: u32,
    state: &mut Cyw43RuntimeState,
) -> Result<u16, u16> {
    let mut last_detail = state.transport_detail;
    for _ in 0..CYW43_TRANSPORT_COMMAND_BURST_STEPS {
        last_detail = cyw43_transport_init_step(sequence, aux0, state)?;
        if last_detail == DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_READY {
            return Ok(last_detail);
        }
    }
    Ok(last_detail)
}

fn cyw43_transport_init_step(
    sequence: u32,
    aux0: u32,
    state: &mut Cyw43RuntimeState,
) -> Result<u16, u16> {
    if state.transport_ready {
        state.transport_detail = DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_READY;
        publish_runtime_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_CYW43_TRANSPORT_READY,
            aux0,
        );
        return Ok(DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_READY);
    }
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_TRANSPORT_BEGIN,
        aux0,
    );
    match state.transport_detail {
        DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_START => {
            if !state.bus_link_ready {
                return Err(FAULT_CYW43_TRANSPORT_BUS_LINK);
            }
            state.reset_firmware_upload_state();
            state.transport_ready = false;
            state.backplane_window_valid = false;
            if !cyw43_uses_sdio_bus_link()
                && sdio_runtime_init_hw(sequence, DRIVER_RUNTIME_NET_INIT_AUX).is_err()
            {
                return Err(FAULT_CYW43_TRANSPORT_DIRECT_SDIO);
            }
            state.transport_detail = DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_BUS_LINK_READY;
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_BUS_LINK_READY,
                aux0,
            );
            Ok(state.transport_detail)
        }
        DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_BUS_LINK_READY => {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_CARD_ADOPT_BEGIN,
                aux0,
            );
            if !cyw43_sdio_card_init_step(sequence, aux0, state)? {
                return Ok(state.transport_detail);
            }
            state.transport_detail = DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_CARD_READY;
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_CARD_READY,
                aux0,
            );
            Ok(state.transport_detail)
        }
        DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_CARD_READY => {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_F1_BLOCK_BEGIN,
                aux0,
            );
            if !cyw43_set_function_block_size(1, SDIO_FUNCTION1_BLOCK_SIZE) {
                return Err(FAULT_CYW43_TRANSPORT_F1_BLOCK_SIZE);
            }
            state.transport_detail = DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_F1_BLOCK_READY;
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_F1_BLOCK_READY,
                aux0,
            );
            Ok(state.transport_detail)
        }
        DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_F1_BLOCK_READY => {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_F2_BLOCK_BEGIN,
                aux0,
            );
            if !cyw43_set_function_block_size(2, SDIO_FUNCTION2_BLOCK_SIZE) {
                return Err(FAULT_CYW43_TRANSPORT_F2_BLOCK_SIZE);
            }
            state.transport_detail = DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_F2_BLOCK_READY;
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_F2_BLOCK_READY,
                aux0,
            );
            Ok(state.transport_detail)
        }
        DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_F2_BLOCK_READY => {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_F1_ENABLE_BEGIN,
                aux0,
            );
            if !cyw43_enable_sdio_function(SDIO_FUNC_ENABLE_1, SDIO_FUNC_READY_1) {
                return Err(FAULT_CYW43_TRANSPORT_F1_ENABLE);
            }
            state.transport_detail = DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_F1_ENABLED;
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_F1_ENABLED,
                aux0,
            );
            Ok(state.transport_detail)
        }
        DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_F1_ENABLED => {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_HOST_CONFIG_BEGIN,
                aux0,
            );
            if !cyw43_configure_sdio_host(SDHCI_STARTUP_CLOCK_HZ, 0) {
                return Err(FAULT_CYW43_TRANSPORT_HOST_BUS_WIDTH);
            }
            state.transport_detail = DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_HOST_READY;
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_HOST_READY,
                aux0,
            );
            Ok(state.transport_detail)
        }
        DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_HOST_READY
        | DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_BACKPLANE_READY => {
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_BACKPLANE_BEGIN,
                aux0,
            );
            cyw43_backplane_transport_init(state)?;
            state.transport_detail = DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_BACKPLANE_READY;
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_BACKPLANE_READY,
                aux0,
            );
            state.transport_ready = true;
            state.transport_detail = DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_READY;
            publish_runtime_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_TRANSPORT_READY,
                aux0,
            );
            Ok(state.transport_detail)
        }
        _ => {
            state.transport_detail = DRIVER_RUNTIME_CYW43_TRANSPORT_DETAIL_START;
            Err(FAULT_CYW43_TRANSPORT_INIT)
        }
    }
}

fn cyw43_sdio_card_init_step(
    sequence: u32,
    aux0: u32,
    state: &mut Cyw43RuntimeState,
) -> Result<bool, u16> {
    #[cfg(not(target_os = "none"))]
    {
        let _ = sequence;
        let _ = aux0;
        let _ = state;
        return Ok(true);
    }
    #[cfg(target_os = "none")]
    {
        let empty = DriverFrameDescriptor::empty();
        match state.card_init_phase {
            CYW43_CARD_INIT_PHASE_HOST_CONFIG => {
                publish_runtime_progress(
                    sequence,
                    pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_CYW43_CARD_HOST_CONFIG_BEGIN,
                    aux0,
                );
                if !cyw43_configure_sdio_host(SDHCI_STARTUP_CLOCK_HZ, 0) {
                    return cyw43_card_init_restart_or_fault(
                        state,
                        FAULT_CYW43_TRANSPORT_HOST_BUS_WIDTH,
                    );
                }
                state.card_init_phase = CYW43_CARD_INIT_PHASE_CMD0;
                state.card_init_poll_count = 0;
                Ok(false)
            }
            CYW43_CARD_INIT_PHASE_CMD0 => {
                publish_runtime_progress(
                    sequence,
                    pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_CYW43_CARD_CMD0_BEGIN,
                    aux0,
                );
                if sdio_execute_transfer(0, 0, DRIVER_RUNTIME_SDIO_FLAG_RESP_NONE, empty, 1, 0)
                    .is_none()
                {
                    return cyw43_card_init_restart_or_fault(
                        state,
                        FAULT_CYW43_TRANSPORT_CARD_CMD0,
                    );
                }
                state.card_init_phase = CYW43_CARD_INIT_PHASE_CMD5_OCR;
                state.card_init_poll_count = 0;
                Ok(false)
            }
            CYW43_CARD_INIT_PHASE_CMD5_OCR => {
                publish_runtime_progress(
                    sequence,
                    pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_CYW43_CARD_CMD5_OCR_BEGIN,
                    aux0,
                );
                let Some(response) = sdio_execute_transfer(
                    SDIO_CMD5,
                    0,
                    DRIVER_RUNTIME_SDIO_FLAG_RESP_OCR,
                    empty,
                    1,
                    0,
                ) else {
                    return cyw43_card_init_restart_or_fault(
                        state,
                        FAULT_CYW43_TRANSPORT_CARD_CMD5_OCR,
                    );
                };
                state.card_init_ocr = response;
                if response & SDIO_OCR_3V2_3V4 != 0 {
                    state.card_init_phase = CYW43_CARD_INIT_PHASE_CMD5_READY;
                    state.card_init_poll_count = 0;
                } else if !cyw43_card_init_poll_again_or_restart(
                    state,
                    FAULT_CYW43_TRANSPORT_CARD_CMD5_OCR,
                )? {
                    return Ok(false);
                }
                Ok(false)
            }
            CYW43_CARD_INIT_PHASE_CMD5_READY => {
                publish_runtime_progress(
                    sequence,
                    pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_CYW43_CARD_CMD5_READY_BEGIN,
                    aux0,
                );
                let desired_ocr = state.card_init_ocr & SDIO_OCR_3V2_3V4;
                if desired_ocr == 0 {
                    return cyw43_card_init_restart_or_fault(
                        state,
                        FAULT_CYW43_TRANSPORT_CARD_CMD5_OCR,
                    );
                }
                let Some(response) = sdio_execute_transfer(
                    SDIO_CMD5,
                    desired_ocr,
                    DRIVER_RUNTIME_SDIO_FLAG_RESP_OCR,
                    empty,
                    1,
                    0,
                ) else {
                    return cyw43_card_init_restart_or_fault(
                        state,
                        FAULT_CYW43_TRANSPORT_CARD_CMD5_READY,
                    );
                };
                state.card_init_ocr = response;
                if response & SDIO_R4_READY != 0 {
                    state.card_init_phase = CYW43_CARD_INIT_PHASE_CMD3_RCA;
                    state.card_init_poll_count = 0;
                } else if !cyw43_card_init_poll_again_or_restart(
                    state,
                    FAULT_CYW43_TRANSPORT_CARD_CMD5_READY,
                )? {
                    return Ok(false);
                }
                Ok(false)
            }
            CYW43_CARD_INIT_PHASE_CMD3_RCA => {
                publish_runtime_progress(
                    sequence,
                    pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_CYW43_CARD_CMD3_RCA_BEGIN,
                    aux0,
                );
                let Some(response) = sdio_execute_transfer(
                    SDIO_CMD3,
                    0,
                    DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
                    empty,
                    1,
                    0,
                ) else {
                    return cyw43_card_init_restart_or_fault(
                        state,
                        FAULT_CYW43_TRANSPORT_CARD_CMD3_RCA,
                    );
                };
                let rca = response & 0xffff_0000;
                if rca == 0 {
                    return cyw43_card_init_restart_or_fault(
                        state,
                        FAULT_CYW43_TRANSPORT_CARD_CMD3_RCA,
                    );
                }
                state.card_init_rca = rca;
                state.card_init_phase = CYW43_CARD_INIT_PHASE_CMD7_SELECT;
                Ok(false)
            }
            CYW43_CARD_INIT_PHASE_CMD7_SELECT => {
                publish_runtime_progress(
                    sequence,
                    pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_CYW43_CARD_CMD7_SELECT_BEGIN,
                    aux0,
                );
                if state.card_init_rca == 0 {
                    return cyw43_card_init_restart_or_fault(
                        state,
                        FAULT_CYW43_TRANSPORT_CARD_CMD3_RCA,
                    );
                }
                if sdio_execute_transfer(
                    SDIO_CMD7,
                    state.card_init_rca,
                    DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT_BUSY,
                    empty,
                    1,
                    0,
                )
                .or_else(|| {
                    if cyw43_configure_sdio_host(SDHCI_STARTUP_CLOCK_HZ, 0) {
                        sdio_execute_transfer(
                            SDIO_CMD7,
                            state.card_init_rca,
                            DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
                            empty,
                            1,
                            0,
                        )
                    } else {
                        None
                    }
                })
                .is_none()
                {
                    return cyw43_card_init_restart_or_fault(
                        state,
                        FAULT_CYW43_TRANSPORT_CARD_CMD7_SELECT,
                    );
                }
                state.card_init_phase = CYW43_CARD_INIT_PHASE_DONE;
                Ok(true)
            }
            CYW43_CARD_INIT_PHASE_DONE => Ok(true),
            _ => {
                state.reset_card_init_state();
                Err(FAULT_CYW43_TRANSPORT_CARD_CMD0)
            }
        }
    }
}

#[cfg(target_os = "none")]
fn cyw43_card_init_poll_again_or_restart(
    state: &mut Cyw43RuntimeState,
    detail: u16,
) -> Result<bool, u16> {
    state.card_init_poll_count = state.card_init_poll_count.saturating_add(1);
    if state.card_init_poll_count < CYW43_SDIO_CARD_INIT_POLL_ATTEMPTS {
        Ok(false)
    } else {
        cyw43_card_init_restart_or_fault(state, detail)
    }
}

#[cfg(target_os = "none")]
fn cyw43_card_init_restart_or_fault(
    state: &mut Cyw43RuntimeState,
    detail: u16,
) -> Result<bool, u16> {
    if usize::from(state.card_init_attempt).saturating_add(1) < CYW43_SDIO_CARD_INIT_ATTEMPTS {
        state.card_init_attempt = state.card_init_attempt.saturating_add(1);
        state.card_init_phase = CYW43_CARD_INIT_PHASE_HOST_CONFIG;
        state.card_init_poll_count = 0;
        state.card_init_ocr = 0;
        state.card_init_rca = 0;
        cyw43_spin_wait(CYW43_SDIO_CARD_INIT_RETRY_SETTLE_SPINS);
        Ok(false)
    } else {
        cyw43_record_last_fault_with_result(detail, cyw43_card_init_fault_result(state, detail));
        Err(detail)
    }
}

#[cfg(target_os = "none")]
const fn cyw43_card_init_fault_result(state: &Cyw43RuntimeState, detail: u16) -> u32 {
    let cmd = match detail {
        FAULT_CYW43_TRANSPORT_CARD_CMD0 => 0,
        FAULT_CYW43_TRANSPORT_CARD_CMD5_OCR | FAULT_CYW43_TRANSPORT_CARD_CMD5_READY => SDIO_CMD5,
        FAULT_CYW43_TRANSPORT_CARD_CMD3_RCA => SDIO_CMD3,
        FAULT_CYW43_TRANSPORT_CARD_CMD7_SELECT => SDIO_CMD7,
        _ => 0xff,
    };
    let low = if detail == FAULT_CYW43_TRANSPORT_CARD_CMD7_SELECT {
        (state.card_init_rca >> 16) & 0xffff
    } else {
        state.card_init_ocr & 0xffff
    };
    ((cmd as u32) << 24) | ((state.card_init_attempt as u32) << 16) | low
}

fn cyw43_sdio_card_init() -> Result<(), u16> {
    #[cfg(not(target_os = "none"))]
    {
        return Ok(());
    }
    #[cfg(target_os = "none")]
    {
        let mut last_detail = FAULT_CYW43_TRANSPORT_CARD_CMD0;
        for attempt in 0..CYW43_SDIO_CARD_INIT_ATTEMPTS {
            if attempt != 0 {
                cyw43_spin_wait(CYW43_SDIO_CARD_INIT_RETRY_SETTLE_SPINS);
            }
            if !cyw43_configure_sdio_host(SDHCI_STARTUP_CLOCK_HZ, 0) {
                last_detail = FAULT_CYW43_TRANSPORT_HOST_BUS_WIDTH;
                continue;
            }
            match cyw43_sdio_card_init_once() {
                Ok(()) => return Ok(()),
                Err(detail) => {
                    last_detail = detail;
                    if !cyw43_sdio_card_init_detail_retryable(detail) {
                        break;
                    }
                }
            }
        }
        Err(last_detail)
    }
}

const fn cyw43_sdio_card_init_detail_retryable(detail: u16) -> bool {
    matches!(
        detail,
        FAULT_CYW43_TRANSPORT_CARD_CMD0
            | FAULT_CYW43_TRANSPORT_CARD_CMD5_OCR
            | FAULT_CYW43_TRANSPORT_CARD_CMD5_READY
            | FAULT_CYW43_TRANSPORT_CARD_CMD3_RCA
            | FAULT_CYW43_TRANSPORT_CARD_CMD7_SELECT
            | FAULT_CYW43_TRANSPORT_HOST_BUS_WIDTH
    )
}

#[cfg(target_os = "none")]
fn cyw43_sdio_card_init_once() -> Result<(), u16> {
    let empty = DriverFrameDescriptor::empty();
    if sdio_execute_transfer(0, 0, DRIVER_RUNTIME_SDIO_FLAG_RESP_NONE, empty, 1, 0).is_none() {
        return Err(FAULT_CYW43_TRANSPORT_CARD_CMD0);
    }
    let mut ocr = 0u32;
    for _ in 0..SDHCI_INIT_SPINS {
        let Some(response) =
            sdio_execute_transfer(SDIO_CMD5, 0, DRIVER_RUNTIME_SDIO_FLAG_RESP_OCR, empty, 1, 0)
        else {
            return Err(FAULT_CYW43_TRANSPORT_CARD_CMD5_OCR);
        };
        ocr = response;
        if ocr & SDIO_OCR_3V2_3V4 != 0 {
            break;
        }
        core::hint::spin_loop();
    }
    if ocr & SDIO_OCR_3V2_3V4 == 0 {
        return Err(FAULT_CYW43_TRANSPORT_CARD_CMD5_OCR);
    }
    let desired_ocr = ocr & SDIO_OCR_3V2_3V4;
    for _ in 0..SDHCI_INIT_SPINS {
        let Some(response) = sdio_execute_transfer(
            SDIO_CMD5,
            desired_ocr,
            DRIVER_RUNTIME_SDIO_FLAG_RESP_OCR,
            empty,
            1,
            0,
        ) else {
            return Err(FAULT_CYW43_TRANSPORT_CARD_CMD5_READY);
        };
        if response & SDIO_R4_READY != 0 {
            ocr = response;
            break;
        }
        core::hint::spin_loop();
    }
    if ocr & SDIO_R4_READY == 0 {
        return Err(FAULT_CYW43_TRANSPORT_CARD_CMD5_READY);
    }
    let Some(rca_response) = sdio_execute_transfer(
        SDIO_CMD3,
        0,
        DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        empty,
        1,
        0,
    ) else {
        return Err(FAULT_CYW43_TRANSPORT_CARD_CMD3_RCA);
    };
    let rca = rca_response & 0xffff_0000;
    if rca == 0 {
        return Err(FAULT_CYW43_TRANSPORT_CARD_CMD3_RCA);
    }
    let cmd7 = sdio_execute_transfer(
        SDIO_CMD7,
        rca,
        DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT_BUSY,
        empty,
        1,
        0,
    )
    .or_else(|| {
        if cyw43_configure_sdio_host(SDHCI_STARTUP_CLOCK_HZ, 0) {
            sdio_execute_transfer(
                SDIO_CMD7,
                rca,
                DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
                empty,
                1,
                0,
            )
        } else {
            None
        }
    });
    cmd7.map(|_| ())
        .ok_or(FAULT_CYW43_TRANSPORT_CARD_CMD7_SELECT)
}

fn cyw43_set_function_block_size(function: u8, size: u16) -> bool {
    #[cfg(not(target_os = "none"))]
    {
        let _ = function;
        let _ = size;
        return true;
    }
    #[cfg(target_os = "none")]
    {
        let base = SDIO_CCCR_FBR_BASE.saturating_mul(u32::from(function));
        if !cyw43_sdio_cmd52_write(0, base + SDIO_FBR_BLKSIZE, (size & 0xff) as u8)
            || !cyw43_sdio_cmd52_write(0, base + SDIO_FBR_BLKSIZE + 1, (size >> 8) as u8)
        {
            return false;
        }
        cyw43_read_function_block_size(function) == Some(size)
    }
}

fn cyw43_read_function_block_size(function: u8) -> Option<u16> {
    let base = SDIO_CCCR_FBR_BASE.saturating_mul(u32::from(function));
    let low = cyw43_sdio_cmd52_read(0, base + SDIO_FBR_BLKSIZE)?;
    let high = cyw43_sdio_cmd52_read(0, base + SDIO_FBR_BLKSIZE + 1)?;
    Some(u16::from(low) | (u16::from(high) << 8))
}

fn cyw43_enable_sdio_function(enable_bit: u8, ready_bit: u8) -> bool {
    #[cfg(not(target_os = "none"))]
    {
        let _ = enable_bit;
        let _ = ready_bit;
        return true;
    }
    #[cfg(target_os = "none")]
    {
        let current = cyw43_sdio_cmd52_read(0, SDIO_CCCR_IOEX).unwrap_or(0);
        let desired = current | enable_bit;
        if !cyw43_sdio_cmd52_write(0, SDIO_CCCR_IOEX, desired) {
            return false;
        }
        for _ in 0..CYW43_SDIO_WAIT_F2_READY_POLLS {
            if cyw43_sdio_cmd52_read(0, SDIO_CCCR_IORX).unwrap_or(0) & ready_bit != 0 {
                return true;
            }
            core::hint::spin_loop();
        }
        false
    }
}

fn cyw43_enable_sdio_high_speed_timing() -> Result<bool, u16> {
    let speed =
        cyw43_sdio_cmd52_read(0, SDIO_CCCR_SPEED).ok_or(FAULT_CYW43_TRANSPORT_HIGH_SPEED)?;
    if speed & SDIO_CCCR_SPEED_SHS == 0 {
        return Ok(false);
    }
    let desired = speed | SDIO_CCCR_SPEED_EHS;
    if desired != speed && !cyw43_sdio_cmd52_write(0, SDIO_CCCR_SPEED, desired) {
        return Err(FAULT_CYW43_TRANSPORT_HIGH_SPEED);
    }
    let readback =
        cyw43_sdio_cmd52_read(0, SDIO_CCCR_SPEED).ok_or(FAULT_CYW43_TRANSPORT_HIGH_SPEED)?;
    if readback & SDIO_CCCR_SPEED_EHS == 0 {
        return Err(FAULT_CYW43_TRANSPORT_HIGH_SPEED);
    }
    Ok(true)
}

fn cyw43_backplane_transport_init(state: &mut Cyw43RuntimeState) -> Result<(), u16> {
    cyw43_backplane_transport_init_once()?;
    if cyw43_backplane_read_u32(state, CYW43_CHIPCOMMON_BASE).is_some() {
        return Ok(());
    }
    let first_fault = cyw43_take_last_fault_detail();
    state.backplane_window_valid = false;
    cyw43_clear_last_fault();
    cyw43_recover_backplane_startup_transport(state)?;
    cyw43_backplane_transport_init_once()?;
    if cyw43_backplane_read_u32(state, CYW43_CHIPCOMMON_BASE).is_some() {
        return Ok(());
    }
    let fault = cyw43_take_last_fault_detail().or(first_fault);
    if matches!(
        fault,
        Some(FAULT_SDIO_DESCRIPTOR_UNAVAILABLE | FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED)
    ) {
        cyw43_record_last_fault(FAULT_CYW43_BACKPLANE_CHIPCOMMON_READ);
        return Err(FAULT_CYW43_BACKPLANE_CHIPCOMMON_READ);
    }
    Err(fault.unwrap_or(FAULT_CYW43_BACKPLANE_WINDOW))
}

fn cyw43_backplane_transport_init_once() -> Result<(), u16> {
    if !cyw43_sdio_cmd52_write(
        1,
        SBSDIO_FUNC1_CHIPCLKCSR,
        SBSDIO_FORCE_HW_CLKREQ_OFF | SBSDIO_ALP_AVAIL_REQ,
    ) {
        return Err(FAULT_CYW43_BACKPLANE_ALP);
    }
    let mut alp_ready = cfg!(not(target_os = "none"));
    for _ in 0..SDHCI_INIT_SPINS {
        if cyw43_sdio_cmd52_read(1, SBSDIO_FUNC1_CHIPCLKCSR).unwrap_or(0) & SBSDIO_ALP_AVAIL != 0 {
            alp_ready = true;
            break;
        }
        core::hint::spin_loop();
    }
    if !alp_ready {
        return Err(FAULT_CYW43_BACKPLANE_ALP);
    }
    let _ = cyw43_sdio_cmd52_write(
        1,
        SBSDIO_FUNC1_CHIPCLKCSR,
        SBSDIO_FORCE_HW_CLKREQ_OFF | SBSDIO_FORCE_ALP,
    );
    cyw43_spin_wait(CYW43_BACKPLANE_FORCE_ALP_SETTLE_SPINS);
    Ok(())
}

fn cyw43_recover_backplane_startup_transport(state: &mut Cyw43RuntimeState) -> Result<(), u16> {
    state.backplane_window_valid = false;
    if !cyw43_configure_sdio_host(SDHCI_STARTUP_CLOCK_HZ, 0) {
        return Err(FAULT_CYW43_TRANSPORT_HOST_BUS_WIDTH);
    }
    cyw43_sdio_card_init()?;
    if !cyw43_set_function_block_size(1, SDIO_FUNCTION1_BLOCK_SIZE) {
        return Err(FAULT_CYW43_TRANSPORT_F1_BLOCK_SIZE);
    }
    if !cyw43_set_function_block_size(2, SDIO_FUNCTION2_BLOCK_SIZE) {
        return Err(FAULT_CYW43_TRANSPORT_F2_BLOCK_SIZE);
    }
    if !cyw43_enable_sdio_function(SDIO_FUNC_ENABLE_1, SDIO_FUNC_READY_1) {
        return Err(FAULT_CYW43_TRANSPORT_F1_ENABLE);
    }
    Ok(())
}

fn cyw43_prepare_firmware_upload_transport(state: &mut Cyw43RuntimeState) -> Result<(), u16> {
    if state.firmware_upload_prepared {
        state.firmware_uploaded = false;
        state.nvram_uploaded = false;
        state.nvram_tail_uploaded = false;
        state.firmware_released = false;
        state.firmware_bytes = 0;
        state.nvram_bytes = 0;
        state.firmware_total_len = 0;
        state.nvram_total_len = 0;
        state.nvram_tail_magic = 0;
        cyw43_reset_firmware_stage(state);
        return Ok(());
    }
    if !state.transport_ready {
        return Err(FAULT_CYW43_TRANSPORT_INIT);
    }
    if !cyw43_configure_sdio_host(
        SDHCI_STARTUP_CLOCK_HZ,
        DriverRuntimeSdioCommandDescriptor::FLAG_HOST_BUS_WIDTH_4BIT,
    ) {
        return Err(FAULT_CYW43_TRANSPORT_HOST_BUS_WIDTH);
    }
    if !cyw43_sdio_cmd52_write(0, SDIO_CCCR_IF, SDIO_BUS_WIDTH_4BIT) {
        return Err(FAULT_CYW43_TRANSPORT_CARD_BUS_WIDTH);
    }
    let high_speed_flags = if cyw43_enable_sdio_high_speed_timing()? {
        DriverRuntimeSdioCommandDescriptor::FLAG_HOST_HIGH_SPEED
    } else {
        0
    };
    if !cyw43_configure_sdio_host(
        CYW43_SDIO_FAST_CLOCK_HZ,
        DriverRuntimeSdioCommandDescriptor::FLAG_HOST_BUS_WIDTH_4BIT | high_speed_flags,
    ) {
        return Err(FAULT_CYW43_TRANSPORT_HOST_BUS_WIDTH);
    }
    if !cyw43_sdio_cmd52_write(
        1,
        SBSDIO_FUNC1_CHIPCLKCSR,
        SBSDIO_FORCE_HW_CLKREQ_OFF | SBSDIO_ALP_AVAIL_REQ,
    ) {
        return Err(FAULT_CYW43_BACKPLANE_ALP);
    }
    let mut alp_ready = cfg!(not(target_os = "none"));
    for _ in 0..SDHCI_INIT_SPINS {
        if cyw43_sdio_cmd52_read(1, SBSDIO_FUNC1_CHIPCLKCSR).unwrap_or(0) & SBSDIO_ALP_AVAIL != 0 {
            alp_ready = true;
            break;
        }
        core::hint::spin_loop();
    }
    if !alp_ready {
        return Err(FAULT_CYW43_BACKPLANE_ALP);
    }
    cyw43_hold_armcr4_for_firmware_upload(state)?;
    cyw43_disable_d11_cores_for_firmware(state);
    cyw43_prepare_socram_for_armcr4_upload(state)?;
    cyw43_reset_firmware_stage(state);
    state.firmware_upload_prepared = true;
    if CYW43_LINKED_PRE_RELEASE_BYTE_MODE_PRIMARY {
        if !cyw43_force_conservative_firmware_byte_replay(state) {
            return Err(FAULT_CYW43_TRANSPORT_HOST_BUS_WIDTH);
        }
        state.firmware_narrow_byte_mode_fallback = true;
    }
    Ok(())
}

fn cyw43_prepare_post_release_function2(_state: &mut Cyw43RuntimeState) -> Result<(), u16> {
    if !cyw43_sdio_cmd52_write(1, SBSDIO_FUNC1_WAKEUPCTRL, SBSDIO_WAKE_TILL_HT_AVAIL) {
        return Err(FAULT_CYW43_BACKPLANE_WAKE);
    }
    if !cyw43_sdio_cmd52_write(1, SBSDIO_FUNC1_SLEEPCSR, SBSDIO_FUNC1_SLEEPCSR_KSO_EN) {
        return Err(FAULT_CYW43_BACKPLANE_KSO);
    }
    if !cyw43_sdio_cmd52_write(
        0,
        SDIO_CCCR_BRCM_CARDCAP,
        cyw43_cardcap_command_decode_value(),
    ) {
        return Err(FAULT_CYW43_POST_RELEASE_CARDCAP);
    }
    if !cyw43_sdio_cmd52_write(1, SBSDIO_WATERMARK, CY_43455_F2_WATERMARK)
        || !cyw43_sdio_cmd52_write(1, SBSDIO_FUNC1_MESBUSYCTRL, CY_43455_MESBUSYCTRL)
    {
        return Err(FAULT_CYW43_BACKPLANE_WATERMARK);
    }
    if !cyw43_sdio_cmd52_write(1, SBSDIO_DEVICE_CTL, SBSDIO_DEVCTL_F2WM_ENAB) {
        return Err(FAULT_CYW43_BACKPLANE_DEVICE_CTL);
    }
    Ok(())
}

fn cyw43_require_post_release_ht_clock() -> Result<u8, u16> {
    #[cfg(not(target_os = "none"))]
    {
        return Ok(SBSDIO_HT_AVAIL | SBSDIO_ALP_AVAIL);
    }
    #[cfg(target_os = "none")]
    {
        let mut last_chipclk = 0u8;
        if !cyw43_sdio_cmd52_write(1, SBSDIO_FUNC1_CHIPCLKCSR, SBSDIO_HT_AVAIL_REQ) {
            return Err(FAULT_CYW43_POST_RELEASE_HT);
        }
        for _ in 0..SDHCI_INIT_SPINS {
            let Some(chipclk) = cyw43_sdio_cmd52_read(1, SBSDIO_FUNC1_CHIPCLKCSR) else {
                return Err(FAULT_CYW43_POST_RELEASE_HT);
            };
            last_chipclk = chipclk;
            if chipclk & SBSDIO_HT_AVAIL != 0 {
                return Ok(chipclk);
            }
            if chipclk & SBSDIO_HT_AVAIL_REQ == 0
                && !cyw43_sdio_cmd52_write(1, SBSDIO_FUNC1_CHIPCLKCSR, SBSDIO_HT_AVAIL_REQ)
            {
                return Err(FAULT_CYW43_POST_RELEASE_HT);
            }
            core::hint::spin_loop();
        }
        cyw43_record_last_fault_with_result(FAULT_CYW43_POST_RELEASE_HT, u32::from(last_chipclk));
        Err(FAULT_CYW43_POST_RELEASE_HT)
    }
}

const fn cyw43_function2_force_ht_clock_value(chipclk: u8) -> u8 {
    if chipclk & SBSDIO_HT_AVAIL != 0 {
        chipclk | SBSDIO_HT_AVAIL_REQ | SBSDIO_FORCE_HT
    } else {
        SBSDIO_HT_AVAIL_REQ
    }
}

fn cyw43_force_ht_clock_for_function2() -> Result<u8, u16> {
    #[cfg(not(target_os = "none"))]
    {
        return Ok(SBSDIO_HT_AVAIL | SBSDIO_HT_AVAIL_REQ | SBSDIO_FORCE_HT);
    }
    #[cfg(target_os = "none")]
    {
        let Some(before) = cyw43_sdio_cmd52_read(1, SBSDIO_FUNC1_CHIPCLKCSR) else {
            return Err(FAULT_CYW43_POST_RELEASE_HT);
        };
        if before & SBSDIO_HT_AVAIL == 0 {
            cyw43_record_last_fault_with_result(FAULT_CYW43_POST_RELEASE_HT, u32::from(before));
            return Err(FAULT_CYW43_POST_RELEASE_HT);
        }
        let forced = cyw43_function2_force_ht_clock_value(before);
        if !cyw43_sdio_cmd52_write(1, SBSDIO_FUNC1_CHIPCLKCSR, forced) {
            cyw43_record_last_fault_with_result(FAULT_CYW43_POST_RELEASE_HT, u32::from(forced));
            return Err(FAULT_CYW43_POST_RELEASE_HT);
        }
        let Some(after) = cyw43_sdio_cmd52_read(1, SBSDIO_FUNC1_CHIPCLKCSR) else {
            return Err(FAULT_CYW43_POST_RELEASE_HT);
        };
        if after & SBSDIO_HT_AVAIL == 0 {
            cyw43_record_last_fault_with_result(FAULT_CYW43_POST_RELEASE_HT, u32::from(after));
            return Err(FAULT_CYW43_POST_RELEASE_HT);
        }
        Ok(after)
    }
}

fn cyw43_enable_post_release_function2() -> Result<u8, u16> {
    #[cfg(not(target_os = "none"))]
    {
        return Ok(SDIO_FUNC_READY_1 | SDIO_FUNC_READY_2);
    }
    #[cfg(target_os = "none")]
    {
        let current_ioex = cyw43_sdio_cmd52_read(0, SDIO_CCCR_IOEX).unwrap_or(0);
        let desired_ioex = current_ioex | SDIO_FUNC_ENABLE_2;
        let mut last_iordy = 0u8;
        for attempt in 0..=CYW43_SDIO_F2_READY_REENABLE_RETRIES {
            if attempt != 0 {
                let cleared = desired_ioex & !SDIO_FUNC_ENABLE_2;
                if !cyw43_sdio_cmd52_write(0, SDIO_CCCR_IOEX, cleared) {
                    cyw43_record_last_fault_with_result(
                        FAULT_CYW43_POST_RELEASE_F2_READY,
                        u32::from(desired_ioex) << 8 | u32::from(last_iordy),
                    );
                    return Err(FAULT_CYW43_POST_RELEASE_F2_READY);
                }
                cyw43_spin_wait(CYW43_SDIO_F2_REENABLE_SETTLE_SPINS);
                if let Err(detail) = cyw43_force_ht_clock_for_function2() {
                    return Err(detail);
                }
            }
            if !cyw43_sdio_cmd52_write(0, SDIO_CCCR_IOEX, desired_ioex) {
                cyw43_record_last_fault_with_result(
                    FAULT_CYW43_POST_RELEASE_F2_READY,
                    u32::from(desired_ioex) << 8 | u32::from(last_iordy),
                );
                return Err(FAULT_CYW43_POST_RELEASE_F2_READY);
            }
            for _ in 0..CYW43_SDIO_WAIT_F2_READY_POLLS {
                let Some(iordy) = cyw43_sdio_cmd52_read(0, SDIO_CCCR_IORX) else {
                    cyw43_record_last_fault_with_result(
                        FAULT_CYW43_POST_RELEASE_F2_READY,
                        u32::from(desired_ioex) << 8 | u32::from(last_iordy),
                    );
                    return Err(FAULT_CYW43_POST_RELEASE_F2_READY);
                };
                last_iordy = iordy;
                if iordy & SDIO_FUNC_READY_2 != 0 {
                    if !cyw43_set_function_block_size(2, SDIO_FUNCTION2_BLOCK_SIZE) {
                        cyw43_record_last_fault_with_result(
                            FAULT_CYW43_POST_RELEASE_F2_READY,
                            u32::from(desired_ioex) << 8 | u32::from(last_iordy),
                        );
                        return Err(FAULT_CYW43_POST_RELEASE_F2_READY);
                    }
                    return Ok(iordy);
                }
                core::hint::spin_loop();
            }
        }
        cyw43_record_last_fault_with_result(
            FAULT_CYW43_POST_RELEASE_F2_READY,
            (u32::from(desired_ioex) << 8) | u32::from(last_iordy),
        );
        Err(FAULT_CYW43_POST_RELEASE_F2_READY)
    }
}

fn cyw43_arm_post_release_function_interrupts() -> Result<(), u16> {
    #[cfg(not(target_os = "none"))]
    {
        Ok(())
    }
    #[cfg(target_os = "none")]
    {
        if cyw43_sdio_cmd52_write(0, SDIO_CCCR_IENX, SDIO_INTERRUPT_ENABLE_MASK) {
            Ok(())
        } else {
            cyw43_record_last_fault_with_result(
                FAULT_CYW43_POST_RELEASE_F2_READY,
                u32::from(SDIO_INTERRUPT_ENABLE_MASK),
            );
            Err(FAULT_CYW43_POST_RELEASE_F2_READY)
        }
    }
}

fn cyw43_rearm_post_release_function_interrupts_if_needed(
    interrupt_enable: Option<u8>,
) -> Option<u8> {
    if !cyw43_sdio_interrupt_enable_needs_rearm(interrupt_enable) {
        return interrupt_enable;
    }
    if !cyw43_sdio_cmd52_write(0, SDIO_CCCR_IENX, SDIO_INTERRUPT_ENABLE_MASK) {
        return interrupt_enable;
    }
    cyw43_sdio_cmd52_read(0, SDIO_CCCR_IENX).or(interrupt_enable)
}

const fn cyw43_sdio_interrupt_enable_needs_rearm(interrupt_enable: Option<u8>) -> bool {
    match interrupt_enable {
        Some(value) => value != SDIO_INTERRUPT_ENABLE_MASK,
        None => false,
    }
}

fn cyw43_require_post_release_corecontrol_ready(state: &mut Cyw43RuntimeState) -> Result<u32, u16> {
    let Some(corecontrol) =
        cyw43_backplane_read_u32(state, CYW43_SDIO_CORE_BASE + SDIO_CORECONTROL)
    else {
        return Err(cyw43_take_last_fault_detail().unwrap_or(FAULT_CYW43_POST_RELEASE_CORECONTROL));
    };
    if corecontrol & CC_F2RDY != 0 {
        return Ok(corecontrol);
    }
    cyw43_record_last_fault_with_result(FAULT_CYW43_POST_RELEASE_CORECONTROL, corecontrol);
    Err(FAULT_CYW43_POST_RELEASE_CORECONTROL)
}

const fn cyw43_mailbox_version_payload() -> u32 {
    SDPCM_PROT_VERSION << HMB_DATA_VERSION_SHIFT
}

const fn cyw43_firmware_mailbox_version(mailbox: u32) -> u32 {
    (mailbox & HMB_DATA_VERSION_MASK) >> HMB_DATA_VERSION_SHIFT
}

const fn cyw43_firmware_mailbox_has_ready_bit(mailbox: u32) -> bool {
    (mailbox & (HMB_DATA_DEVREADY | HMB_DATA_FWREADY)) != 0
}

const fn cyw43_firmware_mailbox_version_accepted(mailbox: u32) -> bool {
    let version = cyw43_firmware_mailbox_version(mailbox);
    version == 0 || version == SDPCM_PROT_VERSION
}

const fn cyw43_firmware_mailbox_ready(mailbox: u32) -> bool {
    cyw43_firmware_mailbox_has_ready_bit(mailbox)
        && cyw43_firmware_mailbox_version_accepted(mailbox)
}

fn cyw43_write_firmware_mailbox_version(state: &mut Cyw43RuntimeState) -> Result<(), u16> {
    if cyw43_backplane_write_u32(
        state,
        CYW43_SDIO_CORE_BASE + SDPCMD_REG_TOSBMAILBOXDATA,
        cyw43_mailbox_version_payload(),
    ) {
        Ok(())
    } else {
        Err(cyw43_take_last_fault_detail().unwrap_or(FAULT_CYW43_POST_RELEASE_MAILBOX_READY))
    }
}

fn cyw43_wait_for_firmware_mailbox_ready(_state: &mut Cyw43RuntimeState) -> Result<u32, u16> {
    #[cfg(not(target_os = "none"))]
    {
        return Ok(HMB_DATA_DEVREADY | HMB_DATA_FWREADY | cyw43_mailbox_version_payload());
    }
    #[cfg(target_os = "none")]
    {
        let mut last_mailbox = 0u32;
        for _ in 0..CYW43_POST_RELEASE_MAILBOX_POLLS {
            let Some(mailbox) = cyw43_backplane_read_u32(
                _state,
                CYW43_SDIO_CORE_BASE + SDPCMD_REG_TOHOSTMAILBOXDATA,
            ) else {
                return Err(cyw43_take_last_fault_detail()
                    .unwrap_or(FAULT_CYW43_POST_RELEASE_MAILBOX_READY));
            };
            last_mailbox = mailbox;
            if cyw43_firmware_mailbox_ready(mailbox) {
                return Ok(mailbox);
            }
            if cyw43_firmware_mailbox_has_ready_bit(mailbox) {
                cyw43_record_last_fault_with_result(
                    FAULT_CYW43_POST_RELEASE_PROTOCOL_VERSION,
                    mailbox,
                );
                return Err(FAULT_CYW43_POST_RELEASE_PROTOCOL_VERSION);
            }
            core::hint::spin_loop();
        }
        cyw43_record_last_fault_with_result(FAULT_CYW43_POST_RELEASE_MAILBOX_READY, last_mailbox);
        Err(FAULT_CYW43_POST_RELEASE_MAILBOX_READY)
    }
}

fn cyw43_hold_armcr4_for_firmware_upload(state: &mut Cyw43RuntimeState) -> Result<(), u16> {
    let prereset_ioctrl = cyw43_core_reset_prepare_hold_value(ARMCR4_BCMA_IOCTL_CPUHALT);
    if !cyw43_ai_core_write8(
        state,
        CYW43_ARMCR4_CORE_BASE,
        AI_IOCTRL_OFFSET,
        prereset_ioctrl,
    ) {
        return Err(cyw43_take_last_fault_detail().unwrap_or(FAULT_CYW43_BACKPLANE_ARMCR4_RESET));
    }
    cyw43_spin_wait(cyw43_core_control_settle_spins(CYW43_ARMCR4_CORE_BASE));
    let reset_ready = cyw43_ai_core_write8(
        state,
        CYW43_ARMCR4_CORE_BASE,
        AI_RESETCTRL_OFFSET,
        AI_RESETCTRL_BIT_RESET,
    );
    if !reset_ready
        && cyw43_armcr4_reset_stage_advisory_skip(true, false, cyw43_take_last_fault_detail())?
    {
        cyw43_reset_firmware_retry_clock(state);
        state.backplane_window_valid = false;
        cyw43_clear_last_fault();
        return Ok(());
    }
    if !reset_ready {
        return Err(cyw43_take_last_fault_detail().unwrap_or(FAULT_CYW43_BACKPLANE_ARMCR4_RESET));
    }
    if !cyw43_ai_core_write8(
        state,
        CYW43_ARMCR4_CORE_BASE,
        AI_IOCTRL_OFFSET,
        prereset_ioctrl,
    ) {
        return Err(cyw43_take_last_fault_detail().unwrap_or(FAULT_CYW43_BACKPLANE_ARMCR4_RESET));
    }
    cyw43_reset_firmware_retry_clock(state);
    cyw43_clear_last_fault();
    Ok(())
}

fn cyw43_armcr4_reset_stage_advisory_skip(
    ioctl_ready: bool,
    reset_ready: bool,
    fault: Option<u16>,
) -> Result<bool, u16> {
    if reset_ready {
        return Ok(false);
    }
    if !ioctl_ready {
        return Err(fault.unwrap_or(FAULT_CYW43_BACKPLANE_ARMCR4_RESET));
    }
    if matches!(
        fault,
        Some(
            FAULT_SDIO_DESCRIPTOR_UNAVAILABLE
                | FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED
                | FAULT_CYW43_FIRMWARE_RETRY_EXHAUSTED
        )
    ) {
        return Ok(true);
    }
    Err(fault.unwrap_or(FAULT_CYW43_BACKPLANE_ARMCR4_RESET))
}

fn cyw43_disable_d11_cores_for_firmware(state: &mut Cyw43RuntimeState) {
    for &base in CYW43_D11_CORE_BASES.iter() {
        if !cyw43_core_disable(
            state,
            base,
            D11_BCMA_IOCTL_PHYRESET | D11_BCMA_IOCTL_PHYCLOCKEN,
            D11_BCMA_IOCTL_PHYCLOCKEN,
        ) {
            state.backplane_window_valid = false;
            cyw43_clear_last_fault();
        }
    }
}

fn cyw43_prepare_socram_for_armcr4_upload(state: &mut Cyw43RuntimeState) -> Result<(), u16> {
    if cyw43_socram_core_reset_required_before_armcr4_upload()
        && (!cyw43_core_disable(state, CYW43_SOCRAM_CORE_BASE, 0, 0)
            || !cyw43_core_reset(state, CYW43_SOCRAM_CORE_BASE, 0, 0, 0))
    {
        return Err(cyw43_take_last_fault_detail().unwrap_or(FAULT_CYW43_BACKPLANE_ARMCR4_RESET));
    }
    Ok(())
}

const fn cyw43_socram_core_reset_required_before_armcr4_upload() -> bool {
    false
}

const fn cyw43_core_control_settle_spins(base: u32) -> usize {
    if base == CYW43_ARMCR4_CORE_BASE {
        CYW43_ARMCR4_CONTROL_SETTLE_SPINS
    } else {
        CYW43_CORE_CONTROL_SETTLE_SPINS
    }
}

const fn cyw43_core_reset_prepare_hold_value(reset: u8) -> u8 {
    reset | AI_CORE_PRERESET_IOCTRL
}

fn cyw43_core_disable(state: &mut Cyw43RuntimeState, base: u32, prereset: u8, reset: u8) -> bool {
    let prereset_ioctrl = prereset | AI_CORE_PRERESET_IOCTRL;
    if !cyw43_ai_core_write8(state, base, AI_IOCTRL_OFFSET, prereset_ioctrl) {
        return false;
    }
    cyw43_spin_wait(cyw43_core_control_settle_spins(base));
    if !cyw43_ai_core_write8(state, base, AI_RESETCTRL_OFFSET, AI_RESETCTRL_BIT_RESET) {
        return false;
    }
    cyw43_spin_wait(cyw43_core_control_settle_spins(base));
    if !cyw43_ai_core_write8(
        state,
        base,
        AI_IOCTRL_OFFSET,
        cyw43_core_reset_prepare_hold_value(reset),
    ) {
        return false;
    }
    cyw43_spin_wait(cyw43_core_control_settle_spins(base));
    true
}

fn cyw43_core_reset(
    state: &mut Cyw43RuntimeState,
    base: u32,
    prereset: u8,
    reset: u8,
    postreset: u8,
) -> bool {
    if !cyw43_core_disable(state, base, prereset, reset) {
        return false;
    }
    if !cyw43_ai_core_write8(
        state,
        base,
        AI_IOCTRL_OFFSET,
        cyw43_core_reset_prepare_hold_value(reset),
    ) {
        return false;
    }
    cyw43_spin_wait(cyw43_core_control_settle_spins(base));
    if !cyw43_ai_core_write8(state, base, AI_RESETCTRL_OFFSET, 0) {
        return false;
    }
    cyw43_spin_wait(cyw43_core_control_settle_spins(base));
    if !cyw43_ai_core_write8(
        state,
        base,
        AI_IOCTRL_OFFSET,
        postreset | AI_CORE_POSTRESET_IOCTRL,
    ) {
        return false;
    }
    cyw43_spin_wait(cyw43_core_control_settle_spins(base));
    true
}

fn cyw43_ai_core_write8(state: &mut Cyw43RuntimeState, base: u32, offset: u32, value: u8) -> bool {
    let Some(addr) = base.checked_add(offset) else {
        cyw43_record_last_fault(FAULT_CYW43_BACKPLANE_WINDOW);
        return false;
    };
    if cyw43_backplane_write8(state, addr, value) {
        true
    } else {
        if cyw43_take_last_fault_detail().is_none() {
            cyw43_record_last_fault(FAULT_CYW43_BACKPLANE_ARMCR4_RESET);
        }
        false
    }
}

const fn cyw43_cardcap_command_decode_value() -> u8 {
    SDIO_CCCR_BRCM_CARDCAP_CMD14_SUPPORT | SDIO_CCCR_BRCM_CARDCAP_CMD14_EXT
}

fn cyw43_publish_release_progress(sequence: u32, phase: u32) {
    publish_runtime_progress(sequence, phase, DRIVER_RUNTIME_CYW43_COMMAND_AUX);
}

fn cyw43_release_firmware(state: &mut Cyw43RuntimeState, reset_vector: u32, sequence: u32) -> bool {
    cyw43_publish_release_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_CYW43_RELEASE_BEGIN);
    if !state.transport_ready
        || !state.firmware_uploaded
        || !state.nvram_uploaded
        || !state.nvram_tail_uploaded
    {
        return false;
    }
    if reset_vector != 0 {
        cyw43_publish_release_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_CYW43_RELEASE_RESET_VECTOR_BEGIN,
        );
        if !cyw43_backplane_write_u32(state, CYW43_FIRMWARE_RESET_VECTOR_ADDR, reset_vector) {
            return false;
        }
    }
    cyw43_publish_release_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_RELEASE_ARMCR4_RESET_BEGIN,
    );
    if !cyw43_core_reset(
        state,
        CYW43_ARMCR4_CORE_BASE,
        ARMCR4_BCMA_IOCTL_CPUHALT,
        0,
        0,
    ) {
        return false;
    }
    cyw43_publish_release_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_RELEASE_UPLOAD_CLOCK_BEGIN,
    );
    if !cyw43_promote_firmware_upload_clock(state) {
        return false;
    }
    cyw43_publish_release_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_RELEASE_POST_CONFIG_BEGIN,
    );
    if let Err(detail) = cyw43_prepare_post_release_function2(state) {
        cyw43_record_last_fault(detail);
        return false;
    }
    cyw43_publish_release_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_RELEASE_HT_CLOCK_BEGIN,
    );
    if let Err(detail) = cyw43_require_post_release_ht_clock() {
        if cyw43_take_last_fault_detail().is_none() {
            cyw43_record_last_fault(detail);
        }
        return false;
    }
    if let Err(detail) = cyw43_force_ht_clock_for_function2() {
        if cyw43_take_last_fault_detail().is_none() {
            cyw43_record_last_fault(detail);
        }
        return false;
    }
    cyw43_publish_release_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_RELEASE_MAILBOX_VERSION_BEGIN,
    );
    if let Err(detail) = cyw43_write_firmware_mailbox_version(state) {
        if cyw43_take_last_fault_detail().is_none() {
            cyw43_record_last_fault(detail);
        }
        return false;
    }
    cyw43_publish_release_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_RELEASE_F2_ENABLE_BEGIN,
    );
    if let Err(detail) = cyw43_enable_post_release_function2() {
        if cyw43_take_last_fault_detail().is_none() {
            cyw43_record_last_fault(detail);
        }
        return false;
    }
    if let Err(detail) = cyw43_arm_post_release_function_interrupts() {
        if cyw43_take_last_fault_detail().is_none() {
            cyw43_record_last_fault(detail);
        }
        return false;
    }
    cyw43_publish_release_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_RELEASE_INT_MASK_BEGIN,
    );
    if !cyw43_backplane_write_u32(
        state,
        CYW43_SDIO_CORE_BASE + SDPCMD_REG_HOSTINTMASK,
        HOSTINTMASK,
    ) || !cyw43_backplane_write_u32(
        state,
        CYW43_SDIO_CORE_BASE + SDPCMD_REG_FUNCTIONINTMASK,
        FUNCTIONINTMASK,
    ) {
        return false;
    }
    cyw43_publish_release_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_RELEASE_CORECONTROL_BEGIN,
    );
    if let Err(detail) = cyw43_require_post_release_corecontrol_ready(state) {
        if cyw43_take_last_fault_detail().is_none() {
            cyw43_record_last_fault(detail);
        }
        return false;
    }
    cyw43_publish_release_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_RELEASE_FIRMWARE_READY_BEGIN,
    );
    if let Err(detail) = cyw43_wait_for_firmware_mailbox_ready(state) {
        if cyw43_take_last_fault_detail().is_none() {
            cyw43_record_last_fault(detail);
        }
        return false;
    }
    if !cyw43_backplane_write_u32(state, CYW43_SDIO_CORE_BASE + SDIO_INT_STATUS, u32::MAX) {
        cyw43_clear_last_fault();
    }
    cyw43_publish_release_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_RELEASE_FIRMWARE_READY_DONE,
    );
    true
}

fn cyw43_sdio_cmd52_read(function: u8, addr: u32) -> Option<u8> {
    #[cfg(target_os = "none")]
    if cyw43_uses_sdio_bus_link() {
        return cyw43_sdio_cmd52_read_via_bus_link(function, addr);
    }
    sdio_execute_transfer(
        SDIO_CMD52,
        sdio_cmd52_arg(false, function, addr, 0),
        DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        DriverFrameDescriptor::empty(),
        1,
        0,
    )
    .map(|response| (response & 0xff) as u8)
}

fn cyw43_sdio_cmd52_write(function: u8, addr: u32, value: u8) -> bool {
    #[cfg(target_os = "none")]
    if cyw43_uses_sdio_bus_link() {
        return cyw43_sdio_cmd52_write_via_bus_link(function, addr, value);
    }
    sdio_execute_transfer(
        SDIO_CMD52,
        sdio_cmd52_arg(true, function, addr, value),
        DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        DriverFrameDescriptor::empty(),
        1,
        0,
    )
    .is_some()
}

#[cfg(target_os = "none")]
fn cyw43_sdio_cmd52_read_via_bus_link(function: u8, addr: u32) -> Option<u8> {
    if !sdio_bus_link_payload_bounds(CYW43_SDIO_BUS_LINK_DATA_OFFSET, 1) {
        return None;
    }
    let sequence = CYW43_SDIO_BUS_LINK_SEQ
        .fetch_add(1, Ordering::AcqRel)
        .wrapping_add(1)
        .max(1);
    let command = sdio_bus_link_cmd52_descriptor_command(sequence, false, function, addr)?;
    let completion = sdio_bus_link_call(command)?;
    if completion.sequence != sequence
        || completion.code != COMPLETION_FRAME_READY
        || completion.frame.offset as usize != CYW43_SDIO_BUS_LINK_DATA_OFFSET
        || completion.frame.len == 0
    {
        return None;
    }
    driver_task_shared_invalidate_range(
        DRIVER_TASK_SDIO_BUS_RING_VADDR + CYW43_SDIO_BUS_LINK_DATA_OFFSET,
        1,
    );
    driver_task_shared_load_barrier();
    Some(read_sdio_bus_payload_byte(CYW43_SDIO_BUS_LINK_DATA_OFFSET))
}

#[cfg(target_os = "none")]
fn cyw43_sdio_cmd52_write_via_bus_link(function: u8, addr: u32, value: u8) -> bool {
    if !sdio_bus_link_payload_bounds(CYW43_SDIO_BUS_LINK_DATA_OFFSET, 1) {
        return false;
    }
    write_sdio_bus_payload_byte(CYW43_SDIO_BUS_LINK_DATA_OFFSET, value);
    driver_task_shared_store_barrier();
    driver_task_shared_clean_range(
        DRIVER_TASK_SDIO_BUS_RING_VADDR + CYW43_SDIO_BUS_LINK_DATA_OFFSET,
        1,
    );
    let sequence = CYW43_SDIO_BUS_LINK_SEQ
        .fetch_add(1, Ordering::AcqRel)
        .wrapping_add(1)
        .max(1);
    let Some(command) = sdio_bus_link_cmd52_descriptor_command(sequence, true, function, addr)
    else {
        return false;
    };
    sdio_bus_link_call(command).is_some_and(|completion| {
        completion.sequence == sequence
            && completion.code == COMPLETION_PROGRESS
            && completion.result == 1
    })
}

fn cyw43_backplane_set_window(state: &mut Cyw43RuntimeState, addr: u32) -> bool {
    let window = addr & BACKPLANE_WINDOW_MASK;
    if state.backplane_window_valid && state.backplane_window == window {
        return true;
    }
    let (low, mid, high) = cyw43_backplane_window_register_bytes(addr);
    if cyw43_sdio_cmd52_write(1, SBSDIO_FUNC1_SBADDRLOW, low)
        && cyw43_sdio_cmd52_write(1, SBSDIO_FUNC1_SBADDRMID, mid)
        && cyw43_sdio_cmd52_write(1, SBSDIO_FUNC1_SBADDRHIGH, high)
    {
        state.backplane_window = window;
        state.backplane_window_valid = true;
        true
    } else {
        if cyw43_take_last_fault_detail().is_none() {
            cyw43_record_last_fault(FAULT_CYW43_BACKPLANE_WINDOW);
        }
        false
    }
}

const fn cyw43_backplane_window_register_bytes(addr: u32) -> (u8, u8, u8) {
    let window = addr & BACKPLANE_WINDOW_MASK;
    (
        ((window >> 8) & 0xff) as u8,
        ((window >> 16) & 0xff) as u8,
        ((window >> 24) & 0xff) as u8,
    )
}

const fn cyw43_backplane_function_addr(addr: u32) -> u32 {
    (addr & BACKPLANE_ADDRESS_MASK) | BACKPLANE_32BIT_FLAG
}

const fn cyw43_backplane_cmd53_increment(_byte_mode_fallback: bool) -> bool {
    true
}

#[cfg(test)]
fn cyw43_backplane_write_chunk_shape(
    firmware_released: bool,
    byte_mode_fallback: bool,
    remaining: usize,
) -> (usize, u16, u16) {
    cyw43_backplane_write_chunk_shape_for_lane(
        firmware_released,
        byte_mode_fallback,
        false,
        remaining,
    )
}

fn cyw43_backplane_write_chunk_shape_for_lane(
    firmware_released: bool,
    byte_mode_fallback: bool,
    narrow_byte_mode_fallback: bool,
    remaining: usize,
) -> (usize, u16, u16) {
    if firmware_released {
        let chunk_len = remaining.min(SDIO_FUNCTION2_BLOCK_SIZE as usize);
        (chunk_len, chunk_len as u16, 1)
    } else if byte_mode_fallback || CYW43_LINKED_PRE_RELEASE_BYTE_MODE_PRIMARY {
        let byte_chunk = if narrow_byte_mode_fallback {
            CYW43_FIRMWARE_BYTE_MODE_NARROW_CHUNK_BYTES
        } else {
            CYW43_FIRMWARE_BYTE_MODE_CHUNK_BYTES
        };
        let chunk_len = remaining.min(byte_chunk);
        (chunk_len, chunk_len as u16, 0)
    } else if remaining > SDIO_CMD53_BYTE_MODE_MAX {
        let block_len = SDIO_FUNCTION1_BLOCK_SIZE as usize;
        let max_block_len = CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES.min(511 * block_len);
        let block_count = (remaining.min(max_block_len) / block_len).min(511);
        let chunk_len = block_count * SDIO_FUNCTION1_BLOCK_SIZE as usize;
        (chunk_len, SDIO_FUNCTION1_BLOCK_SIZE, block_count as u16)
    } else {
        let chunk_len = remaining.min(SDIO_CMD53_BYTE_MODE_MAX);
        (chunk_len, chunk_len as u16, 0)
    }
}

const fn cyw43_backplane_write_prefers_byte_mode_at_window_edge(
    firmware_released: bool,
    byte_mode_fallback: bool,
    transfer_remaining: usize,
    window_remaining: usize,
) -> bool {
    !firmware_released
        && !byte_mode_fallback
        && transfer_remaining >= window_remaining
        && window_remaining < SDIO_FUNCTION1_BLOCK_SIZE as usize
}

fn cyw43_prepare_firmware_upload_retry(state: &mut Cyw43RuntimeState) -> bool {
    if state.firmware_released {
        return false;
    }
    state.backplane_window_valid = false;
    loop {
        if usize::from(state.firmware_retry_clock_index)
            >= CYW43_SDIO_FIRMWARE_RETRY_CLOCKS_HZ.len()
        {
            if !state.firmware_byte_mode_fallback {
                state.firmware_byte_mode_fallback = true;
                state.firmware_narrow_byte_mode_fallback = false;
                state.firmware_retry_clock_index = 0;
                continue;
            }
            if !state.firmware_narrow_byte_mode_fallback {
                state.firmware_narrow_byte_mode_fallback = true;
                state.firmware_retry_clock_index = 0;
                continue;
            }
            return false;
        }
        let retry_index = usize::from(state.firmware_retry_clock_index);
        let clock_hz = CYW43_SDIO_FIRMWARE_RETRY_CLOCKS_HZ[retry_index];
        state.firmware_retry_clock_index = state.firmware_retry_clock_index.saturating_add(1);
        let _ = cyw43_sdio_cmd52_write(
            0,
            SDIO_CCCR_IF,
            cyw43_firmware_retry_card_if_for_lane(state.firmware_byte_mode_fallback, retry_index),
        );
        let flags = cyw43_firmware_retry_host_flags_for_lane(
            state.firmware_byte_mode_fallback,
            retry_index,
        );
        if cyw43_configure_sdio_host(clock_hz, flags) {
            return true;
        }
    }
}

const fn cyw43_firmware_retry_card_if(retry_index: usize) -> u8 {
    if retry_index == 0 {
        0
    } else {
        SDIO_BUS_WIDTH_4BIT
    }
}

const fn cyw43_firmware_retry_host_flags(retry_index: usize) -> u16 {
    if retry_index == 0 {
        0
    } else {
        DriverRuntimeSdioCommandDescriptor::FLAG_HOST_BUS_WIDTH_4BIT
            | DriverRuntimeSdioCommandDescriptor::FLAG_HOST_HIGH_SPEED
    }
}

const fn cyw43_firmware_retry_card_if_for_lane(byte_mode_fallback: bool, retry_index: usize) -> u8 {
    if byte_mode_fallback {
        0
    } else {
        cyw43_firmware_retry_card_if(retry_index)
    }
}

const fn cyw43_firmware_retry_host_flags_for_lane(
    byte_mode_fallback: bool,
    retry_index: usize,
) -> u16 {
    if byte_mode_fallback {
        0
    } else {
        cyw43_firmware_retry_host_flags(retry_index)
    }
}

fn cyw43_force_conservative_firmware_byte_replay(state: &mut Cyw43RuntimeState) -> bool {
    if state.firmware_released {
        return false;
    }
    state.firmware_byte_mode_fallback = true;
    state.firmware_narrow_byte_mode_fallback = false;
    state.firmware_retry_clock_index = 1;
    state.backplane_window_valid = false;
    let _ = cyw43_sdio_cmd52_write(0, SDIO_CCCR_IF, 0);
    if cyw43_configure_sdio_host(CYW43_SDIO_FIRMWARE_RETRY_CLOCKS_HZ[0], 0) {
        true
    } else {
        cyw43_record_last_fault(FAULT_CYW43_TRANSPORT_HOST_BUS_WIDTH);
        false
    }
}

fn cyw43_promote_firmware_upload_clock(state: &mut Cyw43RuntimeState) -> bool {
    if state.firmware_retry_clock_index == 0 {
        return true;
    }
    let high_speed_flags = match cyw43_enable_sdio_high_speed_timing() {
        Ok(true) => DriverRuntimeSdioCommandDescriptor::FLAG_HOST_HIGH_SPEED,
        Ok(false) => 0,
        Err(detail) => {
            cyw43_record_last_fault(detail);
            return false;
        }
    };
    if !cyw43_configure_sdio_host(
        CYW43_SDIO_FAST_CLOCK_HZ,
        DriverRuntimeSdioCommandDescriptor::FLAG_HOST_BUS_WIDTH_4BIT | high_speed_flags,
    ) {
        cyw43_record_last_fault(FAULT_CYW43_TRANSPORT_HOST_BUS_WIDTH);
        return false;
    }
    state.firmware_retry_clock_index = 0;
    true
}

fn cyw43_reset_firmware_retry_clock(state: &mut Cyw43RuntimeState) {
    state.firmware_retry_clock_index = 0;
}

fn cyw43_prepare_retryable_firmware_command(state: &mut Cyw43RuntimeState) {
    if state.firmware_released {
        return;
    }
    if CYW43_LINKED_PRE_RELEASE_BYTE_MODE_PRIMARY {
        let _ = cyw43_force_conservative_firmware_byte_replay(state);
        state.firmware_narrow_byte_mode_fallback = true;
    } else {
        state.firmware_retry_clock_index = 0;
        state.firmware_byte_mode_fallback = false;
        state.firmware_narrow_byte_mode_fallback = false;
    }
    state.backplane_window_valid = false;
}

fn cyw43_firmware_upload_retries_exhausted(state: &Cyw43RuntimeState) -> bool {
    !state.firmware_released
        && state.firmware_byte_mode_fallback
        && state.firmware_narrow_byte_mode_fallback
        && usize::from(state.firmware_retry_clock_index)
            >= CYW43_SDIO_FIRMWARE_RETRY_CLOCKS_HZ.len()
}

fn cyw43_reset_firmware_stage(state: &mut Cyw43RuntimeState) {
    state.firmware_stage_addr = 0;
    state.firmware_stage_len = 0;
    state.firmware_stage_flush_offset = 0;
}

fn cyw43_firmware_stage_covers(
    state: &Cyw43RuntimeState,
    target_addr: u32,
    payload_len: usize,
) -> bool {
    let stage_len = usize::from(state.firmware_stage_len);
    if stage_len == 0 || payload_len == 0 {
        return false;
    }
    let Some(stage_end) = state.firmware_stage_addr.checked_add(stage_len as u32) else {
        return false;
    };
    let Some(target_end) = target_addr.checked_add(payload_len as u32) else {
        return false;
    };
    target_addr >= state.firmware_stage_addr && target_end <= stage_end
}

fn cyw43_runtime_ranges_overlap(
    a_offset: usize,
    a_len: usize,
    b_offset: usize,
    b_len: usize,
) -> bool {
    if a_len == 0 || b_len == 0 {
        return false;
    }
    let Some(a_end) = a_offset.checked_add(a_len) else {
        return true;
    };
    let Some(b_end) = b_offset.checked_add(b_len) else {
        return true;
    };
    a_offset < b_end && b_offset < a_end
}

fn cyw43_firmware_stage_flush_clobbers_payload(
    state: &Cyw43RuntimeState,
    payload_offset: usize,
    payload_len: usize,
) -> bool {
    cyw43_runtime_ranges_overlap(
        CYW43_FIRMWARE_STAGE_OFFSET,
        usize::from(state.firmware_stage_len),
        payload_offset,
        payload_len,
    )
}

fn cyw43_save_firmware_payload_scratch(
    state: &mut Cyw43RuntimeState,
    payload_offset: usize,
    payload_len: usize,
) {
    for index in 0..payload_len {
        state.firmware_stage_scratch[index] = read_runtime_payload_byte(payload_offset + index);
    }
}

fn cyw43_flush_firmware_stage(state: &mut Cyw43RuntimeState) -> bool {
    let len = usize::from(state.firmware_stage_len);
    let flush_offset = usize::from(state.firmware_stage_flush_offset);
    if len == 0 {
        return true;
    }
    if len > CYW43_FIRMWARE_STAGE_BYTES || flush_offset > len {
        cyw43_record_firmware_range_fault(CYW43_FIRMWARE_RANGE_STAGE_PAYLOAD);
        return false;
    }
    if flush_offset == len {
        cyw43_reset_firmware_stage(state);
        return true;
    }
    for index in flush_offset..len {
        write_runtime_payload_byte(
            CYW43_FIRMWARE_STAGE_OFFSET + index,
            state.firmware_stage[index],
        );
    }
    let Some(flush_addr) = state.firmware_stage_addr.checked_add(flush_offset as u32) else {
        cyw43_record_firmware_range_fault(CYW43_FIRMWARE_RANGE_STAGE_ADDR);
        return false;
    };
    match cyw43_backplane_write_ring_with_mode_result(
        state,
        flush_addr,
        CYW43_FIRMWARE_STAGE_OFFSET + flush_offset,
        len - flush_offset,
        false,
    ) {
        Ok(()) => {
            cyw43_reset_firmware_stage(state);
            true
        }
        Err(bytes_written) => {
            let next_offset = flush_offset.saturating_add(bytes_written).min(len);
            state.firmware_stage_flush_offset = next_offset as u16;
            false
        }
    }
}

fn cyw43_stage_firmware_chunk(
    state: &mut Cyw43RuntimeState,
    target_addr: u32,
    payload_offset: usize,
    payload_len: usize,
    stream_complete: bool,
    force_byte_mode: bool,
) -> bool {
    if payload_len == 0 || payload_len > CYW43_FIRMWARE_STAGE_BYTES {
        cyw43_record_firmware_range_fault(CYW43_FIRMWARE_RANGE_STAGE_PAYLOAD);
        return false;
    }
    let mut stage_len = usize::from(state.firmware_stage_len);
    if stage_len > CYW43_FIRMWARE_STAGE_BYTES {
        cyw43_record_firmware_range_fault(CYW43_FIRMWARE_RANGE_STAGE_PAYLOAD);
        return false;
    }
    let mut payload_saved = false;
    if stage_len == 0 {
        state.firmware_stage_addr = target_addr;
        state.firmware_stage_flush_offset = 0;
    } else if stage_len == CYW43_FIRMWARE_STAGE_BYTES {
        if cyw43_firmware_stage_covers(state, target_addr, payload_len) {
            if force_byte_mode && !cyw43_force_conservative_firmware_byte_replay(state) {
                return false;
            }
            return cyw43_flush_firmware_stage(state);
        }
        if state
            .firmware_stage_addr
            .checked_add(u32::from(state.firmware_stage_len))
            .is_none()
        {
            cyw43_record_firmware_range_fault(CYW43_FIRMWARE_RANGE_STAGE_ADDR);
            return false;
        }
        if cyw43_firmware_stage_flush_clobbers_payload(state, payload_offset, payload_len) {
            cyw43_save_firmware_payload_scratch(state, payload_offset, payload_len);
            payload_saved = true;
        }
        if force_byte_mode && !cyw43_force_conservative_firmware_byte_replay(state) {
            return false;
        }
        if !cyw43_flush_firmware_stage(state) {
            return false;
        }
        state.firmware_stage_addr = target_addr;
    } else if state
        .firmware_stage_addr
        .checked_add(u32::from(state.firmware_stage_len))
        != Some(target_addr)
    {
        if force_byte_mode && !cyw43_force_conservative_firmware_byte_replay(state) {
            return false;
        }
        if cyw43_firmware_stage_covers(state, target_addr, payload_len) {
            return cyw43_flush_firmware_stage(state);
        }
        if cyw43_firmware_stage_flush_clobbers_payload(state, payload_offset, payload_len) {
            cyw43_save_firmware_payload_scratch(state, payload_offset, payload_len);
            payload_saved = true;
        }
        if !cyw43_flush_firmware_stage(state) {
            return false;
        }
        state.firmware_stage_addr = target_addr;
    }
    stage_len = usize::from(state.firmware_stage_len);
    let Some(next_stage_len) = stage_len.checked_add(payload_len) else {
        cyw43_record_firmware_range_fault(CYW43_FIRMWARE_RANGE_STAGE_APPEND);
        return false;
    };
    if next_stage_len > CYW43_FIRMWARE_STAGE_BYTES {
        cyw43_record_firmware_range_fault(CYW43_FIRMWARE_RANGE_STAGE_APPEND);
        return false;
    }
    for index in 0..payload_len {
        state.firmware_stage[stage_len + index] = if payload_saved {
            state.firmware_stage_scratch[index]
        } else {
            read_runtime_payload_byte(payload_offset + index)
        };
    }
    state.firmware_stage_len = next_stage_len as u16;
    if force_byte_mode && !cyw43_force_conservative_firmware_byte_replay(state) {
        return false;
    }
    if next_stage_len == CYW43_FIRMWARE_STAGE_BYTES || stream_complete {
        if cyw43_flush_firmware_stage(state) {
            true
        } else {
            // Preserve the failed window so the owner-link retry path can
            // replay the exact firmware bytes without restarting SDIO/CYW43.
            false
        }
    } else {
        true
    }
}

fn cyw43_backplane_write_ring(
    state: &mut Cyw43RuntimeState,
    addr: u32,
    ring_offset: usize,
    len: usize,
) -> bool {
    cyw43_backplane_write_ring_with_mode(state, addr, ring_offset, len, false)
}

fn cyw43_backplane_write_ring_with_mode(
    state: &mut Cyw43RuntimeState,
    addr: u32,
    ring_offset: usize,
    len: usize,
    force_byte_mode: bool,
) -> bool {
    cyw43_backplane_write_ring_with_mode_result(state, addr, ring_offset, len, force_byte_mode)
        .is_ok()
}

fn cyw43_backplane_write_ring_with_mode_result(
    state: &mut Cyw43RuntimeState,
    addr: u32,
    ring_offset: usize,
    len: usize,
    force_byte_mode: bool,
) -> Result<(), usize> {
    let mut done = 0usize;
    while done < len {
        loop {
            let Some(chunk_addr) = addr.checked_add(done as u32) else {
                return Err(done);
            };
            if !cyw43_backplane_set_window(state, chunk_addr) {
                if cyw43_prepare_firmware_upload_retry(state) {
                    continue;
                }
                let last_fault = cyw43_take_last_fault_detail();
                let last_result = cyw43_take_last_fault_result();
                if cyw43_firmware_upload_retries_exhausted(state) {
                    cyw43_record_last_fault_with_result(
                        FAULT_CYW43_FIRMWARE_RETRY_EXHAUSTED,
                        last_result,
                    );
                } else if last_fault.is_none() {
                    cyw43_record_last_fault(FAULT_CYW43_TRANSPORT_BUS_LINK);
                }
                cyw43_prepare_retryable_firmware_command(state);
                return Err(done);
            }
            let window_offset = (chunk_addr as usize) & BACKPLANE_ADDRESS_MASK as usize;
            let window_remaining =
                (BACKPLANE_ADDRESS_MASK as usize + 1).saturating_sub(window_offset);
            let transfer_remaining = len - done;
            let edge_byte_mode = cyw43_backplane_write_prefers_byte_mode_at_window_edge(
                state.firmware_released,
                state.firmware_byte_mode_fallback,
                transfer_remaining,
                window_remaining,
            );
            let byte_mode_fallback =
                force_byte_mode || state.firmware_byte_mode_fallback || edge_byte_mode;
            let (chunk_len, block_size, block_count) = cyw43_backplane_write_chunk_shape_for_lane(
                state.firmware_released,
                byte_mode_fallback,
                state.firmware_narrow_byte_mode_fallback,
                transfer_remaining.min(window_remaining),
            );
            let frame = DriverFrameDescriptor {
                offset: (ring_offset + done) as u32,
                len: chunk_len as u16,
                flags: 0,
            };
            if sdio_execute_transfer(
                SDIO_CMD53,
                sdio_cmd53_arg(
                    true,
                    1,
                    cyw43_backplane_function_addr(chunk_addr),
                    cyw43_backplane_cmd53_increment(byte_mode_fallback),
                    block_count,
                    chunk_len as u16,
                ),
                DRIVER_RUNTIME_SDIO_FLAG_DATA
                    | DRIVER_RUNTIME_SDIO_FLAG_WRITE
                    | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
                frame,
                block_size,
                block_count,
            )
            .is_none()
            {
                if cyw43_prepare_firmware_upload_retry(state) {
                    continue;
                }
                let last_fault = cyw43_take_last_fault_detail();
                let last_result = cyw43_take_last_fault_result();
                if cyw43_firmware_upload_retries_exhausted(state) {
                    cyw43_record_last_fault_with_result(
                        FAULT_CYW43_FIRMWARE_RETRY_EXHAUSTED,
                        last_result,
                    );
                } else if last_fault.is_none() {
                    cyw43_record_last_fault(FAULT_CYW43_TRANSPORT_BUS_LINK);
                }
                cyw43_prepare_retryable_firmware_command(state);
                return Err(done);
            }
            done += chunk_len;
            cyw43_reset_firmware_retry_clock(state);
            break;
        }
    }
    Ok(())
}

fn cyw43_backplane_write_u32(state: &mut Cyw43RuntimeState, addr: u32, value: u32) -> bool {
    write_ring_u32(DRIVER_TASK_RING_FRAME_OFFSET, value);
    if cyw43_backplane_write_ring(state, addr, DRIVER_TASK_RING_FRAME_OFFSET, 4) {
        return true;
    }
    let first_fault = cyw43_take_last_fault_detail();
    state.backplane_window_valid = false;
    cyw43_clear_last_fault();
    if cyw43_backplane_write_u32_cmd52_current_window(state, addr, value) {
        cyw43_reset_firmware_retry_clock(state);
        cyw43_clear_last_fault();
        return true;
    }
    if let Some(detail) = first_fault {
        cyw43_record_last_fault(detail);
    }
    false
}

fn cyw43_backplane_write8(state: &mut Cyw43RuntimeState, addr: u32, value: u8) -> bool {
    if !cyw43_backplane_set_window(state, addr) {
        return false;
    }
    cyw43_sdio_cmd52_write(1, addr & BACKPLANE_ADDRESS_MASK, value)
}

fn cyw43_backplane_read_u32(state: &mut Cyw43RuntimeState, addr: u32) -> Option<u32> {
    cyw43_backplane_read_u32_cmd53(state, addr, cyw43_backplane_function_addr(addr), true)
        .or_else(|| {
            state.backplane_window_valid = false;
            cyw43_clear_last_fault();
            cyw43_backplane_read_u32_cmd52_current_window(state, addr)
        })
        .or_else(|| {
            state.backplane_window_valid = false;
            cyw43_clear_last_fault();
            cyw43_backplane_read_u32_cmd53(state, addr, cyw43_backplane_function_addr(addr), false)
        })
}

fn cyw43_backplane_read_u32_cmd53(
    state: &mut Cyw43RuntimeState,
    addr: u32,
    function_addr: u32,
    increment: bool,
) -> Option<u32> {
    if !cyw43_backplane_set_window(state, addr) {
        return None;
    }
    let frame = DriverFrameDescriptor {
        offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
        len: 4,
        flags: 0,
    };
    sdio_execute_transfer(
        SDIO_CMD53,
        sdio_cmd53_arg(false, 1, function_addr, increment, 0, 4),
        DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        frame,
        4,
        0,
    )?;
    Some(read_ring_u32(DRIVER_TASK_RING_FRAME_OFFSET))
}

fn cyw43_backplane_read_u32_cmd52_current_window(
    state: &mut Cyw43RuntimeState,
    addr: u32,
) -> Option<u32> {
    if !cyw43_backplane_set_window(state, addr) {
        return None;
    }
    let base = addr & BACKPLANE_ADDRESS_MASK;
    let mut bytes = [0u8; 4];
    for (index, byte) in bytes.iter_mut().enumerate() {
        let Some(byte_addr) = base.checked_add(index as u32) else {
            cyw43_record_last_fault(FAULT_CYW43_BACKPLANE_WINDOW);
            return None;
        };
        *byte = cyw43_sdio_cmd52_read(1, byte_addr)?;
    }
    Some(u32::from_le_bytes(bytes))
}

fn cyw43_backplane_write_u32_cmd52_current_window(
    state: &mut Cyw43RuntimeState,
    addr: u32,
    value: u32,
) -> bool {
    if !cyw43_backplane_set_window(state, addr) {
        return false;
    }
    let base = addr & BACKPLANE_ADDRESS_MASK;
    for (index, byte) in value.to_le_bytes().iter().copied().enumerate() {
        let Some(byte_addr) = base.checked_add(index as u32) else {
            cyw43_record_last_fault(FAULT_CYW43_BACKPLANE_WINDOW);
            return false;
        };
        if !cyw43_sdio_cmd52_write(1, byte_addr, byte) {
            return false;
        }
    }
    true
}

fn cyw43_stage_sdpcm_tx(state: &mut Cyw43RuntimeState, frame: DriverFrameDescriptor) -> usize {
    cyw43_submit_sdpcm_frame(state, frame, true, false)
}

const fn cyw43_function2_cmd53_shape(request_len: usize) -> (u16, u16) {
    if request_len >= CYW43_FUNCTION2_BLOCK_BYTES && request_len % CYW43_FUNCTION2_BLOCK_BYTES == 0
    {
        (
            CYW43_FUNCTION2_BLOCK_BYTES as u16,
            (request_len / CYW43_FUNCTION2_BLOCK_BYTES) as u16,
        )
    } else {
        (request_len as u16, 0)
    }
}

fn cyw43_ram_payload_bounds(addr: u32, len: u16) -> bool {
    let Some(end) = addr.checked_add(u32::from(len)) else {
        return false;
    };
    addr >= CYW43_RAM_BASE_4345
        && end <= CYW43_RAM_BASE_4345.saturating_add(CYW43_RAM_SIZE_4345_PI4)
}

fn cyw43_submit_sdpcm_frame(
    state: &mut Cyw43RuntimeState,
    frame: DriverFrameDescriptor,
    data_frame: bool,
    control_ext_header: bool,
) -> usize {
    if !state.initialized || !state.transport_ready || !state.firmware_released {
        return 0;
    }
    let payload_len = frame.len as usize;
    let header_len = if data_frame {
        CYW43_SDPCM_DATA_TX_OVERHEAD_BYTES
    } else if control_ext_header {
        CYW43_SDPCM_CONTROL_TX_EXT_HEADER_BYTES
    } else {
        CYW43_SDPCM_HEADER_BYTES
    };
    if payload_len == 0 || payload_len > CYW43_RING_PAGE_PAYLOAD_BYTES.saturating_sub(header_len) {
        cyw43_record_last_fault(cyw43_command_fault_detail(if data_frame {
            DRIVER_RUNTIME_CYW43_OP_ETH_TX
        } else {
            DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME
        }));
        return 0;
    }
    let total_len = payload_len + header_len;
    let seq = state.sdpcm_seq;
    if !has_sdpcm_credit(state.sdpcm_seq, state.sdpcm_seq_max) {
        return 0;
    }
    let request_len = if data_frame {
        align_to(total_len, CYW43_FUNCTION2_BLOCK_BYTES)
    } else if control_ext_header {
        cyw43_control_tx_request_len(total_len)
    } else {
        align4(total_len)
    };
    if request_len > CYW43_RING_PAGE_PAYLOAD_BYTES {
        cyw43_record_last_fault(cyw43_command_fault_detail(if data_frame {
            DRIVER_RUNTIME_CYW43_OP_ETH_TX
        } else {
            DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME
        }));
        return 0;
    }
    if data_frame {
        cyw43_write_sdpcm_data_tx_header(DRIVER_TASK_RING_FRAME_OFFSET, total_len, seq);
        let bdc_priority = cyw43_bdc_priority_for_ring_packet(frame.offset as usize, payload_len);
        write_ring_byte(
            DRIVER_TASK_RING_FRAME_OFFSET + CYW43_SDPCM_DATA_TX_BDC_OFFSET,
            CYW43_BDC_VERSION << CYW43_BDC_VERSION_SHIFT,
        );
        write_ring_byte(
            DRIVER_TASK_RING_FRAME_OFFSET + CYW43_SDPCM_DATA_TX_BDC_OFFSET + 1,
            bdc_priority,
        );
        write_ring_byte(
            DRIVER_TASK_RING_FRAME_OFFSET + CYW43_SDPCM_DATA_TX_BDC_OFFSET + 2,
            0,
        );
        write_ring_byte(
            DRIVER_TASK_RING_FRAME_OFFSET + CYW43_SDPCM_DATA_TX_BDC_OFFSET + 3,
            0,
        );
        copy_ring_range(
            frame.offset as usize,
            DRIVER_TASK_RING_FRAME_OFFSET + CYW43_SDPCM_DATA_TX_OVERHEAD_BYTES,
            payload_len,
        );
    } else {
        cyw43_write_sdpcm_control_tx_header(
            DRIVER_TASK_RING_FRAME_OFFSET,
            request_len,
            total_len,
            CYW43_SDPCM_HEADER_BYTES,
            header_len,
            seq,
            control_ext_header,
        );
        copy_ring_range(
            frame.offset as usize,
            DRIVER_TASK_RING_FRAME_OFFSET + header_len,
            payload_len,
        );
    }
    for index in total_len..request_len {
        write_ring_byte(DRIVER_TASK_RING_FRAME_OFFSET + index, 0);
    }
    let (block_size, block_count) = cyw43_function2_cmd53_shape(request_len);
    let tx_frame = DriverFrameDescriptor {
        offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
        len: request_len as u16,
        flags: 0,
    };
    if sdio_execute_transfer(
        SDIO_CMD53,
        sdio_cmd53_arg(
            true,
            2,
            BACKPLANE_32BIT_FLAG,
            false,
            block_count,
            request_len as u16,
        ),
        DRIVER_RUNTIME_SDIO_FLAG_DATA
            | DRIVER_RUNTIME_SDIO_FLAG_WRITE
            | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        tx_frame,
        block_size,
        block_count,
    )
    .is_none()
    {
        return 0;
    }
    state.sdpcm_seq = state.sdpcm_seq.wrapping_add(1);
    state.tx_frames = state.tx_frames.saturating_add(1);
    total_len
}

fn cyw43_runtime_poll_rx(
    state: &mut Cyw43RuntimeState,
    wanted_mask: u16,
) -> Option<DriverFrameDescriptor> {
    match cyw43_runtime_poll_rx_detailed(state, wanted_mask, 0, false) {
        Cyw43RxPollResult::Frame(frame) => Some(frame),
        Cyw43RxPollResult::Idle(_) => None,
    }
}

fn cyw43_runtime_poll_rx_detailed(
    state: &mut Cyw43RuntimeState,
    wanted_mask: u16,
    sequence: u32,
    allow_hintless_firstread: bool,
) -> Cyw43RxPollResult {
    if !state.initialized || !state.transport_ready || !state.firmware_released {
        return Cyw43RxPollResult::Idle(Cyw43RxIdleReason::NotReady);
    }
    let mut decoded_unmatched = false;
    for _ in 0..CYW43_RX_DRAIN_BUDGET {
        if let Some(frame) = cyw43_rx_queue_pop_matching(state, wanted_mask) {
            state.rx_frames = state.rx_frames.saturating_add(1);
            return Cyw43RxPollResult::Frame(frame);
        }
        let frame_len = match cyw43_runtime_next_rx_frame_len(state) {
            Ok(Some(frame_len)) => frame_len,
            Ok(None) => {
                if !decoded_unmatched && allow_hintless_firstread {
                    if cyw43_hintless_firstread_uses_block_probe_first(wanted_mask) {
                        return cyw43_runtime_poll_rx_hintless_block_probe(
                            state,
                            wanted_mask,
                            sequence,
                        );
                    }
                    return cyw43_runtime_poll_rx_hintless_firstread(state, wanted_mask, sequence);
                }
                let reason = if decoded_unmatched {
                    Cyw43RxIdleReason::SdpcmDecodeMiss
                } else {
                    Cyw43RxIdleReason::NoRframe
                };
                return Cyw43RxPollResult::Idle(reason);
            }
            Err(reason) => return Cyw43RxPollResult::Idle(reason),
        };
        let frame = match cyw43_runtime_read_rx_frame(state, frame_len) {
            Ok(()) => cyw43_runtime_decode_rx_frame_for(
                state,
                CYW43_RUNTIME_RX_BUFFER_OFFSET,
                frame_len,
                wanted_mask,
            ),
            Err(reason) => return Cyw43RxPollResult::Idle(reason),
        };
        if let Some(frame) = frame {
            state.rx_frames = state.rx_frames.saturating_add(1);
            return Cyw43RxPollResult::Frame(frame);
        }
        decoded_unmatched = true;
        if state.sdpcm_next_frame_len == 0 && state.rx_queue_count >= CYW43_RX_QUEUE_CAP as u8 {
            break;
        }
    }
    Cyw43RxPollResult::Idle(Cyw43RxIdleReason::SdpcmDecodeMiss)
}

fn cyw43_runtime_next_rx_frame_len(
    state: &mut Cyw43RuntimeState,
) -> Result<Option<usize>, Cyw43RxIdleReason> {
    if let Some(frame_len) = cyw43_take_sdpcm_next_frame_len(state) {
        return Ok(Some(frame_len));
    }
    let Some(lo) = cyw43_sdio_cmd52_read(1, SBSDIO_FUNC1_RFRAMEBCLO) else {
        return Err(Cyw43RxIdleReason::RframeCountReadFailed);
    };
    let Some(hi) = cyw43_sdio_cmd52_read(1, SBSDIO_FUNC1_RFRAMEBCHI) else {
        return Err(Cyw43RxIdleReason::RframeCountReadFailed);
    };
    let frame_len = usize::from(lo) | (usize::from(hi) << 8);
    if frame_len == 0 {
        return Ok(None);
    }
    if !cyw43_sdpcm_frame_len_valid(frame_len) {
        return Err(Cyw43RxIdleReason::InvalidRframeLength(frame_len));
    }
    Ok(Some(frame_len))
}

fn cyw43_runtime_read_rx_frame(
    _state: &mut Cyw43RuntimeState,
    frame_len: usize,
) -> Result<(), Cyw43RxIdleReason> {
    if !cyw43_sdpcm_frame_len_valid(frame_len) {
        return Err(Cyw43RxIdleReason::InvalidRframeLength(frame_len));
    }
    let request_len = align_to(frame_len, CYW43_FUNCTION2_BLOCK_BYTES);
    if request_len > CYW43_RUNTIME_RX_BUFFER_BYTES {
        return Err(Cyw43RxIdleReason::RxRequestTooLarge(request_len));
    }
    let rx_frame = DriverFrameDescriptor {
        offset: CYW43_RUNTIME_RX_BUFFER_OFFSET as u32,
        len: request_len as u16,
        flags: 0,
    };
    let (block_size, block_count) = cyw43_function2_cmd53_shape(request_len);
    if sdio_execute_transfer(
        SDIO_CMD53,
        sdio_cmd53_arg(
            false,
            2,
            BACKPLANE_32BIT_FLAG,
            false,
            block_count,
            request_len as u16,
        ),
        DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        rx_frame,
        block_size,
        block_count,
    )
    .is_none()
    {
        return Err(Cyw43RxIdleReason::Function2ReadFailed);
    }
    Ok(())
}

const fn cyw43_hintless_firstread_uses_block_probe_first(wanted_mask: u16) -> bool {
    wanted_mask == CYW43_RX_FRAME_FLAG_MASK_DATA
}

fn cyw43_runtime_poll_rx_hintless_firstread(
    state: &mut Cyw43RuntimeState,
    wanted_mask: u16,
    sequence: u32,
) -> Cyw43RxPollResult {
    cyw43_publish_control_rx_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_RX_FIRSTREAD_BEGIN,
    );
    let rx_frame = DriverFrameDescriptor {
        offset: CYW43_RUNTIME_RX_BUFFER_OFFSET as u32,
        len: CYW43_CONTROL_RX_FIRSTREAD_BYTES as u16,
        flags: 0,
    };
    let (block_size, block_count) = cyw43_function2_cmd53_shape(CYW43_CONTROL_RX_FIRSTREAD_BYTES);
    if sdio_execute_transfer(
        SDIO_CMD53,
        sdio_cmd53_arg(
            false,
            2,
            BACKPLANE_32BIT_FLAG,
            false,
            block_count,
            CYW43_CONTROL_RX_FIRSTREAD_BYTES as u16,
        ),
        DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        rx_frame,
        block_size,
        block_count,
    )
    .is_none()
    {
        return Cyw43RxPollResult::Idle(Cyw43RxIdleReason::FirstreadFailed);
    }
    cyw43_publish_control_rx_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_RX_FIRSTREAD_DONE,
    );
    let Some(header) = cyw43_rx_sdpcm_header_prefix_at(
        CYW43_RUNTIME_RX_BUFFER_OFFSET,
        CYW43_CONTROL_RX_FIRSTREAD_BYTES,
        CYW43_CONTROL_RX_FIRSTREAD_CAPACITY,
    ) else {
        if cyw43_sdpcm_firstread_prefix_empty(CYW43_RUNTIME_RX_BUFFER_OFFSET) {
            return cyw43_runtime_poll_rx_hintless_block_probe(state, wanted_mask, sequence);
        }
        cyw43_publish_control_rx_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_RX_FIRSTREAD_INVALID,
        );
        return Cyw43RxPollResult::Idle(Cyw43RxIdleReason::FirstreadInvalidSdpcm(
            cyw43_sdpcm_firstread_prefix_signature(CYW43_RUNTIME_RX_BUFFER_OFFSET),
        ));
    };
    cyw43_runtime_finish_hintless_firstread(
        state,
        wanted_mask,
        sequence,
        CYW43_CONTROL_RX_FIRSTREAD_BYTES,
        header,
    )
}

fn cyw43_runtime_poll_rx_hintless_block_probe(
    state: &mut Cyw43RuntimeState,
    wanted_mask: u16,
    sequence: u32,
) -> Cyw43RxPollResult {
    match cyw43_runtime_read_hintless_block_probe_once(state, wanted_mask, sequence) {
        Cyw43HintlessBlockProbeResult::Frame(frame) => Cyw43RxPollResult::Frame(frame),
        Cyw43HintlessBlockProbeResult::Idle(reason) => Cyw43RxPollResult::Idle(reason),
        Cyw43HintlessBlockProbeResult::Empty => {
            let source = cyw43_rx_source_snapshot(state, CYW43_CONTROL_RX_BLOCK_PROBE_BYTES as u16);
            if cyw43_rx_source_asserts_pending_frame(source) {
                return cyw43_runtime_recover_asserted_empty_firstread(
                    state,
                    wanted_mask,
                    sequence,
                    source,
                );
            }
            Cyw43RxPollResult::Idle(Cyw43RxIdleReason::FirstreadEmpty {
                probe_len: CYW43_CONTROL_RX_BLOCK_PROBE_BYTES,
                source,
            })
        }
    }
}

enum Cyw43HintlessBlockProbeResult {
    Frame(DriverFrameDescriptor),
    Empty,
    Idle(Cyw43RxIdleReason),
}

fn cyw43_runtime_read_hintless_block_probe_once(
    state: &mut Cyw43RuntimeState,
    wanted_mask: u16,
    sequence: u32,
) -> Cyw43HintlessBlockProbeResult {
    cyw43_publish_control_rx_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_RX_FIRSTREAD_BEGIN,
    );
    let rx_frame = DriverFrameDescriptor {
        offset: CYW43_RUNTIME_RX_BUFFER_OFFSET as u32,
        len: CYW43_CONTROL_RX_BLOCK_PROBE_BYTES as u16,
        flags: 0,
    };
    let (block_size, block_count) = cyw43_function2_cmd53_shape(CYW43_CONTROL_RX_BLOCK_PROBE_BYTES);
    if sdio_execute_transfer(
        SDIO_CMD53,
        sdio_cmd53_arg(
            false,
            2,
            BACKPLANE_32BIT_FLAG,
            false,
            block_count,
            CYW43_CONTROL_RX_BLOCK_PROBE_BYTES as u16,
        ),
        DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        rx_frame,
        block_size,
        block_count,
    )
    .is_none()
    {
        return Cyw43HintlessBlockProbeResult::Idle(Cyw43RxIdleReason::FirstreadFailed);
    }
    cyw43_publish_control_rx_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_RX_FIRSTREAD_DONE,
    );
    let Some(header) = cyw43_rx_sdpcm_header_prefix_at(
        CYW43_RUNTIME_RX_BUFFER_OFFSET,
        CYW43_CONTROL_RX_BLOCK_PROBE_BYTES,
        CYW43_CONTROL_RX_BLOCK_PROBE_CAPACITY,
    ) else {
        if cyw43_sdpcm_firstread_prefix_empty(CYW43_RUNTIME_RX_BUFFER_OFFSET) {
            cyw43_publish_control_rx_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_RX_FIRSTREAD_EMPTY,
            );
            return Cyw43HintlessBlockProbeResult::Empty;
        }
        cyw43_publish_control_rx_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_RX_FIRSTREAD_INVALID,
        );
        return Cyw43HintlessBlockProbeResult::Idle(Cyw43RxIdleReason::FirstreadInvalidSdpcm(
            cyw43_sdpcm_firstread_prefix_signature(CYW43_RUNTIME_RX_BUFFER_OFFSET),
        ));
    };
    match cyw43_runtime_finish_hintless_firstread(
        state,
        wanted_mask,
        sequence,
        CYW43_CONTROL_RX_BLOCK_PROBE_BYTES,
        header,
    ) {
        Cyw43RxPollResult::Frame(frame) => Cyw43HintlessBlockProbeResult::Frame(frame),
        Cyw43RxPollResult::Idle(reason) => Cyw43HintlessBlockProbeResult::Idle(reason),
    }
}

fn cyw43_runtime_recover_asserted_empty_firstread(
    state: &mut Cyw43RuntimeState,
    wanted_mask: u16,
    sequence: u32,
    first_source: Cyw43RxSourceSnapshot,
) -> Cyw43RxPollResult {
    let mut source =
        cyw43_rx_source_snapshot_force(state, CYW43_CONTROL_RX_BLOCK_PROBE_BYTES as u16)
            .unwrap_or(first_source);
    if let Some(result) = cyw43_runtime_read_rframe_if_present(state, wanted_mask) {
        return result;
    }
    for _ in 0..CYW43_RX_SOURCE_ASSERTED_EMPTY_RETRY_READS {
        match cyw43_runtime_read_hintless_block_probe_once(state, wanted_mask, sequence) {
            Cyw43HintlessBlockProbeResult::Frame(frame) => {
                return Cyw43RxPollResult::Frame(frame);
            }
            Cyw43HintlessBlockProbeResult::Idle(reason) => {
                return Cyw43RxPollResult::Idle(reason);
            }
            Cyw43HintlessBlockProbeResult::Empty => {
                source = cyw43_rx_source_snapshot_force(
                    state,
                    CYW43_CONTROL_RX_BLOCK_PROBE_BYTES as u16,
                )
                .unwrap_or(source);
            }
        }
    }
    let reason = if cyw43_rx_source_asserts_pending_frame(source) {
        Cyw43RxIdleReason::FirstreadSourceAssertedEmpty {
            probe_len: CYW43_CONTROL_RX_BLOCK_PROBE_BYTES,
            source,
        }
    } else {
        Cyw43RxIdleReason::FirstreadEmpty {
            probe_len: CYW43_CONTROL_RX_BLOCK_PROBE_BYTES,
            source,
        }
    };
    Cyw43RxPollResult::Idle(reason)
}

fn cyw43_runtime_read_rframe_if_present(
    state: &mut Cyw43RuntimeState,
    wanted_mask: u16,
) -> Option<Cyw43RxPollResult> {
    let frame_len = match cyw43_runtime_next_rx_frame_len(state) {
        Ok(Some(frame_len)) => frame_len,
        Ok(None) => return None,
        Err(reason) => return Some(Cyw43RxPollResult::Idle(reason)),
    };
    let frame = match cyw43_runtime_read_rx_frame(state, frame_len) {
        Ok(()) => cyw43_runtime_decode_rx_frame_for(
            state,
            CYW43_RUNTIME_RX_BUFFER_OFFSET,
            frame_len,
            wanted_mask,
        ),
        Err(reason) => return Some(Cyw43RxPollResult::Idle(reason)),
    };
    if let Some(frame) = frame {
        state.rx_frames = state.rx_frames.saturating_add(1);
        Some(Cyw43RxPollResult::Frame(frame))
    } else {
        Some(Cyw43RxPollResult::Idle(Cyw43RxIdleReason::SdpcmDecodeMiss))
    }
}

fn cyw43_runtime_finish_hintless_firstread(
    state: &mut Cyw43RuntimeState,
    wanted_mask: u16,
    sequence: u32,
    prefix_len: usize,
    header: Cyw43RxSdpcmHeader,
) -> Cyw43RxPollResult {
    if header.packet_len > prefix_len {
        let Some(remainder_request_len) =
            cyw43_control_rx_remainder_request_len(prefix_len, header.packet_len)
        else {
            return Cyw43RxPollResult::Idle(Cyw43RxIdleReason::FirstreadRemainderTooLarge(
                header.packet_len,
            ));
        };
        let remainder_frame = DriverFrameDescriptor {
            offset: (CYW43_RUNTIME_RX_BUFFER_OFFSET + prefix_len) as u32,
            len: remainder_request_len as u16,
            flags: 0,
        };
        let (block_size, block_count) = cyw43_function2_cmd53_shape(remainder_request_len);
        if sdio_execute_transfer(
            SDIO_CMD53,
            sdio_cmd53_arg(
                false,
                2,
                BACKPLANE_32BIT_FLAG,
                false,
                block_count,
                remainder_request_len as u16,
            ),
            DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
            remainder_frame,
            block_size,
            block_count,
        )
        .is_none()
        {
            cyw43_publish_control_rx_progress(
                sequence,
                DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_RX_REMAINDER_FAILED,
            );
            return Cyw43RxPollResult::Idle(Cyw43RxIdleReason::FirstreadRemainderFailed);
        }
    }
    let frame = cyw43_runtime_decode_rx_frame_for(
        state,
        CYW43_RUNTIME_RX_BUFFER_OFFSET,
        header.packet_len,
        wanted_mask,
    );
    if frame.is_some() {
        cyw43_publish_control_rx_progress(
            sequence,
            DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_RX_FIRSTREAD_FRAME,
        );
        state.rx_frames = state.rx_frames.saturating_add(1);
    }
    frame.map_or(
        Cyw43RxPollResult::Idle(Cyw43RxIdleReason::SdpcmDecodeMiss),
        Cyw43RxPollResult::Frame,
    )
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Cyw43ControlReply {
    cmd: u32,
    id: u16,
    status: u32,
    response_len: u32,
    payload_available: usize,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43RxPollResult {
    Frame(DriverFrameDescriptor),
    Idle(Cyw43RxIdleReason),
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct Cyw43RxSourceSnapshot {
    probe_len: u16,
    interrupt_enable: u8,
    frame_indicated: bool,
    host_interrupt: bool,
    card_interrupt: bool,
    function2_ready: bool,
    passive: bool,
    cached: bool,
}

impl Cyw43RxSourceSnapshot {
    const fn empty() -> Self {
        Self {
            probe_len: 0,
            interrupt_enable: 0,
            frame_indicated: false,
            host_interrupt: false,
            card_interrupt: false,
            function2_ready: false,
            passive: false,
            cached: false,
        }
    }

    const fn passive(probe_len: u16) -> Self {
        Self {
            probe_len,
            interrupt_enable: 0,
            frame_indicated: false,
            host_interrupt: false,
            card_interrupt: false,
            function2_ready: false,
            passive: true,
            cached: false,
        }
    }

    const fn with_probe_len(self, probe_len: u16) -> Self {
        Self { probe_len, ..self }
    }

    const fn cached(self, probe_len: u16) -> Self {
        Self {
            probe_len,
            cached: true,
            ..self
        }
    }

    const fn encode(self) -> u32 {
        let mut result = DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_MAGIC
            | self.probe_len as u32
            | ((self.interrupt_enable as u32) << DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_IEN_SHIFT);
        if self.frame_indicated {
            result |= DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_FRAME_INDICATED;
        }
        if self.host_interrupt {
            result |= DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_HOST_INTERRUPT;
        }
        if self.card_interrupt {
            result |= DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_CARD_INTERRUPT;
        }
        if self.function2_ready {
            result |= DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_FUNCTION2_READY;
        }
        if self.passive {
            result |= DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_PASSIVE;
        }
        if self.cached {
            result |= DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_CACHED;
        }
        result
    }
}

fn cyw43_rx_source_snapshot(
    state: &mut Cyw43RuntimeState,
    probe_len: u16,
) -> Cyw43RxSourceSnapshot {
    let using_bus_link = cyw43_uses_sdio_bus_link();
    state.rx_source_empty_polls = state.rx_source_empty_polls.saturating_add(1);
    if !cyw43_rx_source_snapshot_sample_due(
        using_bus_link,
        state.rx_source_snapshot_valid,
        state.rx_source_empty_polls,
    ) {
        return cyw43_cached_rx_source_snapshot(state, probe_len);
    }
    let Some(snapshot) = cyw43_sample_rx_source_snapshot(state, probe_len) else {
        return cyw43_cached_rx_source_snapshot(state, probe_len);
    };
    state.rx_source_snapshot = snapshot.with_probe_len(0);
    state.rx_source_snapshot_valid = true;
    snapshot
}

fn cyw43_rx_source_snapshot_force(
    state: &mut Cyw43RuntimeState,
    probe_len: u16,
) -> Option<Cyw43RxSourceSnapshot> {
    let snapshot = cyw43_sample_rx_source_snapshot(state, probe_len)?;
    state.rx_source_snapshot = snapshot.with_probe_len(0);
    state.rx_source_snapshot_valid = true;
    Some(snapshot)
}

fn cyw43_sample_rx_source_snapshot(
    state: &mut Cyw43RuntimeState,
    probe_len: u16,
) -> Option<Cyw43RxSourceSnapshot> {
    if !cyw43_rx_source_snapshot_queries_card(cyw43_uses_sdio_bus_link()) {
        return None;
    }
    let interrupt_enable = cyw43_rearm_post_release_function_interrupts_if_needed(
        cyw43_sdio_cmd52_read(0, SDIO_CCCR_IENX),
    );
    let iordy = cyw43_sdio_cmd52_read(0, SDIO_CCCR_IORX);
    let int_status = cyw43_backplane_read_u32(state, CYW43_SDIO_CORE_BASE + SDIO_INT_STATUS);
    if interrupt_enable.is_none() && iordy.is_none() && int_status.is_none() {
        return None;
    }
    let sdhci_status = cyw43_sdio_host_int_status_snapshot();
    Some(Cyw43RxSourceSnapshot {
        probe_len,
        interrupt_enable: interrupt_enable.unwrap_or(0),
        frame_indicated: int_status.unwrap_or(0) & I_HMB_FRAME_IND != 0,
        host_interrupt: int_status.unwrap_or(0) & HOSTINTMASK != 0,
        card_interrupt: sdhci_status & SDHCI_INT_CARD_INT != 0,
        function2_ready: iordy.unwrap_or(0) & SDIO_FUNC_READY_2 != 0,
        passive: false,
        cached: false,
    })
}

fn cyw43_cached_rx_source_snapshot(
    state: &Cyw43RuntimeState,
    probe_len: u16,
) -> Cyw43RxSourceSnapshot {
    if state.rx_source_snapshot_valid {
        return state.rx_source_snapshot.cached(probe_len);
    }
    Cyw43RxSourceSnapshot::passive(probe_len)
}

const fn cyw43_rx_source_asserts_pending_frame(source: Cyw43RxSourceSnapshot) -> bool {
    !source.passive
        && source.function2_ready
        && (source.frame_indicated || source.host_interrupt || source.card_interrupt)
}

const fn cyw43_rx_source_snapshot_queries_card(using_bus_link: bool) -> bool {
    let _ = using_bus_link;
    true
}

const fn cyw43_rx_source_snapshot_sample_due(
    using_bus_link: bool,
    snapshot_valid: bool,
    empty_polls: u32,
) -> bool {
    !using_bus_link
        || !snapshot_valid
        || empty_polls == 1
        || empty_polls % CYW43_RX_SOURCE_SAMPLE_INTERVAL_EMPTY_POLLS == 0
}

fn cyw43_sdio_host_int_status_snapshot() -> u32 {
    if !cyw43_sdio_host_int_status_visible_to_cyw43(cyw43_uses_sdio_bus_link()) {
        return 0;
    }
    sdio_read32(SDHCI_INT_STATUS)
}

const fn cyw43_sdio_host_int_status_visible_to_cyw43(using_bus_link: bool) -> bool {
    !using_bus_link
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Cyw43RxIdleReason {
    NotReady,
    RframeCountReadFailed,
    NoRframe,
    InvalidRframeLength(usize),
    RxRequestTooLarge(usize),
    Function2ReadFailed,
    SdpcmDecodeMiss,
    FirstreadFailed,
    FirstreadEmpty {
        probe_len: usize,
        source: Cyw43RxSourceSnapshot,
    },
    FirstreadSourceAssertedEmpty {
        probe_len: usize,
        source: Cyw43RxSourceSnapshot,
    },
    FirstreadInvalidSdpcm(u32),
    FirstreadRemainderFailed,
    FirstreadRemainderTooLarge(usize),
}

const fn cyw43_rx_idle_detail(reason: Cyw43RxIdleReason) -> u16 {
    match reason {
        Cyw43RxIdleReason::NotReady => DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_NOT_READY,
        Cyw43RxIdleReason::RframeCountReadFailed => {
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_RFRAME_READ_FAILED
        }
        Cyw43RxIdleReason::NoRframe => DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_NO_RFRAME,
        Cyw43RxIdleReason::InvalidRframeLength(_) => {
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_INVALID_RFRAME_LEN
        }
        Cyw43RxIdleReason::RxRequestTooLarge(_) => {
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_RX_REQUEST_TOO_LARGE
        }
        Cyw43RxIdleReason::Function2ReadFailed => {
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_F2_READ_FAILED
        }
        Cyw43RxIdleReason::SdpcmDecodeMiss => DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_SDPCM_DECODE_MISS,
        Cyw43RxIdleReason::FirstreadFailed => DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_FAILED,
        Cyw43RxIdleReason::FirstreadEmpty { .. } => {
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_EMPTY
        }
        Cyw43RxIdleReason::FirstreadSourceAssertedEmpty { .. } => {
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_SOURCE_ASSERTED_EMPTY
        }
        Cyw43RxIdleReason::FirstreadInvalidSdpcm(_) => {
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_INVALID_SDPCM
        }
        Cyw43RxIdleReason::FirstreadRemainderFailed => {
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_REMAINDER_FAILED
        }
        Cyw43RxIdleReason::FirstreadRemainderTooLarge(_) => {
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_REMAINDER_TOO_LARGE
        }
    }
}

fn cyw43_rx_idle_result(reason: Cyw43RxIdleReason) -> u32 {
    match reason {
        Cyw43RxIdleReason::InvalidRframeLength(frame_len)
        | Cyw43RxIdleReason::RxRequestTooLarge(frame_len)
        | Cyw43RxIdleReason::FirstreadRemainderTooLarge(frame_len) => bounded_u32(frame_len),
        Cyw43RxIdleReason::FirstreadEmpty { source, .. }
        | Cyw43RxIdleReason::FirstreadSourceAssertedEmpty { source, .. } => source.encode(),
        Cyw43RxIdleReason::FirstreadInvalidSdpcm(signature) => signature,
        _ => 0,
    }
}

fn cyw43_publish_control_rx_progress(sequence: u32, phase: u32) {
    publish_runtime_progress(sequence, phase, DRIVER_RUNTIME_CYW43_COMMAND_AUX);
}

const fn cyw43_control_exchange_attempt_uses_firstread(attempt: usize) -> bool {
    matches!(attempt, 1 | 4 | 16 | 64 | 256 | 1024 | 4096)
}

const fn cyw43_rx_idle_reason_rank(reason: Cyw43RxIdleReason) -> u8 {
    match reason {
        Cyw43RxIdleReason::NotReady => 0,
        Cyw43RxIdleReason::NoRframe => 1,
        Cyw43RxIdleReason::RframeCountReadFailed
        | Cyw43RxIdleReason::InvalidRframeLength(_)
        | Cyw43RxIdleReason::RxRequestTooLarge(_)
        | Cyw43RxIdleReason::Function2ReadFailed
        | Cyw43RxIdleReason::SdpcmDecodeMiss => 2,
        Cyw43RxIdleReason::FirstreadFailed
        | Cyw43RxIdleReason::FirstreadEmpty { .. }
        | Cyw43RxIdleReason::FirstreadSourceAssertedEmpty { .. }
        | Cyw43RxIdleReason::FirstreadInvalidSdpcm(_)
        | Cyw43RxIdleReason::FirstreadRemainderFailed
        | Cyw43RxIdleReason::FirstreadRemainderTooLarge(_) => 3,
    }
}

fn cyw43_remember_control_idle_reason(
    current: &mut Cyw43RxIdleReason,
    candidate: Cyw43RxIdleReason,
) {
    if cyw43_rx_idle_reason_rank(candidate) >= cyw43_rx_idle_reason_rank(*current) {
        *current = candidate;
    }
}

fn cyw43_drain_startup_status_frames(state: &mut Cyw43RuntimeState, sequence: u32) {
    if state.control_startup_status_drained {
        return;
    }
    state.control_startup_status_drained = true;
    for _ in 0..2 {
        match cyw43_runtime_poll_rx_detailed(
            state,
            CYW43_RX_FRAME_FLAG_MASK_CONTROL_EVENT,
            sequence,
            true,
        ) {
            Cyw43RxPollResult::Frame(_) => continue,
            Cyw43RxPollResult::Idle(_) => break,
        }
    }
}

fn cyw43_control_exchange(
    state: &mut Cyw43RuntimeState,
    frame: DriverFrameDescriptor,
    control_ext_header: bool,
    expected_cmd: u32,
    expected_id: u16,
    sequence: u32,
) -> Option<DriverFrameDescriptor> {
    cyw43_drain_startup_status_frames(state, sequence);
    cyw43_publish_control_rx_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_TX_BEGIN,
    );
    if cyw43_submit_sdpcm_frame(state, frame, false, control_ext_header) == 0 {
        return None;
    }
    cyw43_publish_control_rx_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_TX_DONE);
    let mut nonmatching_frames = 0u32;
    let mut last_idle_reason = Cyw43RxIdleReason::NoRframe;
    cyw43_publish_control_rx_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_CYW43_CONTROL_RX_POLL_BEGIN,
    );
    for attempt in 1..=CYW43_CONTROL_EXCHANGE_POLL_ATTEMPTS {
        let allow_firstread = cyw43_control_exchange_attempt_uses_firstread(attempt);
        let reply_frame = match cyw43_runtime_poll_rx_detailed(
            state,
            CYW43_RX_FRAME_FLAG_MASK_CONTROL_EVENT,
            sequence,
            allow_firstread,
        ) {
            Cyw43RxPollResult::Frame(frame) => frame,
            Cyw43RxPollResult::Idle(reason) => {
                cyw43_remember_control_idle_reason(&mut last_idle_reason, reason);
                core::hint::spin_loop();
                continue;
            }
        };
        if nonmatching_frames == 0 {
            last_idle_reason = Cyw43RxIdleReason::SdpcmDecodeMiss;
        };
        let Some(reply) = cyw43_control_reply_from_frame(reply_frame) else {
            nonmatching_frames = nonmatching_frames.saturating_add(1);
            core::hint::spin_loop();
            continue;
        };
        if reply.cmd != expected_cmd || reply.id != expected_id {
            nonmatching_frames = nonmatching_frames.saturating_add(1);
            core::hint::spin_loop();
            continue;
        }
        let response_len = match usize::try_from(reply.response_len) {
            Ok(len) => len,
            Err(_) => {
                cyw43_record_last_fault_with_result(
                    FAULT_CYW43_CONTROL_EXCHANGE,
                    reply.response_len,
                );
                return None;
            }
        };
        if response_len > reply.payload_available {
            cyw43_record_last_fault_with_result(FAULT_CYW43_CONTROL_EXCHANGE, reply.response_len);
            return None;
        }
        if reply.status != CYW43_CDC_STATUS_SUCCESS {
            cyw43_record_last_fault_with_result(FAULT_CYW43_CONTROL_EXCHANGE, reply.status);
            return None;
        }
        let response_len = match u16::try_from(response_len) {
            Ok(len) => len,
            Err(_) => {
                cyw43_record_last_fault_with_result(
                    FAULT_CYW43_CONTROL_EXCHANGE,
                    reply.response_len,
                );
                return None;
            }
        };
        return Some(DriverFrameDescriptor {
            offset: reply_frame
                .offset
                .saturating_add(CYW43_CDC_HEADER_BYTES as u32),
            len: response_len,
            flags: reply_frame.flags,
        });
    }
    cyw43_record_last_fault_with_result(
        FAULT_CYW43_CONTROL_EXCHANGE,
        cyw43_control_exchange_timeout_fault_result(last_idle_reason, nonmatching_frames),
    );
    None
}

const fn cyw43_control_exchange_timeout_result(reason: u32, value: u32) -> u32 {
    let bounded_value = if value > 0xffff { 0xffff } else { value };
    CYW43_CONTROL_EXCHANGE_TIMEOUT_RESULT_MAGIC | ((reason & 0xff) << 16) | bounded_value
}

fn cyw43_control_exchange_timeout_fault_result(
    last_idle_reason: Cyw43RxIdleReason,
    nonmatching_frames: u32,
) -> u32 {
    if nonmatching_frames != 0 {
        return cyw43_control_exchange_timeout_result(
            CYW43_CONTROL_EXCHANGE_TIMEOUT_REASON_NONMATCHING_REPLY,
            nonmatching_frames,
        );
    }
    match last_idle_reason {
        Cyw43RxIdleReason::NotReady => CYW43_CONTROL_EXCHANGE_TIMEOUT_RESULT_NOT_READY,
        Cyw43RxIdleReason::RframeCountReadFailed => {
            CYW43_CONTROL_EXCHANGE_TIMEOUT_RESULT_RFRAME_READ_FAILED
        }
        Cyw43RxIdleReason::NoRframe => CYW43_CONTROL_EXCHANGE_TIMEOUT_RESULT_NO_RFRAME,
        Cyw43RxIdleReason::InvalidRframeLength(frame_len) => cyw43_control_exchange_timeout_result(
            CYW43_CONTROL_EXCHANGE_TIMEOUT_REASON_INVALID_RFRAME_LEN,
            bounded_u32(frame_len),
        ),
        Cyw43RxIdleReason::RxRequestTooLarge(request_len) => cyw43_control_exchange_timeout_result(
            CYW43_CONTROL_EXCHANGE_TIMEOUT_REASON_RX_REQUEST_TOO_LARGE,
            bounded_u32(request_len),
        ),
        Cyw43RxIdleReason::Function2ReadFailed => {
            CYW43_CONTROL_EXCHANGE_TIMEOUT_RESULT_F2_READ_FAILED
        }
        Cyw43RxIdleReason::SdpcmDecodeMiss => {
            CYW43_CONTROL_EXCHANGE_TIMEOUT_RESULT_SDPCM_DECODE_MISS
        }
        Cyw43RxIdleReason::FirstreadFailed => cyw43_control_exchange_timeout_result(
            CYW43_CONTROL_EXCHANGE_TIMEOUT_REASON_FIRSTREAD_FAILED,
            0,
        ),
        Cyw43RxIdleReason::FirstreadEmpty { probe_len, .. } => {
            cyw43_control_exchange_timeout_result(
                CYW43_CONTROL_EXCHANGE_TIMEOUT_REASON_FIRSTREAD_EMPTY,
                bounded_u32(probe_len),
            )
        }
        Cyw43RxIdleReason::FirstreadSourceAssertedEmpty { probe_len, .. } => {
            cyw43_control_exchange_timeout_result(
                CYW43_CONTROL_EXCHANGE_TIMEOUT_REASON_FIRSTREAD_SOURCE_ASSERTED_EMPTY,
                bounded_u32(probe_len),
            )
        }
        Cyw43RxIdleReason::FirstreadInvalidSdpcm(signature) => {
            cyw43_control_exchange_timeout_result(
                CYW43_CONTROL_EXCHANGE_TIMEOUT_REASON_FIRSTREAD_INVALID_SDPCM,
                signature,
            )
        }
        Cyw43RxIdleReason::FirstreadRemainderFailed => cyw43_control_exchange_timeout_result(
            CYW43_CONTROL_EXCHANGE_TIMEOUT_REASON_FIRSTREAD_REMAINDER_FAILED,
            0,
        ),
        Cyw43RxIdleReason::FirstreadRemainderTooLarge(packet_len) => {
            cyw43_control_exchange_timeout_result(
                CYW43_CONTROL_EXCHANGE_TIMEOUT_REASON_FIRSTREAD_REMAINDER_TOO_LARGE,
                bounded_u32(packet_len),
            )
        }
    }
}

fn bounded_u32(value: usize) -> u32 {
    match u32::try_from(value) {
        Ok(value) => value,
        Err(_) => u32::MAX,
    }
}

fn cyw43_control_reply_from_frame(frame: DriverFrameDescriptor) -> Option<Cyw43ControlReply> {
    if frame.flags & DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_MASK
        != DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_CONTROL
    {
        return None;
    }
    let offset = frame.offset as usize;
    let len = usize::from(frame.len);
    if len < CYW43_CDC_HEADER_BYTES {
        return None;
    }
    Some(Cyw43ControlReply {
        cmd: read_ring_u32(offset),
        response_len: read_ring_u32(offset + 4),
        id: read_ring_u16(offset + 10),
        status: read_ring_u32(offset + 12),
        payload_available: len.saturating_sub(CYW43_CDC_HEADER_BYTES),
    })
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Cyw43RxSdpcmHeader {
    packet_len: usize,
    next_frame_len: usize,
    payload_start: usize,
    channel: u8,
    credit: u8,
    glom_descriptor: bool,
}

#[cfg(test)]
fn cyw43_runtime_decode_rx_frame(
    state: &mut Cyw43RuntimeState,
    base: usize,
    frame_len: usize,
) -> usize {
    cyw43_runtime_decode_rx_frame_for(state, base, frame_len, CYW43_RX_FRAME_FLAG_MASK_DATA)
        .map_or(0, |frame| usize::from(frame.len))
}

fn cyw43_runtime_decode_rx_frame_for(
    state: &mut Cyw43RuntimeState,
    base: usize,
    frame_len: usize,
    wanted_mask: u16,
) -> Option<DriverFrameDescriptor> {
    let Some(header) = cyw43_rx_sdpcm_header_at(base, frame_len) else {
        return None;
    };
    cyw43_update_sdpcm_credit(state, header);
    cyw43_remember_sdpcm_next_frame_len(state, header);
    match header.channel {
        CYW43_SDPCM_CHANNEL_DATA => cyw43_stage_or_queue_data_payload(
            state,
            base + header.payload_start,
            header.packet_len.saturating_sub(header.payload_start),
            header.credit,
            wanted_mask,
        ),
        CYW43_SDPCM_CHANNEL_GLOM if header.glom_descriptor => {
            cyw43_process_glom_descriptor(state, base, header);
            None
        }
        CYW43_SDPCM_CHANNEL_GLOM => cyw43_process_glom_superframe(state, base, header, wanted_mask),
        CYW43_SDPCM_CHANNEL_CONTROL | CYW43_SDPCM_CHANNEL_EVENT => {
            cyw43_stage_or_queue_plain_payload(
                state,
                base + header.payload_start,
                header.packet_len.saturating_sub(header.payload_start),
                cyw43_frame_flags_for_header(header),
                wanted_mask,
            )
        }
        _ => None,
    }
}

fn cyw43_rx_sdpcm_header_at(base: usize, frame_len: usize) -> Option<Cyw43RxSdpcmHeader> {
    if !(CYW43_SDPCM_HEADER_BYTES..=CYW43_RUNTIME_RX_BUFFER_BYTES).contains(&frame_len) {
        return None;
    }
    let header = cyw43_rx_sdpcm_header_prefix_at(base, frame_len, frame_len)?;
    if header.packet_len > frame_len {
        return None;
    }
    Some(header)
}

fn cyw43_rx_sdpcm_header_prefix_at(
    base: usize,
    prefix_len: usize,
    max_packet_len: usize,
) -> Option<Cyw43RxSdpcmHeader> {
    if prefix_len < CYW43_SDPCM_HEADER_BYTES {
        return None;
    }
    let len = u16::from_le_bytes([
        read_runtime_payload_byte(base),
        read_runtime_payload_byte(base + 1),
    ]) as usize;
    let len_inv = u16::from_le_bytes([
        read_runtime_payload_byte(base + 2),
        read_runtime_payload_byte(base + 3),
    ]);
    if len == 0 || len > max_packet_len || len_inv != !(len as u16) {
        return None;
    }
    let channel_byte = read_runtime_payload_byte(base + 5);
    let channel = channel_byte & 0x0f;
    let next_frame_len = cyw43_sdpcm_next_frame_len(read_runtime_payload_byte(base + 6));
    let payload_start = usize::from(read_runtime_payload_byte(base + 7));
    if payload_start < CYW43_SDPCM_HEADER_BYTES || payload_start > len {
        return None;
    }
    Some(Cyw43RxSdpcmHeader {
        packet_len: len,
        next_frame_len,
        payload_start,
        channel,
        credit: read_runtime_payload_byte(base + 9),
        glom_descriptor: channel_byte & 0x80 != 0,
    })
}

const fn cyw43_sdpcm_next_frame_len(next_frame_units: u8) -> usize {
    let frame_len = (next_frame_units as usize) * CYW43_SDPCM_NEXT_FRAME_LEN_UNIT_BYTES;
    if cyw43_sdpcm_frame_len_valid_or_empty(frame_len) {
        frame_len
    } else {
        0
    }
}

const fn cyw43_sdpcm_frame_len_valid_or_empty(frame_len: usize) -> bool {
    frame_len == 0 || cyw43_sdpcm_frame_len_valid(frame_len)
}

const fn cyw43_sdpcm_frame_len_valid(frame_len: usize) -> bool {
    frame_len >= CYW43_SDPCM_HEADER_BYTES && frame_len <= CYW43_RUNTIME_RX_BUFFER_BYTES
}

fn cyw43_remember_sdpcm_next_frame_len(state: &mut Cyw43RuntimeState, header: Cyw43RxSdpcmHeader) {
    state.sdpcm_next_frame_len = header.next_frame_len as u16;
}

fn cyw43_take_sdpcm_next_frame_len(state: &mut Cyw43RuntimeState) -> Option<usize> {
    let frame_len = usize::from(state.sdpcm_next_frame_len);
    state.sdpcm_next_frame_len = 0;
    if cyw43_sdpcm_frame_len_valid(frame_len) {
        Some(frame_len)
    } else {
        None
    }
}

fn cyw43_sdpcm_firstread_prefix_empty(base: usize) -> bool {
    for index in 0..CYW43_SDPCM_HEADER_BYTES {
        if read_runtime_payload_byte(base + index) != 0 {
            return false;
        }
    }
    true
}

fn cyw43_sdpcm_firstread_prefix_signature(base: usize) -> u32 {
    u32::from(read_runtime_payload_byte(base))
        | (u32::from(read_runtime_payload_byte(base + 1)) << 8)
        | (u32::from(read_runtime_payload_byte(base + 2)) << 16)
        | (u32::from(read_runtime_payload_byte(base + 3)) << 24)
}

fn cyw43_update_sdpcm_credit(state: &mut Cyw43RuntimeState, header: Cyw43RxSdpcmHeader) {
    if header.channel >= CYW43_SDPCM_CHANNEL_GLOM {
        return;
    }
    state.sdpcm_credit_observations = state.sdpcm_credit_observations.wrapping_add(1);
    let mut credit = header.credit;
    if credit.wrapping_sub(state.sdpcm_seq) > 0x40 {
        credit = state.sdpcm_seq.wrapping_add(2);
    }
    state.sdpcm_seq_max = credit;
}

fn cyw43_process_glom_descriptor(
    state: &mut Cyw43RuntimeState,
    base: usize,
    header: Cyw43RxSdpcmHeader,
) {
    let payload_offset = base + header.payload_start;
    let payload_len = header.packet_len.saturating_sub(header.payload_start);
    state.glom_subframe_count = 0;
    if payload_len == 0 || !payload_len.is_multiple_of(2) {
        return;
    }
    let mut total_len = 0usize;
    let mut index = 0usize;
    while index < payload_len / 2 && index < CYW43_RX_GLOM_SUBFRAME_CAP {
        let subframe_len = u16::from_le_bytes([
            read_runtime_payload_byte(payload_offset + index * 2),
            read_runtime_payload_byte(payload_offset + index * 2 + 1),
        ]);
        if !cyw43_glom_subframe_len_valid(subframe_len, index) {
            state.glom_subframe_count = 0;
            return;
        }
        total_len = match total_len.checked_add(usize::from(subframe_len)) {
            Some(total) if total <= CYW43_RUNTIME_RX_BUFFER_BYTES => total,
            _ => {
                state.glom_subframe_count = 0;
                return;
            }
        };
        state.glom_subframe_lens[index] = subframe_len;
        index += 1;
    }
    if index != payload_len / 2 {
        state.glom_subframe_count = 0;
        return;
    }
    state.glom_subframe_count = index as u8;
}

fn cyw43_process_glom_superframe(
    state: &mut Cyw43RuntimeState,
    base: usize,
    header: Cyw43RxSdpcmHeader,
    wanted_mask: u16,
) -> Option<DriverFrameDescriptor> {
    let count = usize::from(state.glom_subframe_count);
    if count == 0 {
        return None;
    }
    state.glom_subframe_count = 0;
    let mut cursor = base + header.payload_start;
    let packet_end = base + header.packet_len;
    let mut first_frame = None;
    for index in 0..count {
        let descriptor_len = usize::from(state.glom_subframe_lens[index]);
        let Some(subframe_len) =
            cyw43_glom_descriptor_subframe_len(index, descriptor_len, header.payload_start)
        else {
            break;
        };
        if subframe_len < CYW43_SDPCM_HEADER_BYTES {
            break;
        }
        let Some(mut end) = cursor.checked_add(subframe_len) else {
            break;
        };
        let truncated = if end > packet_end {
            if packet_end.saturating_sub(cursor) < CYW43_SDPCM_HEADER_BYTES {
                break;
            }
            end = packet_end;
            true
        } else {
            false
        };
        if let Some(frame) = cyw43_decode_data_subframe(
            state,
            cursor,
            end - cursor,
            first_frame.is_some(),
            wanted_mask,
        ) {
            if first_frame.is_none() {
                first_frame = Some(frame);
            }
        }
        cursor = end;
        if truncated {
            break;
        }
    }
    first_frame
}

fn cyw43_decode_data_subframe(
    state: &mut Cyw43RuntimeState,
    base: usize,
    frame_len: usize,
    queue: bool,
    wanted_mask: u16,
) -> Option<DriverFrameDescriptor> {
    let header = cyw43_rx_sdpcm_header_at(base, frame_len)?;
    if header.channel != CYW43_SDPCM_CHANNEL_DATA {
        return None;
    }
    let payload_offset = base.checked_add(header.payload_start)?;
    let payload_len = header.packet_len.checked_sub(header.payload_start)?;
    let (packet_offset, packet_len) = cyw43_bdc_payload_bounds(payload_offset, payload_len)?;
    if queue {
        cyw43_rx_queue_push_from_runtime(
            state,
            packet_offset,
            packet_len,
            cyw43_frame_flags_for_header(header),
        );
        None
    } else {
        cyw43_stage_or_queue_plain_payload(
            state,
            packet_offset,
            packet_len,
            cyw43_frame_flags_for_header(header),
            wanted_mask,
        )
    }
}

fn cyw43_stage_or_queue_data_payload(
    state: &mut Cyw43RuntimeState,
    payload_offset: usize,
    payload_len: usize,
    credit: u8,
    wanted_mask: u16,
) -> Option<DriverFrameDescriptor> {
    let Some((packet_offset, packet_len)) = cyw43_bdc_payload_bounds(payload_offset, payload_len)
    else {
        return None;
    };
    cyw43_stage_or_queue_plain_payload(
        state,
        packet_offset,
        packet_len,
        cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, credit),
        wanted_mask,
    )
}

fn cyw43_stage_or_queue_plain_payload(
    state: &mut Cyw43RuntimeState,
    packet_offset: usize,
    packet_len: usize,
    flags: u16,
    wanted_mask: u16,
) -> Option<DriverFrameDescriptor> {
    if cyw43_wanted_mask_allows_flags(wanted_mask, flags) {
        if cyw43_copy_runtime_payload_to_front(packet_offset, packet_len) {
            Some(DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: packet_len as u16,
                flags,
            })
        } else {
            None
        }
    } else {
        cyw43_rx_queue_push_from_runtime(state, packet_offset, packet_len, flags);
        None
    }
}

const fn cyw43_wanted_mask_allows_flags(wanted_mask: u16, flags: u16) -> bool {
    let channel = flags & DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_MASK;
    wanted_mask & (1u16 << channel) != 0
}

const fn cyw43_frame_flag_for_channel(channel: u8) -> u16 {
    match channel {
        CYW43_SDPCM_CHANNEL_CONTROL => DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_CONTROL,
        CYW43_SDPCM_CHANNEL_EVENT => DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_EVENT,
        CYW43_SDPCM_CHANNEL_DATA => DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_DATA,
        _ => DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_CONTROL,
    }
}

const fn cyw43_frame_flags(channel: u8, credit: u8) -> u16 {
    cyw43_frame_flag_for_channel(channel)
        | ((credit as u16) << DRIVER_RUNTIME_CYW43_FRAME_FLAG_CREDIT_SHIFT)
}

const fn cyw43_frame_flags_for_header(header: Cyw43RxSdpcmHeader) -> u16 {
    cyw43_frame_flags(header.channel, header.credit)
}

fn cyw43_bdc_payload_bounds(payload_offset: usize, payload_len: usize) -> Option<(usize, usize)> {
    if payload_len < CYW43_BDC_HEADER_BYTES {
        return None;
    }
    if read_runtime_payload_byte(payload_offset) >> CYW43_BDC_VERSION_SHIFT != CYW43_BDC_VERSION {
        return None;
    }
    let data_offset_words = usize::from(read_runtime_payload_byte(payload_offset + 3));
    let packet_offset = payload_offset
        .checked_add(CYW43_BDC_HEADER_BYTES)?
        .checked_add(data_offset_words.checked_mul(4)?)?;
    let payload_end = payload_offset.checked_add(payload_len)?;
    if packet_offset > payload_end {
        return None;
    }
    Some((packet_offset, payload_end - packet_offset))
}

fn cyw43_copy_runtime_payload_to_front(packet_offset: usize, packet_len: usize) -> bool {
    if packet_len > MAX_DRIVER_TASK_FRAME_BYTES {
        return false;
    }
    for index in 0..packet_len {
        write_ring_byte(
            DRIVER_TASK_RING_FRAME_OFFSET + index,
            read_runtime_payload_byte(packet_offset + index),
        );
    }
    true
}

fn cyw43_rx_queue_push_from_runtime(
    state: &mut Cyw43RuntimeState,
    packet_offset: usize,
    packet_len: usize,
    flags: u16,
) -> bool {
    if packet_len == 0
        || packet_len > MAX_DRIVER_TASK_FRAME_BYTES
        || !cyw43_rx_queue_flags_valid(flags)
        || usize::from(state.rx_queue_count) >= CYW43_RX_QUEUE_CAP
    {
        return false;
    }
    let slot = cyw43_rx_queue_slot_at(state, usize::from(state.rx_queue_count));
    for index in 0..packet_len {
        state.rx_queue_frames[slot][index] = read_runtime_payload_byte(packet_offset + index);
    }
    state.rx_queue_lens[slot] = packet_len as u16;
    state.rx_queue_flags[slot] = flags;
    state.rx_queue_count = state.rx_queue_count.saturating_add(1);
    true
}

fn cyw43_rx_queue_pop_matching(
    state: &mut Cyw43RuntimeState,
    wanted_mask: u16,
) -> Option<DriverFrameDescriptor> {
    if state.rx_queue_count == 0 {
        return None;
    }
    let Some(logical_index) = cyw43_rx_queue_find_matching_index(state, wanted_mask) else {
        return None;
    };
    let slot = cyw43_rx_queue_slot_at(state, logical_index);
    let payload_len = usize::from(state.rx_queue_lens[slot]);
    let flags = state.rx_queue_flags[slot];
    if payload_len == 0
        || payload_len > MAX_DRIVER_TASK_FRAME_BYTES
        || !cyw43_rx_queue_flags_valid(flags)
    {
        cyw43_rx_queue_remove_index(state, logical_index);
        return None;
    }
    for index in 0..payload_len {
        write_ring_byte(
            DRIVER_TASK_RING_FRAME_OFFSET + index,
            state.rx_queue_frames[slot][index],
        );
    }
    cyw43_rx_queue_remove_index(state, logical_index);
    Some(DriverFrameDescriptor {
        offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
        len: payload_len as u16,
        flags,
    })
}

const fn cyw43_rx_queue_initial_slots() -> [u8; CYW43_RX_QUEUE_CAP] {
    let mut slots = [0u8; CYW43_RX_QUEUE_CAP];
    let mut index = 0usize;
    while index < CYW43_RX_QUEUE_CAP {
        slots[index] = index as u8;
        index += 1;
    }
    slots
}

fn cyw43_rx_queue_slot_at(state: &Cyw43RuntimeState, logical_index: usize) -> usize {
    let slot_index = (usize::from(state.rx_queue_head) + logical_index) % CYW43_RX_QUEUE_CAP;
    usize::from(state.rx_queue_slots[slot_index])
}

fn cyw43_rx_queue_find_matching_index(
    state: &Cyw43RuntimeState,
    wanted_mask: u16,
) -> Option<usize> {
    let mut index = 0u8;
    while index < state.rx_queue_count {
        let slot = cyw43_rx_queue_slot_at(state, usize::from(index));
        if cyw43_wanted_mask_allows_flags(wanted_mask, state.rx_queue_flags[slot]) {
            return Some(usize::from(index));
        }
        index = index.saturating_add(1);
    }
    None
}

fn cyw43_rx_queue_remove_index(state: &mut Cyw43RuntimeState, logical_index: usize) {
    if state.rx_queue_count == 0 || logical_index >= usize::from(state.rx_queue_count) {
        return;
    }
    let remove_pos = (usize::from(state.rx_queue_head) + logical_index) % CYW43_RX_QUEUE_CAP;
    let freed_slot = usize::from(state.rx_queue_slots[remove_pos]);
    let last_logical_index = usize::from(state.rx_queue_count) - 1;
    for index in logical_index..last_logical_index {
        let current = (usize::from(state.rx_queue_head) + index) % CYW43_RX_QUEUE_CAP;
        let next = (current + 1) % CYW43_RX_QUEUE_CAP;
        state.rx_queue_slots[current] = state.rx_queue_slots[next];
    }
    let tail = (usize::from(state.rx_queue_head) + last_logical_index) % CYW43_RX_QUEUE_CAP;
    state.rx_queue_slots[tail] = freed_slot as u8;
    state.rx_queue_lens[freed_slot] = 0;
    state.rx_queue_flags[freed_slot] = 0;
    state.rx_queue_count = state.rx_queue_count.saturating_sub(1);
    if state.rx_queue_count == 0 {
        state.rx_queue_head = 0;
        state.rx_queue_slots = cyw43_rx_queue_initial_slots();
    }
}

const fn cyw43_rx_queue_flags_valid(flags: u16) -> bool {
    matches!(
        flags & DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_MASK,
        DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_CONTROL
            | DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_EVENT
            | DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_DATA
    ) && flags
        & !(DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_MASK
            | DRIVER_RUNTIME_CYW43_FRAME_FLAG_CREDIT_MASK)
        == 0
}

const fn cyw43_glom_subframe_len_valid(subframe_len: u16, index: usize) -> bool {
    let min_len = if index == 0 {
        CYW43_SDPCM_HEADER_BYTES * 2
    } else {
        CYW43_SDPCM_HEADER_BYTES
    };
    subframe_len as usize >= min_len
}

fn cyw43_glom_descriptor_subframe_len(
    index: usize,
    descriptor_len: usize,
    payload_start: usize,
) -> Option<usize> {
    if index == 0 {
        descriptor_len.checked_sub(payload_start)
    } else {
        Some(descriptor_len)
    }
}

fn write_sdpcm_header(offset: usize, total_len: usize, data_offset: usize, seq: u8, channel: u8) {
    let total = total_len as u16;
    write_ring_byte(offset, (total & 0xff) as u8);
    write_ring_byte(offset + 1, (total >> 8) as u8);
    let inv = !total;
    write_ring_byte(offset + 2, (inv & 0xff) as u8);
    write_ring_byte(offset + 3, (inv >> 8) as u8);
    write_ring_byte(offset + 4, seq);
    write_ring_byte(offset + 5, channel & 0x0f);
    write_ring_byte(offset + 6, 0);
    write_ring_byte(offset + 7, data_offset as u8);
    for index in 8..CYW43_SDPCM_HEADER_BYTES {
        write_ring_byte(offset + index, 0);
    }
}

fn cyw43_write_sdpcm_control_tx_header(
    offset: usize,
    request_len: usize,
    total_len: usize,
    short_header_payload_start: usize,
    header_len: usize,
    seq: u8,
    control_ext_header: bool,
) {
    if control_ext_header {
        let packet_len = request_len as u16;
        write_ring_byte(offset, (packet_len & 0xff) as u8);
        write_ring_byte(offset + 1, (packet_len >> 8) as u8);
        let inv = !packet_len;
        write_ring_byte(offset + 2, (inv & 0xff) as u8);
        write_ring_byte(offset + 3, (inv >> 8) as u8);
        write_ring_u32(
            offset + CYW43_SDPCM_HWHDR_BYTES,
            (total_len.saturating_sub(CYW43_SDPCM_HWHDR_BYTES) as u32) | CYW43_SDPCM_LAST_FRAME,
        );
        write_ring_u32(
            offset + CYW43_SDPCM_HWHDR_BYTES + 4,
            (request_len.saturating_sub(total_len) as u32) << 16,
        );
        write_ring_u32(
            offset + CYW43_SDPCM_HEADER_BYTES,
            u32::from(seq)
                | (u32::from(CYW43_SDPCM_CHANNEL_CONTROL) << 8)
                | ((header_len as u32) << 24),
        );
        write_ring_u32(offset + CYW43_SDPCM_HEADER_BYTES + 4, 0);
    } else {
        write_sdpcm_header(
            offset,
            total_len,
            short_header_payload_start,
            seq,
            CYW43_SDPCM_CHANNEL_CONTROL,
        );
    }
}

const fn cyw43_control_tx_request_len(unpadded_len: usize) -> usize {
    if unpadded_len > CYW43_SDPCM_CONTROL_TX_BLOCK_BYTES {
        let remainder = unpadded_len % CYW43_SDPCM_CONTROL_TX_BLOCK_BYTES;
        if remainder == 0 {
            unpadded_len
        } else {
            unpadded_len + (CYW43_SDPCM_CONTROL_TX_BLOCK_BYTES - remainder)
        }
    } else {
        align4(unpadded_len)
    }
}

const fn cyw43_control_rx_request_len(unpadded_len: usize) -> usize {
    let aligned = (unpadded_len + 3) & !3;
    if aligned <= SDIO_CMD53_BYTE_MODE_MAX {
        aligned
    } else {
        let remainder = aligned % CYW43_FUNCTION2_BLOCK_BYTES;
        if remainder == 0 {
            aligned
        } else {
            aligned + (CYW43_FUNCTION2_BLOCK_BYTES - remainder)
        }
    }
}

const fn cyw43_control_rx_remainder_request_len(
    prefix_len: usize,
    packet_len: usize,
) -> Option<usize> {
    if packet_len <= prefix_len {
        return None;
    }
    let remainder_len = packet_len - prefix_len;
    let request_len = cyw43_control_rx_request_len(remainder_len);
    if request_len <= CYW43_CONTROL_RX_BULK_READ_BYTES {
        Some(request_len)
    } else {
        None
    }
}

fn cyw43_write_sdpcm_data_tx_header(offset: usize, total_len: usize, seq: u8) {
    let total = total_len as u16;
    write_ring_byte(offset, (total & 0xff) as u8);
    write_ring_byte(offset + 1, (total >> 8) as u8);
    let inv = !total;
    write_ring_byte(offset + 2, (inv & 0xff) as u8);
    write_ring_byte(offset + 3, (inv >> 8) as u8);
    write_ring_u32(
        offset + CYW43_SDPCM_HWHDR_BYTES,
        (total_len.saturating_sub(CYW43_SDPCM_HWHDR_BYTES) as u32) | CYW43_SDPCM_LAST_FRAME,
    );
    write_ring_u32(offset + CYW43_SDPCM_HWHDR_BYTES + 4, 0);
    write_ring_u32(
        offset + CYW43_SDPCM_DATA_TX_SW_HEADER_OFFSET,
        u32::from(seq)
            | (u32::from(CYW43_SDPCM_CHANNEL_DATA) << 8)
            | ((CYW43_SDPCM_DATA_TX_BDC_OFFSET as u32) << 24),
    );
    write_ring_u32(offset + CYW43_SDPCM_DATA_TX_SW_HEADER_OFFSET + 4, 0);
    for index in CYW43_SDPCM_DATA_TX_HEADER_BYTES..CYW43_SDPCM_DATA_TX_BDC_OFFSET {
        write_ring_byte(offset + index, 0);
    }
}

fn cyw43_bdc_priority_for_ring_packet(offset: usize, len: usize) -> u8 {
    if len < CYW43_ETH_HEADER_BYTES {
        return 0;
    }
    let ethertype =
        (u16::from(read_ring_byte(offset + 12)) << 8) | u16::from(read_ring_byte(offset + 13));
    if ethertype == CYW43_ETH_P_EAPOL {
        CYW43_HOST_EAPOL_BDC_PRIORITY
    } else {
        0
    }
}

fn copy_ring_range(src: usize, dst: usize, len: usize) {
    if len == 0 || src == dst {
        return;
    }
    if dst > src && dst < src.saturating_add(len) {
        let mut index = len;
        while index != 0 {
            index -= 1;
            let byte = read_ring_byte(src + index);
            write_ring_byte(dst + index, byte);
        }
    } else {
        for index in 0..len {
            let byte = read_ring_byte(src + index);
            write_ring_byte(dst + index, byte);
        }
    }
}

const fn align4(value: usize) -> usize {
    (value + 3) & !3
}

fn align_to(value: usize, alignment: usize) -> usize {
    value.div_ceil(alignment) * alignment
}

#[inline]
const fn has_sdpcm_credit(sdpcm_seq: u8, sdpcm_seq_max: u8) -> bool {
    sdpcm_seq != sdpcm_seq_max && (sdpcm_seq_max.wrapping_sub(sdpcm_seq) & 0x80) == 0
}

fn genet_runtime_submit_tx(state: &mut GenetRuntimeState, frame: DriverFrameDescriptor) -> usize {
    if !state.initialized || frame.len == 0 || frame.len as usize > GENET_MAX_FRAME_LEN {
        state.tx_drops = state.tx_drops.saturating_add(1);
        return 0;
    }
    genet_runtime_poll_tx_completions(state);
    let in_flight = ring_distance(state.tx_prod_index, state.tx_cons_index) as usize;
    if in_flight >= GENET_HW_TOTAL_DESCS {
        state.tx_drops = state.tx_drops.saturating_add(1);
        return 0;
    }
    let descriptor = RUNTIME_DESCRIPTOR.load();
    let Some(dma_range) = runtime_resource_range(
        &descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    ) else {
        return 0;
    };
    let slot = ring_slot(state.tx_prod_index, GENET_HW_TOTAL_DESCS);
    let dma_slot = GENET_HW_TOTAL_DESCS + slot;
    let Some(dma_vaddr) =
        (dma_range.vaddr as usize).checked_add(dma_slot * DRIVER_TASK_RING_PAGE_BYTES)
    else {
        return 0;
    };
    let Some(dma_bus_addr) = runtime_resource_bus_addr_at(
        &descriptor,
        dma_range,
        dma_slot.saturating_mul(DRIVER_TASK_RING_PAGE_BYTES),
    ) else {
        return 0;
    };
    for index in 0..frame.len as usize {
        write_dma_byte(
            dma_vaddr + index,
            read_ring_byte(frame.offset as usize + index),
        );
    }
    dma_store_barrier();
    genet_write_tx_desc(slot, dma_bus_addr, genet_tx_len_status(frame.len as usize));
    dma_store_barrier();
    state.tx_prod_index = state.tx_prod_index.wrapping_add(1);
    genet_write32(GENET_TDMA_PROD_INDEX, state.tx_prod_index as u32);
    state.tx_packets = state.tx_packets.saturating_add(1);
    frame.len as usize
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum GenetRxPoll {
    Idle,
    Frame(usize),
    BudgetExhausted(u16),
}

fn genet_rx_budget_limit(budget: DriverTaskBudgetGrant) -> Result<usize, u16> {
    if budget.max_ops == 0 {
        return Err(BUDGET_EXHAUSTED_OPS);
    }
    if budget.max_frames == 0 {
        return Err(BUDGET_EXHAUSTED_FRAMES);
    }
    if budget.max_bytes == 0 {
        return Err(BUDGET_EXHAUSTED_BYTES);
    }
    Ok(GENET_RX_DRAIN_BUDGET
        .min(budget.max_ops as usize)
        .min(budget.max_frames as usize))
}

fn genet_tx_budget_allows_frame(budget: DriverTaskBudgetGrant, frame_len: u16) -> Result<(), u16> {
    if budget.max_ops == 0 {
        return Err(BUDGET_EXHAUSTED_OPS);
    }
    if budget.max_frames == 0 {
        return Err(BUDGET_EXHAUSTED_FRAMES);
    }
    if u32::from(frame_len) > budget.max_bytes {
        return Err(BUDGET_EXHAUSTED_BYTES);
    }
    Ok(())
}

fn genet_runtime_poll_rx(
    state: &mut GenetRuntimeState,
    budget: DriverTaskBudgetGrant,
) -> GenetRxPoll {
    if !state.initialized {
        return GenetRxPoll::Idle;
    }
    let drain_budget = match genet_rx_budget_limit(budget) {
        Ok(limit) => limit,
        Err(detail) => return GenetRxPoll::BudgetExhausted(detail),
    };
    if drain_budget == 0 {
        return GenetRxPoll::BudgetExhausted(BUDGET_EXHAUSTED_FRAMES);
    }
    if let Some(payload_len) = genet_rx_queue_peek_len(state) {
        if payload_len > budget.max_bytes as usize {
            return GenetRxPoll::BudgetExhausted(BUDGET_EXHAUSTED_BYTES);
        }
        let Some(payload_len) = genet_rx_queue_pop_to_ring(state) else {
            return GenetRxPoll::Idle;
        };
        state.rx_packets = state.rx_packets.saturating_add(1);
        return GenetRxPoll::Frame(payload_len);
    }
    genet_runtime_poll_tx_completions(state);
    let descriptor = RUNTIME_DESCRIPTOR.load();
    let Some(dma_range) = runtime_resource_range(
        &descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    ) else {
        return GenetRxPoll::Idle;
    };
    let mut first_payload_len = 0usize;
    for _ in 0..drain_budget {
        let prod = genet_read32(GENET_RDMA_PROD_INDEX) as u16;
        if prod == state.rx_cons_index {
            break;
        }
        let slot = ring_slot(state.rx_cons_index, GENET_HW_TOTAL_DESCS);
        let desc = genet_read_rx_desc(slot);
        if desc.0 & GENET_DMA_OWN != 0 {
            break;
        }
        let length = genet_decode_rx_len(desc.0);
        let payload_len = length
            .saturating_sub(GENET_RX_BUF_OFFSET)
            .min(MAX_DRIVER_TASK_FRAME_BYTES);
        let dma_vaddr = dma_range.vaddr as usize + slot * DRIVER_TASK_RING_PAGE_BYTES;
        dma_load_barrier();
        if payload_len != 0 {
            if payload_len > budget.max_bytes as usize {
                if first_payload_len == 0 {
                    return GenetRxPoll::BudgetExhausted(BUDGET_EXHAUSTED_BYTES);
                }
                break;
            }
            if first_payload_len == 0 {
                genet_copy_dma_frame_to_ring(dma_vaddr, payload_len);
                first_payload_len = payload_len;
            } else if !genet_rx_queue_push_from_dma(state, dma_vaddr, payload_len) {
                break;
            }
        }
        genet_rearm_rx_slot(&descriptor, dma_range, slot);
        state.rx_cons_index = state.rx_cons_index.wrapping_add(1);
        genet_write32(GENET_RDMA_CONS_INDEX, state.rx_cons_index as u32);
    }
    if first_payload_len != 0 {
        state.rx_packets = state.rx_packets.saturating_add(1);
        GenetRxPoll::Frame(first_payload_len)
    } else {
        GenetRxPoll::Idle
    }
}

fn genet_copy_dma_frame_to_ring(dma_vaddr: usize, payload_len: usize) {
    for index in 0..payload_len {
        let byte = read_dma_byte(dma_vaddr + GENET_RX_BUF_OFFSET + index);
        write_ring_byte(DRIVER_TASK_RING_FRAME_OFFSET + index, byte);
    }
}

fn genet_rx_queue_push_from_dma(
    state: &mut GenetRuntimeState,
    dma_vaddr: usize,
    payload_len: usize,
) -> bool {
    if payload_len == 0
        || payload_len > GENET_MAX_FRAME_LEN
        || usize::from(state.rx_queue_count) >= GENET_RX_QUEUE_CAP
    {
        return false;
    }
    let slot =
        (usize::from(state.rx_queue_head) + usize::from(state.rx_queue_count)) % GENET_RX_QUEUE_CAP;
    for index in 0..payload_len {
        state.rx_queue_frames[slot][index] = read_dma_byte(dma_vaddr + GENET_RX_BUF_OFFSET + index);
    }
    state.rx_queue_lens[slot] = payload_len as u16;
    state.rx_queue_count = state.rx_queue_count.saturating_add(1);
    true
}

#[cfg(test)]
fn genet_rx_queue_push_for_test(state: &mut GenetRuntimeState, payload: &[u8]) -> bool {
    if payload.is_empty()
        || payload.len() > GENET_MAX_FRAME_LEN
        || usize::from(state.rx_queue_count) >= GENET_RX_QUEUE_CAP
    {
        return false;
    }
    let slot =
        (usize::from(state.rx_queue_head) + usize::from(state.rx_queue_count)) % GENET_RX_QUEUE_CAP;
    state.rx_queue_frames[slot][..payload.len()].copy_from_slice(payload);
    state.rx_queue_lens[slot] = payload.len() as u16;
    state.rx_queue_count = state.rx_queue_count.saturating_add(1);
    true
}

fn genet_rx_queue_pop_to_ring(state: &mut GenetRuntimeState) -> Option<usize> {
    if state.rx_queue_count == 0 {
        return None;
    }
    let slot = usize::from(state.rx_queue_head);
    let payload_len = usize::from(state.rx_queue_lens[slot]);
    if payload_len == 0 || payload_len > GENET_MAX_FRAME_LEN {
        genet_rx_queue_drop_head(state);
        return None;
    }
    for index in 0..payload_len {
        write_ring_byte(
            DRIVER_TASK_RING_FRAME_OFFSET + index,
            state.rx_queue_frames[slot][index],
        );
    }
    genet_rx_queue_drop_head(state);
    Some(payload_len)
}

fn genet_rx_queue_peek_len(state: &GenetRuntimeState) -> Option<usize> {
    if state.rx_queue_count == 0 {
        return None;
    }
    let slot = usize::from(state.rx_queue_head);
    let payload_len = usize::from(state.rx_queue_lens[slot]);
    if payload_len == 0 || payload_len > GENET_MAX_FRAME_LEN {
        return None;
    }
    Some(payload_len)
}

fn genet_rx_queue_drop_head(state: &mut GenetRuntimeState) {
    if state.rx_queue_count == 0 {
        return;
    }
    let slot = usize::from(state.rx_queue_head);
    state.rx_queue_lens[slot] = 0;
    state.rx_queue_head = ((slot + 1) % GENET_RX_QUEUE_CAP) as u8;
    state.rx_queue_count = state.rx_queue_count.saturating_sub(1);
    if state.rx_queue_count == 0 {
        state.rx_queue_head = 0;
    }
}

fn genet_runtime_poll_tx_completions(state: &mut GenetRuntimeState) {
    let new_cons = genet_read32(GENET_TDMA_CONS_INDEX) as u16;
    let completed = ring_distance(new_cons, state.tx_cons_index) as usize;
    if completed != 0 {
        let reclaim = completed.min(GENET_TX_COMPLETION_RECLAIM_BUDGET);
        state.tx_cons_index = state.tx_cons_index.wrapping_add(reclaim as u16);
    }
}

fn genet_runtime_init_hw(
    descriptor: &DriverRuntimeInitDescriptor,
    state: &mut GenetRuntimeState,
) -> bool {
    let Some(dma_range) = runtime_resource_range(
        descriptor,
        DRIVER_RUNTIME_RESOURCE_KIND_DMA,
        DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
    ) else {
        return false;
    };
    if dma_range.page_count < GENET_REQUIRED_DMA_PAGES {
        return false;
    }
    genet_hw_init_registers();
    genet_write_mac(GENET_DRIVER_TASK_MAC);
    if let Some((phy_addr, link_ready, speed)) = genet_configure_phy_link() {
        state.phy_addr = phy_addr;
        state.link_ready = link_ready;
        state.link_speed = speed;
    } else {
        state.link_speed = genet_current_umac_speed();
    }
    state.tx_cons_index = genet_read32(GENET_TDMA_CONS_INDEX) as u16;
    state.tx_prod_index = state.tx_cons_index;
    state.rx_cons_index = genet_read32(GENET_RDMA_PROD_INDEX) as u16;
    for slot in 0..GENET_HW_TOTAL_DESCS {
        genet_rearm_rx_slot(descriptor, dma_range, slot);
        genet_write_tx_desc(slot, 0, 0);
    }
    genet_enable_dma();
    let cmd = genet_read32(GENET_UMAC_CMD);
    genet_write32(GENET_UMAC_CMD, cmd | GENET_CMD_TX_EN | GENET_CMD_RX_EN);
    true
}

fn genet_hw_init_registers() {
    let mut flush = genet_read32(GENET_SYS_RBUF_FLUSH_CTRL);
    flush |= 1 << 1;
    genet_write32(GENET_SYS_RBUF_FLUSH_CTRL, flush);
    runtime_spin(10_000);
    genet_write32(GENET_SYS_RBUF_FLUSH_CTRL, flush & !(1 << 1));
    runtime_spin(10_000);
    genet_write32(GENET_UMAC_CMD, 0);
    genet_write32(GENET_UMAC_CMD, GENET_CMD_SW_RESET | GENET_CMD_LCL_LOOP_EN);
    runtime_spin(2_000);
    genet_write32(GENET_UMAC_CMD, 0);
    genet_write32(
        GENET_UMAC_MIB_CTRL,
        GENET_MIB_RESET_RX | GENET_MIB_RESET_TX | GENET_MIB_RESET_RUNT,
    );
    genet_write32(GENET_UMAC_MIB_CTRL, 0);
    genet_write32(GENET_UMAC_MAX_FRAME_LEN, GENET_RX_BUF_LENGTH as u32);
    genet_write32(
        GENET_RBUF_CTRL,
        genet_read32(GENET_RBUF_CTRL) | GENET_RBUF_ALIGN_2B,
    );
    genet_write32(GENET_RBUF_TBUF_SIZE_CTRL, 1);
    genet_write32(GENET_SYS_PORT_CTRL, GENET_PORT_MODE_EXT_GPHY);
    let mut oob = genet_read32(GENET_EXT_RGMII_OOB_CTRL);
    oob &= !GENET_OOB_DISABLE;
    oob |= GENET_RGMII_LINK | GENET_RGMII_MODE_EN | GENET_ID_MODE_DIS;
    genet_write32(GENET_EXT_RGMII_OOB_CTRL, oob);
    let mut cmd = genet_read32(GENET_UMAC_CMD);
    cmd &= !(GENET_CMD_SPEED_MASK << GENET_CMD_SPEED_SHIFT);
    cmd |= 2 << GENET_CMD_SPEED_SHIFT;
    genet_write32(GENET_UMAC_CMD, cmd);
    genet_disable_dma();
    genet_init_rx_ring();
    genet_init_tx_ring();
}

fn genet_configure_phy_link() -> Option<(u8, bool, u32)> {
    genet_write32(GENET_SYS_PORT_CTRL, GENET_PORT_MODE_EXT_GPHY);
    let mut oob = genet_read32(GENET_EXT_RGMII_OOB_CTRL);
    oob &= !GENET_OOB_DISABLE;
    oob |= GENET_RGMII_LINK | GENET_RGMII_MODE_EN | GENET_ID_MODE_DIS;
    genet_write32(GENET_EXT_RGMII_OOB_CTRL, oob);

    let phy_addr = genet_discover_phy_addr()?;
    if let Some(bmcr) = genet_mdio_read(phy_addr, GENET_MII_BMCR) {
        if (bmcr & GENET_MII_BMCR_ANENABLE) == 0 {
            let next = (bmcr | GENET_MII_BMCR_ANENABLE | GENET_MII_BMCR_ANRESTART)
                & !(GENET_MII_BMCR_SPEED100 | GENET_MII_BMCR_SPEED1000);
            let _ = genet_mdio_write(phy_addr, GENET_MII_BMCR, next);
        }
    }

    let mut link_ready = false;
    let mut resolved_speed = None;
    for _ in 0..GENET_PHY_LINK_POLL_TRIES {
        let _ = genet_mdio_read(phy_addr, GENET_MII_BMSR);
        if let Some(status) = genet_mdio_read(phy_addr, GENET_MII_BMSR) {
            link_ready = (status & GENET_MII_BMSR_LSTATUS) != 0;
            let autoneg_ready = (status & GENET_MII_BMSR_ANEGCOMPLETE) != 0;
            resolved_speed = genet_resolve_phy_speed(phy_addr).or(resolved_speed);
            if link_ready && (autoneg_ready || resolved_speed.is_some()) {
                break;
            }
        }
        runtime_spin(GENET_PHY_LINK_POLL_DELAY_SPINS);
    }

    let speed = resolved_speed
        .or_else(|| genet_mdio_read(phy_addr, GENET_MII_BMCR).map(genet_decode_bmcr_speed))
        .unwrap_or(if link_ready {
            2
        } else {
            genet_current_umac_speed()
        });
    genet_set_umac_speed(speed);
    Some((phy_addr, link_ready, speed))
}

fn genet_discover_phy_addr() -> Option<u8> {
    let mut addr = 0u8;
    while addr < 32 {
        let id1 = genet_mdio_read(addr, GENET_MII_PHYSID1);
        let id2 = genet_mdio_read(addr, GENET_MII_PHYSID2);
        if let (Some(id1), Some(id2)) = (id1, id2) {
            if id1 != 0 && id1 != u16::MAX && id2 != 0 && id2 != u16::MAX {
                return Some(addr);
            }
        }
        addr = addr.saturating_add(1);
    }
    None
}

fn genet_mdio_wait_idle() -> bool {
    for _ in 0..GENET_MDIO_POLL_TRIES {
        if (genet_read32(GENET_MDIO_CMD) & GENET_MDIO_START_BUSY) == 0 {
            return true;
        }
        core::hint::spin_loop();
    }
    false
}

fn genet_mdio_read(phy_addr: u8, reg: u8) -> Option<u16> {
    if !genet_mdio_wait_idle() {
        return None;
    }
    let mut cmd = GENET_MDIO_RD
        | ((u32::from(phy_addr) & GENET_MDIO_FIELD_MASK) << GENET_MDIO_PMD_SHIFT)
        | ((u32::from(reg) & GENET_MDIO_FIELD_MASK) << GENET_MDIO_REG_SHIFT);
    genet_write32(GENET_MDIO_CMD, cmd);
    cmd |= GENET_MDIO_START_BUSY;
    genet_write32(GENET_MDIO_CMD, cmd);
    if !genet_mdio_wait_idle() {
        return None;
    }
    let value = genet_read32(GENET_MDIO_CMD);
    if (value & GENET_MDIO_READ_FAIL) != 0 {
        return None;
    }
    Some((value & 0xffff) as u16)
}

fn genet_mdio_write(phy_addr: u8, reg: u8, value: u16) -> bool {
    if !genet_mdio_wait_idle() {
        return false;
    }
    let cmd = GENET_MDIO_WR
        | ((u32::from(phy_addr) & GENET_MDIO_FIELD_MASK) << GENET_MDIO_PMD_SHIFT)
        | ((u32::from(reg) & GENET_MDIO_FIELD_MASK) << GENET_MDIO_REG_SHIFT)
        | u32::from(value);
    genet_write32(GENET_MDIO_CMD, cmd | GENET_MDIO_START_BUSY);
    genet_mdio_wait_idle() && (genet_read32(GENET_MDIO_CMD) & GENET_MDIO_READ_FAIL) == 0
}

fn genet_resolve_phy_speed(phy_addr: u8) -> Option<u32> {
    let adv_1000 = genet_mdio_read(phy_addr, GENET_MII_CTRL1000)?;
    let lpa_1000 = genet_mdio_read(phy_addr, GENET_MII_STAT1000)?;
    if (adv_1000 & GENET_ADVERTISE_1000FULL) != 0 && (lpa_1000 & GENET_LPA_1000FULL) != 0 {
        return Some(2);
    }
    if (adv_1000 & GENET_ADVERTISE_1000HALF) != 0 && (lpa_1000 & GENET_LPA_1000HALF) != 0 {
        return Some(2);
    }

    let adv = genet_mdio_read(phy_addr, GENET_MII_ADVERTISE)?;
    let lpa = genet_mdio_read(phy_addr, GENET_MII_LPA)?;
    if (adv & GENET_LPA_100FULL) != 0 && (lpa & GENET_LPA_100FULL) != 0 {
        return Some(1);
    }
    if (adv & GENET_LPA_100HALF) != 0 && (lpa & GENET_LPA_100HALF) != 0 {
        return Some(1);
    }
    if (adv & GENET_LPA_10FULL) != 0 && (lpa & GENET_LPA_10FULL) != 0 {
        return Some(0);
    }
    if (adv & GENET_LPA_10HALF) != 0 && (lpa & GENET_LPA_10HALF) != 0 {
        return Some(0);
    }
    None
}

const fn genet_decode_bmcr_speed(bmcr: u16) -> u32 {
    let speed_100 = (bmcr & GENET_MII_BMCR_SPEED100) != 0;
    let speed_1000 = (bmcr & GENET_MII_BMCR_SPEED1000) != 0;
    match (speed_100, speed_1000) {
        (false, false) => 0,
        (true, false) => 1,
        (false, true) | (true, true) => 2,
    }
}

fn genet_current_umac_speed() -> u32 {
    (genet_read32(GENET_UMAC_CMD) >> GENET_CMD_SPEED_SHIFT) & GENET_CMD_SPEED_MASK
}

fn genet_set_umac_speed(speed: u32) {
    let mut cmd = genet_read32(GENET_UMAC_CMD);
    cmd &= !(GENET_CMD_SPEED_MASK << GENET_CMD_SPEED_SHIFT);
    cmd |= (speed & GENET_CMD_SPEED_MASK) << GENET_CMD_SPEED_SHIFT;
    genet_write32(GENET_UMAC_CMD, cmd);
}

fn genet_write_mac(mac: [u8; 6]) {
    let mac0 = (u32::from(mac[0]) << 24)
        | (u32::from(mac[1]) << 16)
        | (u32::from(mac[2]) << 8)
        | u32::from(mac[3]);
    let mac1 = (u32::from(mac[4]) << 8) | u32::from(mac[5]);
    genet_write32(GENET_UMAC_MAC0, mac0);
    genet_write32(GENET_UMAC_MAC1, mac1);
}

fn genet_disable_dma() {
    genet_write32(
        GENET_TDMA_REG_BASE + GENET_DMA_CTRL,
        genet_read32(GENET_TDMA_REG_BASE + GENET_DMA_CTRL) & !GENET_DMA_EN,
    );
    genet_write32(
        GENET_RDMA_REG_BASE + GENET_DMA_CTRL,
        genet_read32(GENET_RDMA_REG_BASE + GENET_DMA_CTRL) & !GENET_DMA_EN,
    );
    genet_write32(GENET_UMAC_TX_FLUSH, 1);
    runtime_spin(10_000);
    genet_write32(GENET_UMAC_TX_FLUSH, 0);
}

fn genet_enable_dma() {
    let ctrl = (1u32 << (GENET_DEFAULT_Q + GENET_DMA_RING_BUF_EN_SHIFT)) | GENET_DMA_EN;
    genet_write32(GENET_TDMA_REG_BASE + GENET_DMA_CTRL, ctrl);
    genet_write32(
        GENET_RDMA_REG_BASE + GENET_DMA_CTRL,
        genet_read32(GENET_RDMA_REG_BASE + GENET_DMA_CTRL) | ctrl,
    );
}

fn genet_init_rx_ring() {
    genet_write32(
        GENET_RDMA_REG_BASE + GENET_DMA_SCB_BURST_SIZE,
        GENET_DMA_MAX_BURST_LENGTH,
    );
    genet_write32(GENET_RDMA_RING_REG_BASE + GENET_DMA_START_ADDR, 0);
    genet_write32(GENET_RDMA_READ_PTR, 0);
    genet_write32(GENET_RDMA_WRITE_PTR, 0);
    genet_write32(
        GENET_RDMA_RING_REG_BASE + GENET_DMA_END_ADDR,
        genet_ring_end_addr(GENET_HW_TOTAL_DESCS),
    );
    genet_write32(GENET_RDMA_CONS_INDEX, genet_read32(GENET_RDMA_PROD_INDEX));
    genet_write32(
        GENET_RDMA_RING_REG_BASE + GENET_DMA_RING_BUF_SIZE,
        genet_ring_buffer_size(GENET_HW_TOTAL_DESCS),
    );
    genet_write32(
        GENET_RDMA_XON_XOFF_THRESH,
        genet_dma_fc_thresh_value(GENET_HW_TOTAL_DESCS),
    );
    genet_write32(
        GENET_RDMA_REG_BASE + GENET_DMA_RING_CFG,
        1u32 << GENET_DEFAULT_Q,
    );
}

fn genet_init_tx_ring() {
    genet_write32(
        GENET_TDMA_REG_BASE + GENET_DMA_SCB_BURST_SIZE,
        GENET_DMA_MAX_BURST_LENGTH,
    );
    genet_write32(GENET_TDMA_RING_REG_BASE + GENET_DMA_START_ADDR, 0);
    genet_write32(GENET_TDMA_READ_PTR, 0);
    genet_write32(GENET_TDMA_WRITE_PTR, 0);
    genet_write32(
        GENET_TDMA_RING_REG_BASE + GENET_DMA_END_ADDR,
        genet_ring_end_addr(GENET_HW_TOTAL_DESCS),
    );
    genet_write32(GENET_TDMA_PROD_INDEX, genet_read32(GENET_TDMA_CONS_INDEX));
    genet_write32(GENET_TDMA_RING_REG_BASE + GENET_DMA_MBUF_DONE_THRESH, 1);
    genet_write32(GENET_TDMA_FLOW_PERIOD, 0);
    genet_write32(
        GENET_TDMA_RING_REG_BASE + GENET_DMA_RING_BUF_SIZE,
        genet_ring_buffer_size(GENET_HW_TOTAL_DESCS),
    );
    genet_write32(
        GENET_TDMA_REG_BASE + GENET_DMA_RING_CFG,
        1u32 << GENET_DEFAULT_Q,
    );
}

fn genet_rearm_rx_slot(
    descriptor: &DriverRuntimeInitDescriptor,
    dma_range: DriverRuntimeResourceRangeDescriptor,
    slot: usize,
) {
    let Some(dma_bus_addr) = runtime_resource_bus_addr_at(
        descriptor,
        dma_range,
        slot.saturating_mul(DRIVER_TASK_RING_PAGE_BYTES),
    ) else {
        return;
    };
    genet_write_rx_desc(slot, dma_bus_addr, genet_rx_owned_len_status());
}

fn genet_write_tx_desc(slot: usize, paddr: u64, len_status: u32) {
    if let Some(base) = genet_tx_desc_offset(slot) {
        genet_write32(base + 0x04, paddr as u32);
        genet_write32(base + 0x08, (paddr >> 32) as u32);
        genet_write32(base, len_status);
    }
}

fn genet_write_rx_desc(slot: usize, paddr: u64, len_status: u32) {
    if let Some(base) = genet_rx_desc_offset(slot) {
        genet_write32(base + 0x04, paddr as u32);
        genet_write32(base + 0x08, (paddr >> 32) as u32);
        genet_write32(base, len_status);
    }
}

fn genet_read_rx_desc(slot: usize) -> (u32, u32, u32) {
    if let Some(base) = genet_rx_desc_offset(slot) {
        (
            genet_read32(base),
            genet_read32(base + 0x04),
            genet_read32(base + 0x08),
        )
    } else {
        (0, 0, 0)
    }
}

fn sdio_runtime_init(sequence: u32, aux0: u32) -> Result<u16, u16> {
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_SDIO_STATE_RESET_BEGIN,
        aux0,
    );
    SDIO_RUNTIME_STATE.with_mut(SdioRuntimeState::reset);
    publish_runtime_progress(
        sequence,
        DRIVER_RUNTIME_RING_PROGRESS_SDIO_STATE_RESET_DONE,
        aux0,
    );
    publish_runtime_progress(sequence, DRIVER_RUNTIME_RING_PROGRESS_SDIO_HW_ENTRY, aux0);
    let result = sdio_runtime_init_hw(sequence, aux0);
    SDIO_RUNTIME_STATE.with_mut(|state| {
        state.initialized = result.is_ok();
    });
    result.map(|()| DRIVER_RUNTIME_SDIO_INIT_DETAIL_READY)
}

fn pcie_runtime_init(state: &mut PcieRuntimeState) -> bool {
    state.reset();
    let ok = pcie_runtime_init_hw(state);
    state.initialized = ok;
    ok
}

fn usb_reset_keyboard_interrupt_queue(state: &mut UsbRuntimeState) {
    state.keyboard_reports_queued = 0;
    state.keyboard_doorbell_pending = false;
    state.keyboard_report_in_use = [false; USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH];
    state.keyboard_report_trb_indices = [0; USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH];
    state.keyboard_preserved_event_count = 0;
    state.keyboard_preserved_event_parameters = [0; USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH];
    state.keyboard_preserved_event_statuses = [0; USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH];
    state.keyboard_preserved_event_controls = [0; USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH];
    state.keyboard_transfer_events = 0;
    state.keyboard_control_poll_disabled = false;
    state.keyboard_control_poll_cooldown = 0;
}

fn usb_runtime_poll_keyboard(state: &mut UsbRuntimeState) -> usize {
    if !state.initialized || state.keyboard_slot == 0 || state.keyboard_endpoint_id == 0 {
        return 0;
    }
    RUNTIME_DESCRIPTOR.with_ref(|descriptor| {
        if !xhci_arm_keyboard_interrupt_queue(state, descriptor) {
            return 0;
        }
        let Some(dma_range) = runtime_resource_range(
            descriptor,
            DRIVER_RUNTIME_RESOURCE_KIND_DMA,
            DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
        ) else {
            return 0;
        };
        let mut bytes = 0usize;
        for _ in 0..USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH {
            let Some((event, report_slot)) = xhci_next_keyboard_transfer_event(state, descriptor)
            else {
                break;
            };
            let code = xhci_completion_code(event.status);
            if code != XHCI_COMPLETION_SUCCESS && code != XHCI_COMPLETION_SHORT_PACKET {
                continue;
            }
            let report_len = usb_keyboard_report_request_len(state);
            let remaining = xhci_transfer_event_remaining(event.status).min(report_len);
            let payload_len = report_len.saturating_sub(remaining);
            if payload_len < USB_FLEXIBLE_KEYBOARD_REPORT_MIN_BYTES {
                continue;
            }
            let report_vaddr =
                dma_range.vaddr as usize + xhci_keyboard_report_buffer_offset(report_slot);
            dma_invalidate_range(report_vaddr, report_len);
            let mut payload = [0u8; USB_KEYBOARD_REPORT_BUFFER_BYTES];
            for (index, byte) in payload.iter_mut().take(payload_len).enumerate() {
                *byte = read_dma_byte(report_vaddr + index);
            }
            bytes = bytes.saturating_add(usb_keyboard_report_payload_to_frame_at(
                state,
                &payload[..payload_len],
                bytes,
            ));
            if bytes >= USB_KEYBOARD_OUTPUT_LIMIT {
                break;
            }
        }
        let _ = xhci_arm_keyboard_interrupt_queue(state, descriptor);
        if bytes == 0 {
            bytes = usb_poll_keyboard_control_report(state, descriptor);
        }
        bytes
    })
}

fn usb_keyboard_endpoint_ready(state: &mut UsbRuntimeState) -> bool {
    state.initialized && state.keyboard_slot != 0 && state.keyboard_endpoint_id != 0
}

fn usb_keyboard_pending_result(state: &mut UsbRuntimeState) -> u32 {
    u32::from(state.keyboard_reports_queued)
        | if state.keyboard_doorbell_pending {
            1 << 8
        } else {
            0
        }
        | (u32::from(state.keyboard_preserved_event_count) << 16)
        | ((state.keyboard_transfer_events.min(0xff) & 0xff) << 24)
}

const fn usb_keyboard_pending_result_has_transfer_event(result: u32) -> bool {
    (result >> 24) & 0xff != 0
}

fn usb_runtime_enumeration_result(state: &UsbRuntimeState) -> u32 {
    let command_proof_detail = matches!(
        state.init_detail,
        DRIVER_RUNTIME_USB_INIT_DETAIL_COMMAND_RING_PENDING
            | DRIVER_RUNTIME_USB_INIT_DETAIL_COMMAND_RING_READY
    );
    let snapshot_root_or_events = if command_proof_detail {
        u32::from(state.command_proof_events_seen)
    } else if state.command_path_proven {
        xhci_live_connected_root_port_mask(state)
    } else {
        0
    };
    let snapshot_slot =
        if command_proof_detail && state.keyboard_slot == 0 && state.last_address_slot == 0 {
            if state.command_proof_slot != 0 {
                state.command_proof_slot
            } else {
                state.command_proof_poll_slices
            }
        } else if state.keyboard_slot != 0 {
            state.keyboard_slot
        } else {
            state.last_address_slot
        };
    let snapshot_endpoint = if command_proof_detail && state.keyboard_endpoint_id == 0 {
        usb_command_proof_event_code(state.command_proof_last_event_type)
    } else {
        state.keyboard_endpoint_id & 0x1f
    };
    let snapshot_scan_pass = if command_proof_detail {
        state.command_proof_ack_failures & USB_ENUM_RESULT_SCAN_PASS_MASK as u8
    } else {
        state.enumeration_root_scan_pass & USB_ENUM_RESULT_SCAN_PASS_MASK as u8
    };
    (snapshot_root_or_events & USB_ENUM_RESULT_ROOT_PORT_MASK)
        | (u32::from(snapshot_slot) << USB_ENUM_RESULT_SLOT_SHIFT)
        | (u32::from(snapshot_endpoint) << USB_ENUM_RESULT_ENDPOINT_SHIFT)
        | (u32::from(snapshot_scan_pass) << USB_ENUM_RESULT_SCAN_PASS_SHIFT)
        | USB_ENUM_RESULT_SNAPSHOT
        | if state.enumeration_root_powered {
            USB_ENUM_RESULT_ROOT_POWERED
        } else {
            0
        }
        | if state.command_path_proven {
            USB_ENUM_RESULT_COMMAND_PATH
        } else {
            0
        }
        | if state.port_event_count != 0 {
            USB_ENUM_RESULT_PORT_EVENT
        } else {
            0
        }
        | if state.keyboard_endpoint_address != 0 {
            USB_ENUM_RESULT_HID_ENDPOINT
        } else {
            0
        }
        | if state.keyboard_preserved_event_count != 0 {
            USB_ENUM_RESULT_PRESERVED_EVENT
        } else {
            0
        }
        | if state.keyboard_transfer_events != 0 {
            USB_ENUM_RESULT_TRANSFER_EVENT
        } else {
            0
        }
        | if state.keyboard_slot != 0 && state.keyboard_endpoint_id != 0 {
            USB_ENUM_RESULT_ENDPOINT_READY
        } else {
            0
        }
}

const fn usb_command_proof_event_code(event_type: u8) -> u8 {
    match event_type as u32 {
        0 => USB_COMMAND_PROOF_EVENT_NONE,
        XHCI_TRB_TYPE_COMMAND_COMPLETION => USB_COMMAND_PROOF_EVENT_COMMAND_COMPLETION,
        XHCI_TRB_TYPE_PORT_STATUS_CHANGE_EVENT => USB_COMMAND_PROOF_EVENT_PORT_STATUS,
        XHCI_TRB_TYPE_TRANSFER_EVENT => USB_COMMAND_PROOF_EVENT_TRANSFER,
        _ => USB_COMMAND_PROOF_EVENT_OTHER,
    }
}

fn usb_runtime_enumeration_status(state: &mut UsbRuntimeState) -> Option<(u16, u32)> {
    let detail = usb_runtime_enumeration_detail(state)?;
    Some((detail, usb_runtime_enumeration_result(state)))
}

fn usb_runtime_enumeration_detail(state: &mut UsbRuntimeState) -> Option<u16> {
    if !state.initialized {
        return None;
    }
    match state.init_detail {
        DRIVER_RUNTIME_USB_INIT_DETAIL_XHCI_READY
        | DRIVER_RUNTIME_USB_INIT_DETAIL_COMMAND_RING_PENDING
        | DRIVER_RUNTIME_USB_INIT_DETAIL_COMMAND_RING_READY
        | DRIVER_RUNTIME_USB_INIT_DETAIL_ROOT_PORT_CONNECTED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_DEVICE_ADDRESSED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_DEVICE_DESCRIPTOR
        | DRIVER_RUNTIME_USB_INIT_DETAIL_CONFIG_DESCRIPTOR
        | DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_TOPOLOGY_SEEN
        | DRIVER_RUNTIME_USB_INIT_DETAIL_HID_ENDPOINT_SEEN
        | DRIVER_RUNTIME_USB_INIT_DETAIL_ENABLE_SLOT_FAILED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_ADDRESS_DEVICE_FAILED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_DEVICE_DESCRIPTOR_FAILED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_CONFIG_DESCRIPTOR_FAILED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_HID_ATTACH_FAILED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_ATTACH_FAILED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_SET_CONFIG_FAILED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_DESCRIPTOR_FAILED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_CONTEXT_FAILED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_KEYBOARD_READY => Some(state.init_detail),
        _ => None,
    }
}

const fn usb_enumeration_detail_rank(detail: u16) -> u8 {
    match detail {
        DRIVER_RUNTIME_USB_INIT_DETAIL_XHCI_READY => 3,
        DRIVER_RUNTIME_USB_INIT_DETAIL_COMMAND_RING_PENDING => 4,
        DRIVER_RUNTIME_USB_INIT_DETAIL_COMMAND_RING_READY => 4,
        DRIVER_RUNTIME_USB_INIT_DETAIL_ROOT_PORT_CONNECTED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_ENABLE_SLOT_FAILED => 5,
        DRIVER_RUNTIME_USB_INIT_DETAIL_DEVICE_ADDRESSED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_ADDRESS_DEVICE_FAILED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_DEVICE_DESCRIPTOR_FAILED => 6,
        DRIVER_RUNTIME_USB_INIT_DETAIL_DEVICE_DESCRIPTOR
        | DRIVER_RUNTIME_USB_INIT_DETAIL_CONFIG_DESCRIPTOR
        | DRIVER_RUNTIME_USB_INIT_DETAIL_CONFIG_DESCRIPTOR_FAILED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_TOPOLOGY_SEEN
        | DRIVER_RUNTIME_USB_INIT_DETAIL_HID_ENDPOINT_SEEN
        | DRIVER_RUNTIME_USB_INIT_DETAIL_HID_ATTACH_FAILED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_ATTACH_FAILED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_SET_CONFIG_FAILED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_DESCRIPTOR_FAILED
        | DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_CONTEXT_FAILED => 7,
        DRIVER_RUNTIME_USB_INIT_DETAIL_KEYBOARD_READY => 8,
        _ => 0,
    }
}

fn usb_remember_best_enumeration_detail(best: &mut u16, detail: u16) {
    if usb_enumeration_detail_rank(detail) >= usb_enumeration_detail_rank(*best) {
        *best = detail;
    }
}

fn usb_reset_enumeration_cursor(state: &mut UsbRuntimeState) {
    state.enumeration_root_powered = false;
    state.enumeration_root_scan_pass = 0;
    state.enumeration_root_next_port = 1;
    state.enumeration_best_detail = state.init_detail;
    state.enumeration_retry_window_exhausted = false;
}

const fn usb_detail_warrants_cold_reinit(detail: u16) -> bool {
    matches!(detail, DRIVER_RUNTIME_USB_INIT_DETAIL_ENABLE_SLOT_FAILED)
}

const fn usb_detail_warrants_deep_cold_reinit(detail: u16) -> bool {
    matches!(
        detail,
        DRIVER_RUNTIME_USB_INIT_DETAIL_ADDRESS_DEVICE_FAILED
            | DRIVER_RUNTIME_USB_INIT_DETAIL_DEVICE_DESCRIPTOR_FAILED
            | DRIVER_RUNTIME_USB_INIT_DETAIL_CONFIG_DESCRIPTOR_FAILED
            | DRIVER_RUNTIME_USB_INIT_DETAIL_HID_ATTACH_FAILED
            | DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_ATTACH_FAILED
            | DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_SET_CONFIG_FAILED
            | DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_DESCRIPTOR_FAILED
            | DRIVER_RUNTIME_USB_INIT_DETAIL_HUB_CONTEXT_FAILED
    )
}

fn usb_runtime_reinitialize_controller(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
    descriptor: &DriverRuntimeInitDescriptor,
    fallback_detail: u16,
    command_cold_attempts: u8,
    deep_cold_attempts: u8,
    deep_cold_detail: u16,
) -> u16 {
    state.reset();
    state.enumeration_cold_reinit_attempts = command_cold_attempts;
    state.enumeration_deep_cold_reinit_attempts = deep_cold_attempts;
    state.enumeration_deep_cold_reinit_detail = deep_cold_detail;
    if let Some(detail) = usb_runtime_init_hw(sequence, aux0, descriptor, state) {
        state.initialized = true;
        state.init_detail = detail;
        usb_reset_enumeration_cursor(state);
        detail
    } else {
        state.initialized = true;
        state.init_detail = fallback_detail;
        fallback_detail
    }
}

fn usb_reset_deep_cold_reinit_frontier(state: &mut UsbRuntimeState, detail: u16) {
    state.enumeration_deep_cold_reinit_attempts = 0;
    state.enumeration_deep_cold_reinit_detail = detail;
}

fn usb_prepare_deep_cold_reinit_attempt(state: &mut UsbRuntimeState, detail: u16) -> Option<u8> {
    if !usb_detail_warrants_deep_cold_reinit(detail) {
        usb_reset_deep_cold_reinit_frontier(state, detail);
        return None;
    }
    if state.enumeration_deep_cold_reinit_detail != detail {
        usb_reset_deep_cold_reinit_frontier(state, detail);
    }
    if state.enumeration_deep_cold_reinit_attempts >= USB_ENUMERATION_DEEP_COLD_REINIT_LIMIT {
        return None;
    }
    let next_attempt = state
        .enumeration_deep_cold_reinit_attempts
        .saturating_add(1);
    state.enumeration_deep_cold_reinit_attempts = next_attempt;
    Some(next_attempt)
}

fn usb_runtime_retry_keyboard_enumeration(
    sequence: u32,
    aux0: u32,
    state: &mut UsbRuntimeState,
) -> Option<u16> {
    if !state.initialized {
        return None;
    }
    if state.keyboard_slot != 0 && state.keyboard_endpoint_id != 0 {
        state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_KEYBOARD_READY;
        return Some(DRIVER_RUNTIME_USB_INIT_DETAIL_KEYBOARD_READY);
    }
    if state.enumeration_retry_cooldown != 0 {
        state.enumeration_retry_cooldown = state.enumeration_retry_cooldown.saturating_sub(1);
        return usb_runtime_enumeration_detail(state).or(Some(state.init_detail));
    }
    state.enumeration_retry_cooldown = USB_ENUMERATION_RETRY_COOLDOWN_TURNS;
    RUNTIME_DESCRIPTOR.with_ref(|descriptor| {
        let dma_range = runtime_resource_range(
            descriptor,
            DRIVER_RUNTIME_RESOURCE_KIND_DMA,
            DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
        )?;
        let mut before = state.init_detail;
        if usb_detail_warrants_cold_reinit(before)
            && state.enumeration_cold_reinit_attempts < USB_ENUMERATION_COLD_REINIT_LIMIT
        {
            let next_attempt = state.enumeration_cold_reinit_attempts.saturating_add(1);
            let deep_attempts = state.enumeration_deep_cold_reinit_attempts;
            let deep_detail = state.enumeration_deep_cold_reinit_detail;
            usb_runtime_reinitialize_controller(
                sequence,
                aux0,
                state,
                descriptor,
                before,
                next_attempt,
                deep_attempts,
                deep_detail,
            );
            usb_reset_deep_cold_reinit_frontier(state, state.init_detail);
            before = state.init_detail;
        }
        state.enumeration_retry_window_exhausted = false;
        if usb_keyboard_enumerate(sequence, aux0, state, descriptor, dma_range) {
            state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_KEYBOARD_READY;
            state.enumeration_retry_cooldown = 0;
            state.enumeration_cold_reinit_attempts = 0;
            usb_reset_deep_cold_reinit_frontier(
                state,
                DRIVER_RUNTIME_USB_INIT_DETAIL_KEYBOARD_READY,
            );
            Some(DRIVER_RUNTIME_USB_INIT_DETAIL_KEYBOARD_READY)
        } else {
            if state.enumeration_retry_window_exhausted {
                let detail = state.init_detail;
                if let Some(deep_attempt) = usb_prepare_deep_cold_reinit_attempt(state, detail) {
                    let command_attempts = state.enumeration_cold_reinit_attempts;
                    let reinit_detail = usb_runtime_reinitialize_controller(
                        sequence,
                        aux0,
                        state,
                        descriptor,
                        detail,
                        command_attempts,
                        deep_attempt,
                        detail,
                    );
                    return Some(reinit_detail);
                }
            }
            if state.init_detail != before || state.port_event_candidate_mask != 0 {
                Some(state.init_detail)
            } else {
                usb_runtime_enumeration_detail(state).or(Some(state.init_detail))
            }
        }
    })
}

#[cfg(test)]
fn usb_keyboard_report_bytes_to_frame(
    state: &mut UsbRuntimeState,
    report: [u8; USB_BOOT_REPORT_BYTES],
) -> usize {
    usb_keyboard_report_bytes_to_frame_at(state, report, 0)
}

fn usb_keyboard_report_bytes_to_frame_at(
    state: &mut UsbRuntimeState,
    report: [u8; USB_BOOT_REPORT_BYTES],
    output_offset: usize,
) -> usize {
    let mut produced = 0usize;
    'keys: for &code in report[2..].iter() {
        if code == 0 {
            continue;
        }
        if state.last_keys.contains(&code) {
            continue;
        }
        if usb_keyboard_toggle_lock(state, code) {
            continue;
        }
        if let Some(sequence) = usb_hid_usage_to_sequence(code) {
            for &byte in sequence {
                let Some(frame_offset) = output_offset.checked_add(produced) else {
                    break 'keys;
                };
                if frame_offset >= USB_KEYBOARD_OUTPUT_LIMIT {
                    break 'keys;
                }
                write_ring_byte(DRIVER_TASK_RING_FRAME_OFFSET + frame_offset, byte);
                produced = produced.saturating_add(1);
                if output_offset.saturating_add(produced) >= USB_KEYBOARD_OUTPUT_LIMIT {
                    break 'keys;
                }
            }
            continue;
        }
        let shifted = report[0] & 0x22 != 0;
        let Some(mut byte) = usb_hid_usage_to_ascii(code, shifted) else {
            continue;
        };
        if state.caps_lock_on && byte.is_ascii_alphabetic() {
            byte ^= 0x20;
        }
        let Some(frame_offset) = output_offset.checked_add(produced) else {
            break;
        };
        if frame_offset >= USB_KEYBOARD_OUTPUT_LIMIT {
            break;
        }
        write_ring_byte(DRIVER_TASK_RING_FRAME_OFFSET + frame_offset, byte);
        produced = produced.saturating_add(1);
        if output_offset.saturating_add(produced) >= USB_KEYBOARD_OUTPUT_LIMIT {
            break;
        }
    }
    state.last_keys.copy_from_slice(&report[2..8]);
    produced
}

fn usb_keyboard_report_payload_to_frame_at(
    state: &mut UsbRuntimeState,
    payload: &[u8],
    output_offset: usize,
) -> usize {
    let Some(report) =
        usb_decode_keyboard_report_payload(payload, usb_keyboard_report_preferred_offset(state))
    else {
        return 0;
    };
    usb_keyboard_report_bytes_to_frame_at(state, report, output_offset)
}

const fn usb_keyboard_report_preferred_offset(state: &UsbRuntimeState) -> usize {
    if state.keyboard_attach_rank == USB_KEYBOARD_ATTACH_RANK_STRICT_BOOT {
        0
    } else {
        1
    }
}

fn usb_decode_keyboard_report_payload(
    payload: &[u8],
    preferred_offset: usize,
) -> Option<[u8; USB_BOOT_REPORT_BYTES]> {
    if payload.len() < USB_FLEXIBLE_KEYBOARD_REPORT_MIN_BYTES {
        return None;
    }
    if let Some(report) = usb_decode_keyboard_report_at(payload, preferred_offset) {
        return Some(report);
    }
    let mut offset = 0usize;
    while offset < payload.len() {
        if offset != preferred_offset {
            if let Some(report) = usb_decode_keyboard_report_at(payload, offset) {
                return Some(report);
            }
        }
        offset += 1;
    }
    None
}

fn usb_decode_keyboard_report_at(
    payload: &[u8],
    offset: usize,
) -> Option<[u8; USB_BOOT_REPORT_BYTES]> {
    usb_decode_boot_keyboard_report_at(payload, offset)
        .or_else(|| usb_decode_compact_keyboard_report_at(payload, offset))
        .or_else(|| usb_decode_bitmap_keyboard_report_at(payload, offset))
}

fn usb_decode_boot_keyboard_report_at(
    payload: &[u8],
    offset: usize,
) -> Option<[u8; USB_BOOT_REPORT_BYTES]> {
    if offset.checked_add(USB_BOOT_REPORT_BYTES)? > payload.len() {
        return None;
    }
    let mut report = [0u8; USB_BOOT_REPORT_BYTES];
    report.copy_from_slice(&payload[offset..offset + USB_BOOT_REPORT_BYTES]);
    if report[1] != 0 || !usb_keyboard_keys_valid(&report[2..8]) {
        return None;
    }
    Some(report)
}

fn usb_decode_compact_keyboard_report_at(
    payload: &[u8],
    offset: usize,
) -> Option<[u8; USB_BOOT_REPORT_BYTES]> {
    if offset.checked_add(7)? > payload.len() {
        return None;
    }
    let mut report = [0u8; USB_BOOT_REPORT_BYTES];
    report[0] = payload[offset];
    report[2..8].copy_from_slice(&payload[offset + 1..offset + 7]);
    if !usb_keyboard_keys_valid(&report[2..8]) {
        return None;
    }
    Some(report)
}

fn usb_decode_bitmap_keyboard_report_at(
    payload: &[u8],
    offset: usize,
) -> Option<[u8; USB_BOOT_REPORT_BYTES]> {
    if offset.checked_add(4)? > payload.len() || payload[offset + 1] != 0 {
        return None;
    }
    let mut report = [0u8; USB_BOOT_REPORT_BYTES];
    report[0] = payload[offset];
    let mut count = 0usize;
    for (byte_index, byte) in payload[offset + 2..].iter().copied().enumerate() {
        if byte == 0 {
            continue;
        }
        let base_usage = byte_index.checked_mul(8)?;
        if base_usage > u8::MAX as usize {
            break;
        }
        for bit in 0..8usize {
            if (byte & (1u8 << bit)) == 0 {
                continue;
            }
            let usage_index = base_usage.saturating_add(bit);
            if usage_index > u8::MAX as usize {
                break;
            }
            let usage = usage_index as u8;
            if !usb_keyboard_usage_code_valid(usage) || report[2..2 + count].contains(&usage) {
                continue;
            }
            if count >= 6 {
                return Some(report);
            }
            report[2 + count] = usage;
            count += 1;
        }
    }
    (count != 0).then_some(report)
}

fn usb_keyboard_usage_code_valid(code: u8) -> bool {
    code == 0 || (code >= 0x04 && code <= 0xe7)
}

fn usb_keyboard_keys_valid(keys: &[u8]) -> bool {
    let mut index = 0usize;
    while index < keys.len() {
        if !usb_keyboard_usage_code_valid(keys[index]) {
            return false;
        }
        index += 1;
    }
    true
}

fn usb_keyboard_toggle_lock(state: &mut UsbRuntimeState, code: u8) -> bool {
    match code {
        USB_HID_USAGE_CAPS_LOCK => state.caps_lock_on = !state.caps_lock_on,
        USB_HID_USAGE_NUM_LOCK => state.num_lock_on = !state.num_lock_on,
        USB_HID_USAGE_SCROLL_LOCK => state.scroll_lock_on = !state.scroll_lock_on,
        _ => return false,
    }
    let leds = usb_keyboard_led_bitmap(state);
    RUNTIME_DESCRIPTOR.with_ref(|descriptor| {
        state.led_sync_failed = state.keyboard_slot == 0
            || state.keyboard_interface == 0xff
            || !usb_set_hid_leds(state, descriptor, leds);
    });
    true
}

fn usb_keyboard_led_bitmap(state: &UsbRuntimeState) -> u8 {
    (if state.num_lock_on {
        USB_HID_LED_NUM_LOCK
    } else {
        0
    }) | (if state.caps_lock_on {
        USB_HID_LED_CAPS_LOCK
    } else {
        0
    }) | (if state.scroll_lock_on {
        USB_HID_LED_SCROLL_LOCK
    } else {
        0
    })
}

fn usb_hid_usage_to_sequence(code: u8) -> Option<&'static [u8]> {
    if code == USB_HID_USAGE_UP_ARROW {
        Some(b"\x1b[A")
    } else if code == USB_HID_USAGE_DOWN_ARROW {
        Some(b"\x1b[B")
    } else if code == USB_HID_USAGE_RIGHT_ARROW {
        Some(b"\x1b[C")
    } else if code == USB_HID_USAGE_LEFT_ARROW {
        Some(b"\x1b[D")
    } else {
        None
    }
}

fn usb_hid_usage_to_ascii(code: u8, shifted: bool) -> Option<u8> {
    match code {
        0x04..=0x1d => {
            let base = if shifted { b'A' } else { b'a' };
            Some(base + (code - 0x04))
        }
        0x1e..=0x26 => Some(if shifted {
            b"!@#$%^&*("[usize::from(code - 0x1e)]
        } else {
            b"123456789"[usize::from(code - 0x1e)]
        }),
        0x27 => Some(if shifted { b')' } else { b'0' }),
        0x28 => Some(b'\n'),
        0x2a => Some(0x08),
        0x2c => Some(b' '),
        0x2d => Some(if shifted { b'_' } else { b'-' }),
        0x2e => Some(if shifted { b'+' } else { b'=' }),
        0x2f => Some(if shifted { b'{' } else { b'[' }),
        0x30 => Some(if shifted { b'}' } else { b']' }),
        0x31 => Some(if shifted { b'|' } else { b'\\' }),
        0x33 => Some(if shifted { b':' } else { b';' }),
        0x34 => Some(if shifted { b'"' } else { b'\'' }),
        0x35 => Some(if shifted { b'~' } else { b'`' }),
        0x36 => Some(if shifted { b'<' } else { b',' }),
        0x37 => Some(if shifted { b'>' } else { b'.' }),
        0x38 => Some(if shifted { b'?' } else { b'/' }),
        _ => None,
    }
}

fn hdmi_render_frame(frame: DriverFrameDescriptor) -> usize {
    RUNTIME_DESCRIPTOR.with_ref(|descriptor| {
        let mut state = HdmiRenderState::from_descriptor(descriptor);
        let mut rendered = 0usize;
        for index in 0..frame.len as usize {
            let byte = read_ring_byte(frame.offset as usize + index);
            state.put_byte(byte);
            rendered = rendered.saturating_add(1);
        }
        HDMI_CURSOR_ROW.store(state.row as u32, Ordering::Release);
        HDMI_CURSOR_COL.store(state.col as u32, Ordering::Release);
        rendered
    })
}

fn hdmi_render_boot_diagnostics(descriptor: &DriverRuntimeInitDescriptor) {
    let mut state = HdmiRenderState::from_descriptor(descriptor);
    state.clear_full_framebuffer();
    state.put_str("Cohesix HDMI linked runtime\n");
    state.put_str("framebuffer descriptor ready\n");
    state.put_str("waiting for console mirror\n");
    HDMI_CURSOR_ROW.store(0, Ordering::Release);
    HDMI_CURSOR_COL.store(0, Ordering::Release);
}

struct HdmiRenderState {
    framebuffer: usize,
    framebuffer_len: usize,
    framebuffer_width: usize,
    framebuffer_height: usize,
    safe_x: usize,
    safe_y: usize,
    width: usize,
    height: usize,
    pitch: usize,
    format: u32,
    cols: usize,
    rows: usize,
    row: usize,
    col: usize,
}

impl HdmiRenderState {
    fn from_descriptor(descriptor: &DriverRuntimeInitDescriptor) -> Self {
        let framebuffer_width = descriptor.framebuffer.width as usize;
        let framebuffer_height = descriptor.framebuffer.height as usize;
        let pitch = descriptor.framebuffer.pitch as usize;
        let safe_area = hdmi_safe_area_for_framebuffer(framebuffer_width, framebuffer_height);
        let cols = (safe_area.width / CHAR_WIDTH).max(1);
        let rows = (safe_area.height / CHAR_HEIGHT).max(1);
        let row = (HDMI_CURSOR_ROW.load(Ordering::Acquire) as usize).min(rows.saturating_sub(1));
        let col = (HDMI_CURSOR_COL.load(Ordering::Acquire) as usize).min(cols);
        let framebuffer_len = pitch.saturating_mul(framebuffer_height);
        Self {
            framebuffer: descriptor.framebuffer.vaddr as usize,
            framebuffer_len,
            framebuffer_width,
            framebuffer_height,
            safe_x: safe_area.x,
            safe_y: safe_area.y,
            width: safe_area.width,
            height: safe_area.height,
            pitch,
            format: descriptor.framebuffer.format,
            cols,
            rows,
            row,
            col,
        }
    }

    fn put_byte(&mut self, byte: u8) {
        match byte {
            b'\n' => self.newline(),
            b'\r' => self.col = 0,
            0x0c => {
                self.clear_full_framebuffer();
                self.row = 0;
                self.col = 0;
            }
            0x08 | 0x7f => self.backspace(),
            b'\t' => {
                for _ in 0..4 {
                    self.put_byte(b' ');
                }
            }
            byte => {
                if self.col >= self.cols {
                    self.newline();
                }
                self.draw_char(byte);
                self.col = self.col.saturating_add(1);
            }
        }
    }

    fn put_str(&mut self, text: &str) {
        for byte in text.bytes() {
            self.put_byte(byte);
        }
    }

    fn newline(&mut self) {
        self.col = 0;
        self.row = self.row.saturating_add(1);
        if self.row >= self.rows {
            self.scroll_up_one_text_row();
        }
    }

    fn backspace(&mut self) {
        if self.col == 0 {
            if self.row != 0 {
                self.row = self.row.saturating_sub(1);
                self.col = self.cols.saturating_sub(1);
            }
        } else {
            self.col = self.col.saturating_sub(1);
        }
        self.draw_char(b' ');
    }

    fn scroll_up_one_text_row(&mut self) {
        let Some(bytes_per_pixel) = self.bytes_per_pixel() else {
            self.clear_text_area();
            self.row = 0;
            self.col = 0;
            return;
        };
        let text_height = self.rows.saturating_mul(CHAR_HEIGHT).min(self.height);
        if text_height <= CHAR_HEIGHT || self.pitch == 0 || self.width == 0 {
            self.clear_text_area();
            self.row = 0;
            self.col = 0;
            return;
        }
        let Some(row_bytes) = self.width.checked_mul(bytes_per_pixel) else {
            self.clear_text_area();
            self.row = 0;
            self.col = 0;
            return;
        };
        if row_bytes == 0 || row_bytes > self.pitch {
            self.clear_text_area();
            self.row = 0;
            self.col = 0;
            return;
        }
        let copy_rows = text_height.saturating_sub(CHAR_HEIGHT);
        for y in 0..copy_rows {
            let Some(dst_off) =
                self.framebuffer_offset(self.safe_x, self.safe_y + y, bytes_per_pixel)
            else {
                continue;
            };
            let Some(src_off) = self.framebuffer_offset(
                self.safe_x,
                self.safe_y + y + CHAR_HEIGHT,
                bytes_per_pixel,
            ) else {
                continue;
            };
            let Some(dst_end) = dst_off.checked_add(row_bytes) else {
                continue;
            };
            let Some(src_end) = src_off.checked_add(row_bytes) else {
                continue;
            };
            if dst_end > self.framebuffer_len || src_end > self.framebuffer_len {
                continue;
            }
            copy_framebuffer_bytes(
                self.framebuffer + dst_off,
                self.framebuffer + src_off,
                row_bytes,
            );
        }
        self.fill_rect(
            0,
            text_height.saturating_sub(CHAR_HEIGHT),
            self.width,
            CHAR_HEIGHT,
            HDMI_BG_COLOR,
        );
        self.row = self.rows.saturating_sub(1);
        self.col = 0;
    }

    fn clear_text_area(&mut self) {
        self.fill_rect(0, 0, self.width, self.height, HDMI_BG_COLOR);
    }

    fn clear_full_framebuffer(&mut self) {
        let Some(bytes_per_pixel) = self.bytes_per_pixel() else {
            self.clear_text_area();
            return;
        };
        if self.framebuffer_width == 0
            || self.framebuffer_height == 0
            || self.pitch == 0
            || self.framebuffer_len == 0
        {
            return;
        }
        for y in 0..self.framebuffer_height {
            for x in 0..self.framebuffer_width {
                let Some(byte_off) = self.framebuffer_offset(x, y, bytes_per_pixel) else {
                    continue;
                };
                write_framebuffer_pixel(
                    self.framebuffer + byte_off,
                    HDMI_BG_COLOR,
                    bytes_per_pixel,
                );
            }
        }
    }

    fn draw_char(&mut self, byte: u8) {
        let glyph = BASIC_LEGACY[usize::from(byte.min(0x7f))];
        let x0 = self.col.saturating_mul(CHAR_WIDTH);
        let y0 = self.row.saturating_mul(CHAR_HEIGHT);
        self.fill_rect(x0, y0, CHAR_WIDTH, CHAR_HEIGHT, HDMI_BG_COLOR);
        for (gy, bits) in glyph.iter().enumerate() {
            for gx in 0..CHAR_WIDTH {
                if ((bits >> gx) & 1) == 0 {
                    continue;
                }
                let x = x0.saturating_add(gx);
                let y = y0.saturating_add(gy.saturating_mul(2));
                self.put_pixel(x, y, HDMI_FG_COLOR);
                self.put_pixel(x, y.saturating_add(1), HDMI_FG_COLOR);
            }
        }
    }

    fn fill_rect(&mut self, x: usize, y: usize, w: usize, h: usize, color: u32) {
        let x_end = self.width.min(x.saturating_add(w));
        let y_end = self.height.min(y.saturating_add(h));
        if x >= x_end || y >= y_end {
            return;
        }
        for yy in y..y_end {
            for xx in x..x_end {
                self.put_pixel(xx, yy, color);
            }
        }
    }

    fn put_pixel(&mut self, x: usize, y: usize, color: u32) {
        if x >= self.width || y >= self.height {
            return;
        }
        let Some(abs_x) = self.safe_x.checked_add(x) else {
            return;
        };
        let Some(abs_y) = self.safe_y.checked_add(y) else {
            return;
        };
        if abs_x >= self.framebuffer_width || abs_y >= self.framebuffer_height {
            return;
        }
        let Some(bytes_per_pixel) = self.bytes_per_pixel() else {
            return;
        };
        let Some(byte_off) = self.framebuffer_offset(abs_x, abs_y, bytes_per_pixel) else {
            return;
        };
        write_framebuffer_pixel(self.framebuffer + byte_off, color, bytes_per_pixel);
    }

    fn bytes_per_pixel(&self) -> Option<usize> {
        match self.format {
            DRIVER_RUNTIME_FRAMEBUFFER_FORMAT_RGB888 => Some(3),
            DRIVER_RUNTIME_FRAMEBUFFER_FORMAT_XRGB8888 | 0 => Some(FB_BYTES_PER_PIXEL_32),
            _ => None,
        }
    }

    fn framebuffer_offset(&self, x: usize, y: usize, bytes_per_pixel: usize) -> Option<usize> {
        if x >= self.framebuffer_width || y >= self.framebuffer_height {
            return None;
        }
        let row_off = y.checked_mul(self.pitch)?;
        let col_off = x.checked_mul(bytes_per_pixel)?;
        let byte_off = row_off.checked_add(col_off)?;
        let end = byte_off.checked_add(bytes_per_pixel)?;
        (end <= self.framebuffer_len).then_some(byte_off)
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct HdmiSafeArea {
    x: usize,
    y: usize,
    width: usize,
    height: usize,
}

fn hdmi_safe_area_for_framebuffer(width: usize, height: usize) -> HdmiSafeArea {
    let (x, safe_width) = hdmi_safe_axis(width, CHAR_WIDTH);
    let (y, safe_height) = hdmi_safe_axis(height, CHAR_HEIGHT);
    HdmiSafeArea {
        x,
        y,
        width: safe_width,
        height: safe_height,
    }
}

fn hdmi_safe_axis(total: usize, cell: usize) -> (usize, usize) {
    if total == 0 {
        return (0, 0);
    }
    if total <= cell {
        return (0, total);
    }
    let min_visible = cell.min(total);
    let desired_margin = (total / HDMI_SAFE_AREA_MARGIN_DIVISOR).max(1);
    let max_margin = total.saturating_sub(min_visible) / 2;
    let margin = desired_margin.min(max_margin);
    let available = total.saturating_sub(margin.saturating_mul(2));
    let cells = (available / cell).max(1);
    let aligned = cells.saturating_mul(cell).min(available);
    let offset = margin.saturating_add(available.saturating_sub(aligned) / 2);
    (offset, aligned)
}

#[cfg(test)]
fn read_frame_prefix<const N: usize>(frame: DriverFrameDescriptor) -> [u8; N] {
    let mut out = [0u8; N];
    let len = (frame.len as usize).min(N);
    for (index, slot) in out.iter_mut().enumerate().take(len) {
        *slot = read_ring_byte(frame.offset as usize + index);
    }
    out
}

#[cfg(target_os = "none")]
fn read_ring_byte(offset: usize) -> u8 {
    // SAFETY: Callers validate frame descriptors before reading payload bytes.
    unsafe { core::ptr::read_volatile((DRIVER_TASK_RING_VADDR + offset) as *const u8) }
}

#[cfg(all(not(target_os = "none"), test))]
struct TestRing(UnsafeCell<[u8; DRIVER_TASK_RING_PAGE_BYTES]>);

#[cfg(all(not(target_os = "none"), test))]
struct TestSharedBuffer(UnsafeCell<[u8; DRIVER_TASK_RING_PAGE_BYTES * 64]>);

#[cfg(all(not(target_os = "none"), test))]
struct TestDmaBuffer(UnsafeCell<[u8; XHCI_DMA_ZERO_BYTES]>);

#[cfg(all(not(target_os = "none"), test))]
// SAFETY: Runtime tests serialize all access through `test_guard`, so the
// process-local ring buffer is never concurrently mutated.
unsafe impl Sync for TestRing {}

#[cfg(all(not(target_os = "none"), test))]
// SAFETY: Runtime tests serialize all access through `test_guard`, so the
// process-local shared buffer is never concurrently mutated.
unsafe impl Sync for TestSharedBuffer {}

#[cfg(all(not(target_os = "none"), test))]
// SAFETY: Runtime tests serialize all access through `test_guard`, so the
// process-local DMA buffer is never concurrently mutated.
unsafe impl Sync for TestDmaBuffer {}

#[cfg(all(not(target_os = "none"), test))]
static TEST_RING: TestRing = TestRing(UnsafeCell::new([0; DRIVER_TASK_RING_PAGE_BYTES]));

#[cfg(all(not(target_os = "none"), test))]
static TEST_SHARED_BUFFER: TestSharedBuffer =
    TestSharedBuffer(UnsafeCell::new([0; DRIVER_TASK_RING_PAGE_BYTES * 64]));

#[cfg(all(not(target_os = "none"), test))]
static TEST_DMA_BUFFER: TestDmaBuffer = TestDmaBuffer(UnsafeCell::new([0; XHCI_DMA_ZERO_BYTES]));

#[cfg(all(not(target_os = "none"), test))]
fn reset_test_ring() {
    // SAFETY: Runtime tests hold `test_guard` before resetting shared state.
    unsafe {
        (*TEST_RING.0.get()).fill(0);
        (*TEST_SHARED_BUFFER.0.get()).fill(0);
        (*TEST_DMA_BUFFER.0.get()).fill(0);
    }
}

#[cfg(all(not(target_os = "none"), test))]
fn read_ring_byte(offset: usize) -> u8 {
    if offset >= DRIVER_TASK_RING_PAGE_BYTES {
        return 0;
    }
    // SAFETY: Runtime tests hold `test_guard` and the bounds check above keeps
    // reads inside the process-local fixed ring.
    unsafe { (*TEST_RING.0.get())[offset] }
}

#[cfg(all(not(target_os = "none"), not(test)))]
fn read_ring_byte(_offset: usize) -> u8 {
    0
}

#[cfg(target_os = "none")]
fn write_ring_byte(offset: usize, value: u8) {
    // SAFETY: Callers write only into the fixed shared ring payload region.
    unsafe {
        core::ptr::write_volatile((DRIVER_TASK_RING_VADDR + offset) as *mut u8, value);
    }
}

#[cfg(all(not(target_os = "none"), test))]
fn write_ring_byte(offset: usize, value: u8) {
    if offset >= DRIVER_TASK_RING_PAGE_BYTES {
        return;
    }
    // SAFETY: Runtime tests hold `test_guard` and the bounds check above keeps
    // writes inside the process-local fixed ring.
    unsafe {
        (*TEST_RING.0.get())[offset] = value;
    }
}

#[cfg(all(not(target_os = "none"), not(test)))]
fn write_ring_byte(_offset: usize, _value: u8) {}

#[cfg(target_os = "none")]
fn read_shared_buffer_byte(offset: usize) -> u8 {
    // SAFETY: Callers validate the offset against the runtime init descriptor's
    // shared-buffer resource range before reading payload bytes.
    unsafe { core::ptr::read_volatile((DRIVER_TASK_SHARED_BUFFER_VADDR + offset) as *const u8) }
}

#[cfg(all(not(target_os = "none"), test))]
fn read_shared_buffer_byte(offset: usize) -> u8 {
    if offset >= DRIVER_TASK_RING_PAGE_BYTES * 64 {
        return 0;
    }
    // SAFETY: Runtime tests hold `test_guard` and the bounds check above keeps
    // reads inside the process-local fixed shared buffer.
    unsafe { (*TEST_SHARED_BUFFER.0.get())[offset] }
}

#[cfg(all(not(target_os = "none"), not(test)))]
fn read_shared_buffer_byte(_offset: usize) -> u8 {
    0
}

#[cfg(target_os = "none")]
fn write_shared_buffer_byte(offset: usize, value: u8) {
    // SAFETY: Callers validate the offset against the runtime init descriptor's
    // shared-buffer resource range before writing payload bytes.
    unsafe {
        core::ptr::write_volatile((DRIVER_TASK_SHARED_BUFFER_VADDR + offset) as *mut u8, value);
    }
}

#[cfg(all(not(target_os = "none"), test))]
fn write_shared_buffer_byte(offset: usize, value: u8) {
    if offset >= DRIVER_TASK_RING_PAGE_BYTES * 64 {
        return;
    }
    // SAFETY: Runtime tests hold `test_guard` and the bounds check above keeps
    // writes inside the process-local fixed shared buffer.
    unsafe {
        (*TEST_SHARED_BUFFER.0.get())[offset] = value;
    }
}

#[cfg(all(not(target_os = "none"), not(test)))]
fn write_shared_buffer_byte(_offset: usize, _value: u8) {}

fn read_runtime_payload_byte(offset: usize) -> u8 {
    if offset < DRIVER_TASK_RING_PAGE_BYTES {
        read_ring_byte(offset)
    } else {
        read_shared_buffer_byte(offset - DRIVER_TASK_RING_PAGE_BYTES)
    }
}

fn write_runtime_payload_byte(offset: usize, value: u8) {
    if offset < DRIVER_TASK_RING_PAGE_BYTES {
        write_ring_byte(offset, value);
    } else {
        write_shared_buffer_byte(offset - DRIVER_TASK_RING_PAGE_BYTES, value);
    }
}

fn write_ring_u32(offset: usize, value: u32) {
    write_ring_byte(offset, (value & 0xff) as u8);
    write_ring_byte(offset + 1, ((value >> 8) & 0xff) as u8);
    write_ring_byte(offset + 2, ((value >> 16) & 0xff) as u8);
    write_ring_byte(offset + 3, ((value >> 24) & 0xff) as u8);
}

fn publish_runtime_progress(sequence: u32, phase: u32, aux0: u32) {
    let offset = DRIVER_RUNTIME_RING_PROGRESS_OFFSET as usize;
    write_ring_u32(offset, DRIVER_RUNTIME_RING_PROGRESS_MAGIC);
    write_ring_u32(offset + 4, sequence);
    write_ring_u32(offset + 8, phase);
    write_ring_u32(offset + 12, aux0);
    driver_task_shared_store_barrier();
    driver_task_shared_clean_range(
        DRIVER_TASK_RING_VADDR + offset,
        DRIVER_RUNTIME_RING_PROGRESS_BYTES as usize,
    );
}

#[cfg(any(target_os = "none", test))]
fn read_ring_u32(offset: usize) -> u32 {
    let b0 = u32::from(read_ring_byte(offset));
    let b1 = u32::from(read_ring_byte(offset + 1));
    let b2 = u32::from(read_ring_byte(offset + 2));
    let b3 = u32::from(read_ring_byte(offset + 3));
    b0 | (b1 << 8) | (b2 << 16) | (b3 << 24)
}

#[cfg(all(not(target_os = "none"), not(test)))]
fn read_ring_u32(_offset: usize) -> u32 {
    0
}

fn read_ring_u16(offset: usize) -> u16 {
    u16::from(read_ring_byte(offset)) | (u16::from(read_ring_byte(offset + 1)) << 8)
}

#[cfg(target_os = "none")]
fn copy_framebuffer_bytes(dst: usize, src: usize, len: usize) {
    if len == 0 || dst == src {
        return;
    }
    if (dst | src | len) & 0x7 == 0 {
        copy_framebuffer_u64(dst, src, len / 8);
        return;
    }
    if (dst | src | len) & 0x3 == 0 {
        copy_framebuffer_u32(dst, src, len / 4);
        return;
    }
    if dst > src && dst < src.saturating_add(len) {
        let mut index = len;
        while index != 0 {
            index -= 1;
            let byte = read_framebuffer_byte(src + index);
            write_framebuffer_byte(dst + index, byte);
        }
    } else {
        for index in 0..len {
            let byte = read_framebuffer_byte(src + index);
            write_framebuffer_byte(dst + index, byte);
        }
    }
}

#[cfg(target_os = "none")]
fn copy_framebuffer_u64(dst: usize, src: usize, words: usize) {
    if dst > src && dst < src.saturating_add(words.saturating_mul(8)) {
        let mut index = words;
        while index != 0 {
            index -= 1;
            let byte_offset = index * 8;
            let value = read_framebuffer_u64(src + byte_offset);
            write_framebuffer_u64(dst + byte_offset, value);
        }
    } else {
        for index in 0..words {
            let byte_offset = index * 8;
            let value = read_framebuffer_u64(src + byte_offset);
            write_framebuffer_u64(dst + byte_offset, value);
        }
    }
}

#[cfg(target_os = "none")]
fn copy_framebuffer_u32(dst: usize, src: usize, words: usize) {
    if dst > src && dst < src.saturating_add(words.saturating_mul(4)) {
        let mut index = words;
        while index != 0 {
            index -= 1;
            let byte_offset = index * 4;
            let value = read_framebuffer_u32(src + byte_offset);
            write_framebuffer_u32(dst + byte_offset, value);
        }
    } else {
        for index in 0..words {
            let byte_offset = index * 4;
            let value = read_framebuffer_u32(src + byte_offset);
            write_framebuffer_u32(dst + byte_offset, value);
        }
    }
}

#[cfg(not(target_os = "none"))]
fn copy_framebuffer_bytes(_dst: usize, _src: usize, _len: usize) {}

