    #[test]
    fn cyw43_rx_queue_removes_matching_channel_without_reordering_data() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        let data_a = *b"data-a";
        let control = *b"ctrl";
        let data_b = *b"data-b";
        let data_a_offset = CYW43_RUNTIME_RX_BUFFER_OFFSET + 0x100;
        let control_offset = CYW43_RUNTIME_RX_BUFFER_OFFSET + 0x200;
        let data_b_offset = CYW43_RUNTIME_RX_BUFFER_OFFSET + 0x300;
        stage_bytes(data_a_offset, &data_a);
        stage_bytes(control_offset, &control);
        stage_bytes(data_b_offset, &data_b);

        assert!(cyw43_rx_queue_push_from_runtime(
            &mut state,
            data_a_offset,
            data_a.len(),
            cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 1)
        ));
        assert!(cyw43_rx_queue_push_from_runtime(
            &mut state,
            control_offset,
            control.len(),
            cyw43_frame_flags(CYW43_SDPCM_CHANNEL_CONTROL, 2)
        ));
        assert!(cyw43_rx_queue_push_from_runtime(
            &mut state,
            data_b_offset,
            data_b.len(),
            cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 3)
        ));
        let control_slot = cyw43_rx_queue_slot_at(&state, 1);

        assert_eq!(
            cyw43_rx_queue_pop_matching(&mut state, CYW43_RX_FRAME_FLAG_MASK_CONTROL_EVENT),
            Some(DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: control.len() as u16,
                flags: cyw43_frame_flags(CYW43_SDPCM_CHANNEL_CONTROL, 2),
            })
        );
        assert_eq!(
            read_frame_prefix::<4>(DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: control.len() as u16,
                flags: 0,
            }),
            control
        );
        assert_eq!(state.rx_queue_lens[control_slot], 0);

        assert_eq!(
            cyw43_rx_queue_pop_matching(&mut state, CYW43_RX_FRAME_FLAG_MASK_DATA),
            Some(DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: data_a.len() as u16,
                flags: cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 1),
            })
        );
        assert_eq!(
            read_frame_prefix::<6>(DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: data_a.len() as u16,
                flags: 0,
            }),
            data_a
        );
        assert_eq!(
            cyw43_rx_queue_pop_matching(&mut state, CYW43_RX_FRAME_FLAG_MASK_DATA),
            Some(DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: data_b.len() as u16,
                flags: cyw43_frame_flags(CYW43_SDPCM_CHANNEL_DATA, 3),
            })
        );
        assert_eq!(
            read_frame_prefix::<6>(DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: data_b.len() as u16,
                flags: 0,
            }),
            data_b
        );
        assert_eq!(state.rx_queue_count, 0);
    }

    #[test]
    fn cyw43_transport_recovery_clears_stale_firmware_state() {
        let mut state = Cyw43RuntimeState::new();
        state.transport_ready = true;
        state.firmware_uploaded = true;
        state.nvram_uploaded = true;
        state.firmware_released = true;
        state.firmware_upload_prepared = true;
        state.firmware_byte_mode_fallback = true;
        state.nvram_tail_uploaded = true;
        state.sdpcm_seq = 9;
        state.sdpcm_seq_max = 9;
        state.tx_frames = 3;
        state.rx_frames = 2;
        state.firmware_bytes = 4096;
        state.nvram_bytes = 256;
        state.firmware_total_len = 4096;
        state.nvram_total_len = 256;
        state.nvram_tail_magic = 0xfeed_beef;
        state.backplane_window = 0x1800_0000;
        state.backplane_window_valid = true;
        state.bus_link_ready = true;

        state.reset_firmware_upload_state();

        assert!(state.transport_ready);
        assert!(state.bus_link_ready);
        assert!(!state.firmware_uploaded);
        assert!(!state.nvram_uploaded);
        assert!(!state.firmware_released);
        assert!(!state.firmware_upload_prepared);
        assert!(!state.firmware_byte_mode_fallback);
        assert!(!state.nvram_tail_uploaded);
        assert_eq!(state.sdpcm_seq, 0);
        assert_eq!(state.sdpcm_seq_max, 1);
        assert_eq!(state.tx_frames, 0);
        assert_eq!(state.rx_frames, 0);
        assert_eq!(state.firmware_bytes, 0);
        assert_eq!(state.nvram_bytes, 0);
        assert_eq!(state.firmware_total_len, 0);
        assert_eq!(state.nvram_total_len, 0);
        assert_eq!(state.nvram_tail_magic, 0);
        assert_eq!(state.backplane_window, 0);
        assert!(!state.backplane_window_valid);
    }

    #[test]
    fn cyw43_runtime_faults_preserve_command_stage_detail() {
        let _guard = test_guard();
        reset_runtime_for_test();
        init_cyw43_engine_for_test();
        let payload_offset = cyw43_runtime_payload_offset();
        stage_bytes(usize::from(payload_offset), &[0xaa, 0xbb, 0xcc, 0xdd]);
        stage_cyw43_descriptor(DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_FIRMWARE_CHUNK,
            flags: 0,
            target_addr: CYW43_RAM_BASE_4345 + CYW43_RAM_SIZE_4345_PI4 + 4,
            payload_offset,
            payload_len: 4,
            total_len: 4,
            arg0: 0,
            arg1: 0,
            reserved: 0,
        });
        assert_eq!(
            service_command(0, cyw43_descriptor_command(78)),
            DriverTaskCompletionRecord::fault_with_result(
                78,
                FAULT_CYW43_FIRMWARE_RANGE,
                CYW43_FIRMWARE_RANGE_RAM
            )
        );

        stage_cyw43_descriptor(DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_RELEASE,
            flags: 0,
            target_addr: 0,
            payload_offset: 0,
            payload_len: 0,
            total_len: 0,
            arg0: CYW43_RAM_BASE_4345,
            arg1: 0,
            reserved: 0,
        });
        assert_eq!(
            service_command(0, cyw43_descriptor_command(79)),
            DriverTaskCompletionRecord::fault(79, FAULT_CYW43_RELEASE)
        );
    }

    #[test]
    fn engine_init_rejects_descriptors_without_required_resources() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut descriptor = DriverRuntimeInitDescriptor::empty();
        descriptor.hot_path = HOT_PATH_GENET_NIC;
        descriptor.role_bit = ROLE_NET;
        descriptor.flags = pi4_driver_abi::DRIVER_RUNTIME_INIT_REQUIRED_FLAGS
            | pi4_driver_abi::DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY;
        descriptor.shared_page_count = 1;
        descriptor.shared_pages[0] = pi4_driver_abi::DriverRuntimePageDescriptor::new(0x4000_0000);
        let init_descriptor = DriverTaskCommandRecord {
            sequence: 40,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_GENET_NIC,
            arg1: ROLE_NET,
            aux0: DRIVER_RUNTIME_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: core::mem::size_of::<DriverRuntimeInitDescriptor>() as u16,
                flags: 0,
            },
        };
        assert_eq!(
            service_runtime_init_for_test(init_descriptor, descriptor),
            DriverTaskCompletionRecord::progress(40, HOT_PATH_GENET_NIC)
        );
        let engine_init = DriverTaskCommandRecord {
            sequence: 41,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_GENET_NIC,
            arg1: ROLE_NET,
            aux0: DRIVER_RUNTIME_NET_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor::empty(),
        };
        assert_eq!(
            service_command(0, engine_init),
            DriverTaskCompletionRecord::fault(
                41,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED as u16
            )
        );
    }

    #[test]
    fn cyw43_descriptor_rejects_direct_sdio_mmio_even_with_bus_link() {
        let mut descriptor = descriptor_for(HOT_PATH_CYW43_WIFI, ROLE_NET);
        assert!(descriptor_resources_ready(&descriptor, HOT_PATH_CYW43_WIFI));

        let range_index = usize::from(descriptor.resource_range_count);
        descriptor.resource_ranges[range_index] = DriverRuntimeResourceRangeDescriptor::new(
            DRIVER_RUNTIME_RESOURCE_KIND_MMIO,
            DRIVER_RUNTIME_RESOURCE_FLAG_VADDR_CONTIGUOUS
                | DRIVER_RUNTIME_RESOURCE_FLAG_PADDR_CONTIGUOUS
                | DRIVER_RUNTIME_RESOURCE_FLAG_DEVICE_VISIBLE,
            DRIVER_RUNTIME_RESOURCE_TAG_SDIO_HOST,
            DRIVER_TASK_DEVICE_MMIO_VADDR as u64,
            0x1000_0000,
            DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
            1,
            0,
        );
        descriptor.resource_range_count = descriptor.resource_range_count.saturating_add(1);

        assert!(!descriptor_resources_ready(
            &descriptor,
            HOT_PATH_CYW43_WIFI
        ));
        let mut state = Cyw43RuntimeState::new();
        assert!(!cyw43_runtime_init(
            42,
            DRIVER_RUNTIME_NET_INIT_AUX,
            &mut state,
            &descriptor
        ));
    }

