    #[test]
    fn cyw43_post_release_gate_requires_strict_function2_proof() {
        assert_eq!(FAULT_CYW43_POST_RELEASE_HT, 0x532a);
        assert_eq!(FAULT_CYW43_POST_RELEASE_F2_READY, 0x532b);
        assert_eq!(FAULT_CYW43_POST_RELEASE_CORECONTROL, 0x532c);
        assert_eq!(FAULT_CYW43_POST_RELEASE_MAILBOX_READY, 0x532d);
        assert_eq!(FAULT_CYW43_POST_RELEASE_PROTOCOL_VERSION, 0x532e);
        assert_eq!(CYW43_POST_RELEASE_MAILBOX_POLLS, 1_000);
        assert_eq!(CYW43_SDIO_F2_READY_REENABLE_RETRIES, 1);
        assert_eq!(CYW43_SDIO_F2_REENABLE_SETTLE_SPINS, 5_000);
        assert_eq!(cyw43_mailbox_version_payload(), 0x0004_0000);
        assert!(cyw43_firmware_mailbox_ready(
            HMB_DATA_FWREADY | cyw43_mailbox_version_payload()
        ));
        assert!(cyw43_firmware_mailbox_ready(
            HMB_DATA_DEVREADY | cyw43_mailbox_version_payload()
        ));
        assert!(cyw43_firmware_mailbox_ready(
            HMB_DATA_DEVREADY | HMB_DATA_FWREADY | cyw43_mailbox_version_payload()
        ));
        assert!(!cyw43_firmware_mailbox_ready(
            cyw43_mailbox_version_payload()
        ));
        assert!(!cyw43_firmware_mailbox_ready(
            HMB_DATA_FWREADY | (5 << HMB_DATA_VERSION_SHIFT)
        ));
        assert_eq!(
            cyw43_require_post_release_ht_clock().unwrap() & SBSDIO_HT_AVAIL,
            SBSDIO_HT_AVAIL
        );
        assert_eq!(
            cyw43_enable_post_release_function2().unwrap() & SDIO_FUNC_READY_2,
            SDIO_FUNC_READY_2
        );
        assert_eq!(SDIO_FUNCTION2_BLOCK_SIZE, 512);
        assert_eq!(SDIO_CCCR_IENX, 0x04);
        assert_eq!(SDIO_INTERRUPT_ENABLE_MASK, 0x07);
        assert!(cyw43_arm_post_release_function_interrupts().is_ok());
        let mut state = Cyw43RuntimeState::new();
        assert_eq!(
            cyw43_wait_for_firmware_mailbox_ready(&mut state).unwrap()
                & (HMB_DATA_DEVREADY | HMB_DATA_FWREADY | HMB_DATA_VERSION_MASK),
            HMB_DATA_DEVREADY | HMB_DATA_FWREADY | cyw43_mailbox_version_payload()
        );
    }

    #[test]
    fn cyw43_function2_force_ht_clock_preserves_strict_ht_proof() {
        assert_eq!(SBSDIO_FORCE_HT, 0x02);
        assert_eq!(cyw43_function2_force_ht_clock_value(0), SBSDIO_HT_AVAIL_REQ);
        assert_eq!(
            cyw43_function2_force_ht_clock_value(SBSDIO_HT_AVAIL_REQ | SBSDIO_ALP_AVAIL),
            SBSDIO_HT_AVAIL_REQ
        );
        assert_eq!(
            cyw43_function2_force_ht_clock_value(SBSDIO_HT_AVAIL),
            SBSDIO_HT_AVAIL | SBSDIO_HT_AVAIL_REQ | SBSDIO_FORCE_HT
        );
        assert_eq!(
            cyw43_force_ht_clock_for_function2().unwrap() & SBSDIO_FORCE_HT,
            SBSDIO_FORCE_HT
        );
    }

    #[test]
    fn cyw43_armcr4_reset_assert_descriptor_failure_is_advisory_after_halt() {
        assert_eq!(
            cyw43_armcr4_reset_stage_advisory_skip(
                true,
                false,
                Some(FAULT_SDIO_DESCRIPTOR_UNAVAILABLE)
            ),
            Ok(true)
        );
        assert_eq!(
            cyw43_armcr4_reset_stage_advisory_skip(
                true,
                false,
                Some(FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED)
            ),
            Ok(true)
        );
        assert_eq!(
            cyw43_armcr4_reset_stage_advisory_skip(
                false,
                false,
                Some(FAULT_SDIO_DESCRIPTOR_UNAVAILABLE)
            ),
            Err(FAULT_SDIO_DESCRIPTOR_UNAVAILABLE)
        );
        assert_eq!(
            cyw43_armcr4_reset_stage_advisory_skip(true, false, Some(FAULT_CYW43_COMMAND)),
            Err(FAULT_CYW43_COMMAND)
        );
        assert_eq!(
            cyw43_armcr4_reset_stage_advisory_skip(true, true, None),
            Ok(false)
        );
    }

    #[test]
    fn sdio_runtime_without_mmio_rejects_engine_init_before_register_access() {
        let _guard = test_guard();
        reset_runtime_for_test();

        let mut descriptor = DriverRuntimeInitDescriptor::empty();
        descriptor.hot_path = HOT_PATH_SDIO_HOST;
        descriptor.role_bit = ROLE_SDIO;
        descriptor.flags = pi4_driver_abi::DRIVER_RUNTIME_INIT_REQUIRED_FLAGS
            | pi4_driver_abi::DRIVER_RUNTIME_INIT_FLAG_POLL_ONLY;
        descriptor.shared_page_count = 1;
        descriptor.shared_pages[0] = pi4_driver_abi::DriverRuntimePageDescriptor::new(0x4000_0000);
        descriptor.resource_range_count = 1;
        descriptor.resource_ranges[0] = DriverRuntimeResourceRangeDescriptor::new(
            DRIVER_RUNTIME_RESOURCE_KIND_SHARED,
            DRIVER_RUNTIME_RESOURCE_FLAG_VADDR_CONTIGUOUS
                | DRIVER_RUNTIME_RESOURCE_FLAG_DEVICE_VISIBLE
                | DRIVER_RUNTIME_RESOURCE_FLAG_ROOT_SHARED,
            DRIVER_RUNTIME_RESOURCE_TAG_SHARED_CONTROL,
            DRIVER_TASK_SHARED_BUFFER_VADDR as u64,
            0x4000_0000,
            DRIVER_RUNTIME_RESOURCE_PAGE_BYTES,
            1,
            0,
        );
        let runtime_init = DriverTaskCommandRecord {
            sequence: 70,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_SDIO_HOST,
            arg1: ROLE_SDIO,
            aux0: DRIVER_RUNTIME_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor {
                offset: DRIVER_TASK_RING_FRAME_OFFSET as u32,
                len: core::mem::size_of::<DriverRuntimeInitDescriptor>() as u16,
                flags: 0,
            },
        };
        assert_eq!(
            service_runtime_init_for_test(runtime_init, descriptor),
            DriverTaskCompletionRecord::progress(70, HOT_PATH_SDIO_HOST)
        );

        let engine_init = DriverTaskCommandRecord {
            sequence: 71,
            opcode: OPCODE_SERVICE,
            flags: 0,
            arg0: HOT_PATH_SDIO_HOST,
            arg1: ROLE_SDIO,
            aux0: DRIVER_RUNTIME_ENGINE_INIT_AUX,
            aux1: 0,
            budget: budget(),
            frame: DriverFrameDescriptor::empty(),
        };
        assert_eq!(
            service_command(0, engine_init),
            DriverTaskCompletionRecord::fault(
                71,
                DRIVER_RUNTIME_RING_PROGRESS_ENGINE_INIT_RESOURCE_CHECK_FAILED as u16
            )
        );
    }

    #[test]
    fn sdio_descriptor_helpers_encode_cmd52_and_cmd53_arguments() {
        assert_eq!(
            sdio_cmd52_arg(false, 1, 0x1234, 0),
            (1 << 28) | (0x1234 << 9)
        );
        assert_eq!(
            sdio_cmd52_arg(true, 2, 0x20, 0x5a),
            (1 << 31) | (2 << 28) | (0x20 << 9) | 0x5a
        );
        assert_eq!(
            sdio_cmd53_arg(true, 2, 0x1_0000, true, 4, 0),
            (1 << 31) | (2 << 28) | (1 << 27) | (1 << 26) | (0x1_0000 << 9) | 4
        );
        assert_eq!(
            sdio_descriptor_response_flags(DRIVER_RUNTIME_SDIO_RESP_SHORT_BUSY),
            DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT_BUSY
        );
    }

    #[test]
    fn sdio_runtime_int_ack_preserves_card_interrupt() {
        let status = SDHCI_INT_RESPONSE | SDHCI_INT_DATA_END | SDHCI_INT_CARD_INT | SDHCI_INT_ERROR;
        assert_eq!(
            sdhci_wait_int_ack_bits(SDHCI_INT_RESPONSE, status),
            SDHCI_INT_RESPONSE | SDHCI_INT_DATA_END | SDHCI_INT_ERROR
        );
        assert_eq!(SDHCI_INT_COMMAND_DATA_CLEAR_MASK & SDHCI_INT_CARD_INT, 0);
        assert_ne!(SDHCI_INT_DATA_FINISH_MASK & SDHCI_INT_DATA_END, 0);
        assert_ne!(SDHCI_INT_DATA_FINISH_MASK & SDHCI_INT_DATA_CRC, 0);
        assert_ne!(SDHCI_INT_DATA_FINISH_MASK & SDHCI_INT_ERROR, 0);
    }

    #[test]
    fn cyw43_backplane_upload_uses_block_primary_before_firmware_release() {
        assert_eq!(
            CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES,
            CYW43_FIRMWARE_STAGE_BYTES / 2
        );
        assert!(CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES < CYW43_FIRMWARE_STAGE_BYTES);
        assert_eq!(
            CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES % SDIO_FUNCTION1_BLOCK_SIZE as usize,
            0
        );
        assert_eq!(
            cyw43_backplane_write_chunk_shape(false, false, 2048),
            (2048, SDIO_FUNCTION1_BLOCK_SIZE, 32)
        );
        assert_eq!(
            cyw43_backplane_write_chunk_shape(false, false, CYW43_FIRMWARE_STAGE_BYTES),
            (
                CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES,
                SDIO_FUNCTION1_BLOCK_SIZE,
                64
            )
        );
        assert_eq!(
            cyw43_backplane_write_chunk_shape(false, false, 32 * 1024),
            (
                CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES,
                SDIO_FUNCTION1_BLOCK_SIZE,
                64
            )
        );
        assert_eq!(
            cyw43_backplane_write_chunk_shape(false, true, 2048),
            (
                CYW43_FIRMWARE_BYTE_MODE_CHUNK_BYTES,
                CYW43_FIRMWARE_BYTE_MODE_CHUNK_BYTES as u16,
                0
            )
        );
        assert_eq!(
            CYW43_FIRMWARE_BYTE_MODE_CHUNK_BYTES,
            CYW43_FIRMWARE_BYTE_MODE_SAFE_CHUNK_BYTES
        );
        assert_eq!(
            CYW43_FIRMWARE_BYTE_MODE_CHUNK_BYTES,
            SDIO_CMD53_BYTE_MODE_MAX
        );
        assert_eq!(CYW43_FIRMWARE_BYTE_MODE_NARROW_CHUNK_BYTES, 64);
        assert_eq!(
            CYW43_FIRMWARE_BYTE_MODE_NARROW_CHUNK_BYTES,
            SDIO_FUNCTION1_BLOCK_SIZE as usize
        );
        assert_eq!(
            cyw43_backplane_write_chunk_shape(false, false, 4),
            (4, 4, 0)
        );
        assert_eq!(
            cyw43_backplane_write_chunk_shape(true, false, 2048),
            (
                SDIO_FUNCTION2_BLOCK_SIZE as usize,
                SDIO_FUNCTION2_BLOCK_SIZE,
                1
            )
        );
        assert_eq!(cyw43_backplane_write_chunk_shape(true, false, 4), (4, 4, 1));
    }

    #[test]
    fn cyw43_firmware_upload_uses_byte_mode_at_backplane_window_edge() {
        assert!(!cyw43_backplane_write_prefers_byte_mode_at_window_edge(
            false,
            false,
            CYW43_FIRMWARE_STAGE_BYTES,
            CYW43_FIRMWARE_STAGE_BYTES
        ));
        assert!(!cyw43_backplane_write_prefers_byte_mode_at_window_edge(
            false,
            false,
            CYW43_FIRMWARE_STAGE_BYTES,
            CYW43_FIRMWARE_STAGE_BYTES * 2
        ));
        assert!(!cyw43_backplane_write_prefers_byte_mode_at_window_edge(
            true,
            false,
            CYW43_FIRMWARE_STAGE_BYTES,
            CYW43_FIRMWARE_STAGE_BYTES
        ));
        assert_eq!(
            cyw43_backplane_write_chunk_shape(false, true, CYW43_FIRMWARE_STAGE_BYTES),
            (
                CYW43_FIRMWARE_BYTE_MODE_CHUNK_BYTES,
                CYW43_FIRMWARE_BYTE_MODE_CHUNK_BYTES as u16,
                0
            )
        );
        assert_eq!(
            cyw43_backplane_write_chunk_shape_for_lane(
                false,
                true,
                true,
                CYW43_FIRMWARE_STAGE_BYTES
            ),
            (
                CYW43_FIRMWARE_BYTE_MODE_NARROW_CHUNK_BYTES,
                CYW43_FIRMWARE_BYTE_MODE_NARROW_CHUNK_BYTES as u16,
                0
            )
        );
        assert_eq!(
            CYW43_FIRMWARE_BYTE_MODE_CHUNK_BYTES,
            CYW43_FIRMWARE_BYTE_MODE_SAFE_CHUNK_BYTES
        );
        let arg = sdio_cmd53_arg(
            true,
            1,
            CYW43_RAM_BASE_4345,
            cyw43_backplane_cmd53_increment(true),
            0,
            CYW43_FIRMWARE_BYTE_MODE_CHUNK_BYTES as u16,
        );
        assert_eq!(
            CYW43_FIRMWARE_BYTE_MODE_CHUNK_BYTES,
            SDIO_CMD53_BYTE_MODE_MAX
        );
        assert_eq!(arg & 0x1ff, 0);
        assert_ne!(arg & (1 << 26), 0);
        let block_arg = sdio_cmd53_arg(
            true,
            1,
            CYW43_RAM_BASE_4345,
            cyw43_backplane_cmd53_increment(false),
            1,
            SDIO_FUNCTION1_BLOCK_SIZE,
        );
        assert_ne!(block_arg & (1 << 26), 0);
    }

    #[test]
    fn cyw43_linked_pre_release_owner_upload_uses_block_primary_with_byte_replay() {
        assert_eq!(
            cyw43_backplane_write_chunk_shape_for_lane(
                false,
                CYW43_LINKED_PRE_RELEASE_BYTE_MODE_PRIMARY,
                true,
                CYW43_FIRMWARE_STAGE_BYTES
            ),
            (
                CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES,
                SDIO_FUNCTION1_BLOCK_SIZE,
                (CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES / SDIO_FUNCTION1_BLOCK_SIZE as usize) as u16,
            )
        );
        assert_eq!(
            cyw43_backplane_write_chunk_shape(false, true, CYW43_FIRMWARE_STAGE_BYTES),
            (
                CYW43_FIRMWARE_BYTE_MODE_CHUNK_BYTES,
                CYW43_FIRMWARE_BYTE_MODE_CHUNK_BYTES as u16,
                0,
            )
        );
        let arg = sdio_cmd53_arg(
            true,
            1,
            cyw43_backplane_function_addr(CYW43_RAM_BASE_4345),
            true,
            (CYW43_FIRMWARE_BLOCK_MODE_CHUNK_BYTES / SDIO_FUNCTION1_BLOCK_SIZE as usize) as u16,
            SDIO_FUNCTION1_BLOCK_SIZE,
        );
        assert_ne!(arg & (1 << 27), 0);
        assert_ne!(arg & (1 << 26), 0);
        assert_eq!(
            sdio_transfer_failure_result(SDIO_TRANSFER_FAILURE_STAGE_DATA_WAIT, SDHCI_INT_ERROR),
            (SDIO_TRANSFER_FAILURE_STAGE_DATA_WAIT << 24) | SDHCI_INT_ERROR
        );
    }

    #[test]
    fn cyw43_function2_fifo_shape_matches_card_and_host_mode() {
        assert_eq!(
            CYW43_CONTROL_RX_BLOCK_PROBE_BYTES,
            CYW43_FUNCTION2_BLOCK_BYTES
        );
        let (probe_block_size, probe_block_count) =
            cyw43_function2_cmd53_shape(CYW43_CONTROL_RX_BLOCK_PROBE_BYTES);
        assert_eq!(probe_block_size, CYW43_FUNCTION2_BLOCK_BYTES as u16);
        assert_eq!(probe_block_count, 1);

        let (block_size, block_count) =
            cyw43_function2_cmd53_shape(CYW43_FUNCTION2_BLOCK_BYTES * 3);
        assert_eq!(block_size, CYW43_FUNCTION2_BLOCK_BYTES as u16);
        assert_eq!(block_count, 3);
        let block_arg = sdio_cmd53_arg(
            true,
            2,
            BACKPLANE_32BIT_FLAG,
            false,
            block_count,
            (CYW43_FUNCTION2_BLOCK_BYTES * 3) as u16,
        );
        assert_ne!(block_arg & (1 << 27), 0);
        assert_eq!(block_arg & 0x1ff, 3);

        let (byte_size, byte_count) = cyw43_function2_cmd53_shape(96);
        assert_eq!(byte_size, 96);
        assert_eq!(byte_count, 0);
        let byte_arg = sdio_cmd53_arg(true, 2, BACKPLANE_32BIT_FLAG, false, byte_count, 96);
        assert_eq!(byte_arg & (1 << 27), 0);
        assert_eq!(byte_arg & 0x1ff, 96);
    }

    #[test]
    fn sdio_descriptor_retry_covers_function1_backplane_and_function2_cmd53_writes() {
        let mut desc = DriverRuntimeSdioCommandDescriptor {
            op: DRIVER_RUNTIME_SDIO_OP_CMD53_WRITE,
            function: 1,
            response_kind: DRIVER_RUNTIME_SDIO_RESP_SHORT,
            addr: CYW43_RAM_BASE_4345,
            data_offset: DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE,
            len: CYW43_FIRMWARE_BYTE_MODE_CHUNK_BYTES as u16,
            block_size: 0,
            block_count: 0,
            flags: DriverRuntimeSdioCommandDescriptor::FLAG_INCREMENT,
            reserved: 0,
            timeout_us: 100_000,
        };
        assert!(sdio_descriptor_transfer_retryable(
            desc,
            SDIO_CMD53,
            DRIVER_RUNTIME_SDIO_FLAG_DATA
                | DRIVER_RUNTIME_SDIO_FLAG_WRITE
                | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        ));
        desc.function = 2;
        assert!(sdio_descriptor_transfer_retryable(
            desc,
            SDIO_CMD53,
            DRIVER_RUNTIME_SDIO_FLAG_DATA
                | DRIVER_RUNTIME_SDIO_FLAG_WRITE
                | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        ));
        desc.function = 0;
        assert!(!sdio_descriptor_transfer_retryable(
            desc,
            SDIO_CMD53,
            DRIVER_RUNTIME_SDIO_FLAG_DATA
                | DRIVER_RUNTIME_SDIO_FLAG_WRITE
                | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        ));
        desc.function = 2;
        desc.op = DRIVER_RUNTIME_SDIO_OP_CMD53_READ;
        assert!(!sdio_descriptor_transfer_retryable(
            desc,
            SDIO_CMD53,
            DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
        ));
    }

    #[test]
    fn sdio_fault_telemetry_frame_encodes_owner_command_snapshot() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let arg = sdio_cmd53_arg(
            true,
            1,
            cyw43_backplane_function_addr(CYW43_RAM_BASE_4345),
            true,
            0,
            SDIO_CMD53_BYTE_MODE_MAX as u16,
        );
        let transfer_mode = sdio_transfer_mode_from_flags(
            DRIVER_RUNTIME_SDIO_FLAG_DATA | DRIVER_RUNTIME_SDIO_FLAG_WRITE,
            1,
        );
        let failure =
            sdio_transfer_failure_result(SDIO_TRANSFER_FAILURE_STAGE_DATA_END, SDHCI_INT_ERROR);
        let payload = DriverFrameDescriptor {
            offset: DRIVER_TASK_RING_PAGE_BYTES as u32,
            len: SDIO_CMD53_BYTE_MODE_MAX as u16,
            flags: 0,
        };
        write_runtime_payload_byte(payload.offset as usize, 0x11);
        write_runtime_payload_byte(
            payload.offset as usize + usize::from(payload.len).saturating_sub(1),
            0x22,
        );

        let frame = sdio_write_fault_telemetry_frame(
            SDIO_CMD53,
            arg,
            DRIVER_RUNTIME_SDIO_FLAG_DATA
                | DRIVER_RUNTIME_SDIO_FLAG_WRITE
                | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT,
            SDIO_CMD53_BYTE_MODE_MAX as u16,
            SDIO_CMD53_BYTE_MODE_MAX as u16,
            1,
            transfer_mode,
            failure,
            payload,
        );

        assert_eq!(frame.offset, SDIO_FAULT_TELEMETRY_FRAME_OFFSET as u32);
        assert_eq!(frame.len, SDIO_FAULT_TELEMETRY_BYTES);
        assert_eq!(
            read_ring_u32(SDIO_FAULT_TELEMETRY_FRAME_OFFSET),
            SDIO_FAULT_TELEMETRY_MAGIC
        );
        assert_eq!(
            read_ring_u32(SDIO_FAULT_TELEMETRY_FRAME_OFFSET + 4),
            SDIO_FAULT_TELEMETRY_VERSION
        );
        assert_eq!(
            read_ring_u32(SDIO_FAULT_TELEMETRY_FRAME_OFFSET + SDIO_FAULT_TELEMETRY_ARG_OFFSET),
            arg
        );
        assert_eq!(
            read_ring_u32(SDIO_FAULT_TELEMETRY_FRAME_OFFSET + SDIO_FAULT_TELEMETRY_FAILURE_OFFSET),
            failure
        );
        assert_eq!(
            read_ring_u32(
                SDIO_FAULT_TELEMETRY_FRAME_OFFSET + SDIO_FAULT_TELEMETRY_LEN_BLOCK_OFFSET
            ),
            u32::from(SDIO_CMD53_BYTE_MODE_MAX as u16)
                | (u32::from(SDIO_CMD53_BYTE_MODE_MAX as u16) << 16)
        );
        assert_eq!(
            read_ring_u32(
                SDIO_FAULT_TELEMETRY_FRAME_OFFSET + SDIO_FAULT_TELEMETRY_COUNT_MODE_OFFSET
            ),
            u32::from(1u16) | (u32::from(transfer_mode) << 16)
        );
        assert_eq!(
            read_ring_u32(
                SDIO_FAULT_TELEMETRY_FRAME_OFFSET + SDIO_FAULT_TELEMETRY_PAYLOAD_EDGE_OFFSET
            ),
            0x0033_2211
        );
        assert_eq!(
            read_ring_u32(
                SDIO_FAULT_TELEMETRY_FRAME_OFFSET + SDIO_FAULT_TELEMETRY_PAYLOAD_SUM_OFFSET
            ),
            0x33
        );
    }

    #[test]
    fn sdio_descriptor_cmd53_byte_mode_keeps_descriptor_zero_and_host_one_block() {
        let flags = DRIVER_RUNTIME_SDIO_FLAG_DATA
            | DRIVER_RUNTIME_SDIO_FLAG_WRITE
            | DRIVER_RUNTIME_SDIO_FLAG_RESP_SHORT;
        let arg = sdio_cmd53_arg(
            true,
            1,
            cyw43_backplane_function_addr(CYW43_RAM_BASE_4345),
            true,
            0,
            SDIO_CMD53_BYTE_MODE_MAX as u16,
        );
        assert_eq!(arg, 0x9500_0000);

        let host_block_count = sdio_descriptor_host_block_count(0, flags);
        assert_eq!(host_block_count, 1);
        let transfer = sdio_transfer_mode_from_flags(flags, host_block_count);
        assert_ne!(transfer & SDHCI_TRNS_BLK_CNT_EN, 0);
        assert_eq!(transfer & SDHCI_TRNS_MULTI, 0);
        assert_eq!(transfer & SDHCI_TRNS_READ, 0);

        let read_transfer = sdio_transfer_mode_from_flags(
            DRIVER_RUNTIME_SDIO_FLAG_DATA,
            sdio_descriptor_host_block_count(0, DRIVER_RUNTIME_SDIO_FLAG_DATA),
        );
        assert_ne!(read_transfer & SDHCI_TRNS_BLK_CNT_EN, 0);
        assert_ne!(read_transfer & SDHCI_TRNS_READ, 0);
    }

    #[test]
    fn sdio_cmd53_r5_errors_match_old_hal_status_mask() {
        let firmware_write = sdio_cmd53_arg(
            true,
            1,
            cyw43_backplane_function_addr(CYW43_RAM_BASE_4345),
            true,
            1,
            SDIO_FUNCTION1_BLOCK_SIZE,
        );
        let function2_write = sdio_cmd53_arg(
            true,
            2,
            BACKPLANE_32BIT_FLAG,
            false,
            0,
            SDIO_FUNCTION2_BLOCK_SIZE,
        );
        assert_eq!(sdio_cmd53_r5_error(SDIO_CMD53, 0, 0), None);
        assert_eq!(
            sdio_cmd53_r5_error(SDIO_CMD53, firmware_write, SDIO_R5_OUT_OF_RANGE),
            None
        );
        assert_eq!(
            sdio_cmd53_r5_error(SDIO_CMD53, firmware_write, 0x0100),
            Some(0x0100)
        );
        assert_eq!(
            sdio_cmd53_r5_error(SDIO_CMD53, function2_write, SDIO_R5_OUT_OF_RANGE),
            Some(SDIO_R5_OUT_OF_RANGE)
        );
        assert_eq!(sdio_cmd53_r5_error(SDIO_CMD52, 0, 0x0800), None);
        assert_eq!(sdio_cmd53_r5_error(SDIO_CMD5, 0, 0x0800), None);
        assert_eq!(
            sdio_transfer_failure_result(SDIO_TRANSFER_FAILURE_STAGE_RESPONSE, 0x0800),
            (SDIO_TRANSFER_FAILURE_STAGE_RESPONSE << 24) | 0x0800
        );
    }

    #[test]
