    #[test]
    fn cyw43_armcr4_reset_skip_treats_retry_exhaustion_as_advisory_after_ioctl() {
        assert!(cyw43_armcr4_reset_stage_advisory_skip(
            true,
            false,
            Some(FAULT_CYW43_FIRMWARE_RETRY_EXHAUSTED),
        )
        .expect("post-ioctrl reset rejection is advisory"));
        assert!(cyw43_armcr4_reset_stage_advisory_skip(
            true,
            false,
            Some(FAULT_SDIO_DESCRIPTOR_UNAVAILABLE),
        )
        .expect("descriptor exhaustion is advisory at reset stage"));
        assert!(cyw43_armcr4_reset_stage_advisory_skip(
            true,
            false,
            Some(FAULT_SDIO_DESCRIPTOR_TRANSFER_FAILED),
        )
        .expect("descriptor transfer failure is advisory at reset stage"));
        assert!(cyw43_armcr4_reset_stage_advisory_skip(
            false,
            false,
            Some(FAULT_CYW43_FIRMWARE_RETRY_EXHAUSTED),
        )
        .is_err());
    }

    #[test]
    fn cyw43_runtime_stream_completion_requires_declared_total_lengths() {
        assert_eq!(
            cyw43_stream_next_bytes(0, 0, 4096, 1024, 1024, false),
            Some(1024)
        );
        assert_eq!(
            cyw43_stream_next_bytes(1024, 4096, 4096, 3072, 3072, false),
            Some(4096)
        );
        assert_eq!(
            cyw43_stream_next_bytes(1024, 4096, 2048, 512, 512, false),
            None
        );
        assert_eq!(
            cyw43_stream_next_bytes(4090, 4096, 4096, 16, 16, false),
            None
        );
        assert_eq!(cyw43_stream_next_bytes(0, 0, 0, 0, 0, false), None);
    }

    #[test]
    fn cyw43_firmware_stream_accepts_logical_final_tail_padding() {
        assert_eq!(
            cyw43_stream_next_bytes(606_208, 609_309, 609_309, 3_584, 3_101, true),
            Some(609_309)
        );
        assert_eq!(
            cyw43_stream_next_bytes(606_208, 609_309, 609_309, 3_584, 3_101, false),
            None
        );
        assert_eq!(
            cyw43_stream_next_bytes(606_208, 609_309, 609_309, 3_585, 3_101, true),
            None
        );
        assert_eq!(
            cyw43_stream_next_bytes(606_208, 609_309, 609_309, 3_584, 3_584, true),
            None
        );
    }

    #[test]
    fn cyw43_firmware_stream_rejects_nonzero_tail_padding() {
        let payload_offset = usize::from(DRIVER_RUNTIME_SHARED_PAYLOAD_OFFSET_BASE);
        for index in 0..3_584 {
            write_runtime_payload_byte(payload_offset + index, 0);
        }

        assert!(cyw43_runtime_payload_tail_zero(
            payload_offset,
            3_101,
            3_584
        ));
        write_runtime_payload_byte(payload_offset + 3_101, 0x5a);
        assert!(!cyw43_runtime_payload_tail_zero(
            payload_offset,
            3_101,
            3_584
        ));
    }

    #[test]
    fn cyw43_release_requires_nvram_tail_after_complete_streams() {
        let _guard = test_guard();
        reset_runtime_for_test();
        let mut state = Cyw43RuntimeState::new();
        state.transport_ready = true;
        state.firmware_uploaded = true;
        state.nvram_uploaded = true;
        assert!(!cyw43_release_firmware(&mut state, 0, 1));

        state.nvram_tail_uploaded = true;
        assert!(cyw43_release_firmware(&mut state, 0, 1));
        let offset = DRIVER_RUNTIME_RING_PROGRESS_OFFSET as usize;
        assert_eq!(read_ring_u32(offset), DRIVER_RUNTIME_RING_PROGRESS_MAGIC);
        assert_eq!(read_ring_u32(offset + 4), 1);
        assert_eq!(
            read_ring_u32(offset + 8),
            DRIVER_RUNTIME_RING_PROGRESS_CYW43_RELEASE_FIRMWARE_READY_DONE
        );
        assert_eq!(read_ring_u32(offset + 12), DRIVER_RUNTIME_CYW43_COMMAND_AUX);
    }

    #[test]
    fn cyw43_core_control_transplant_matches_old_good_pi4_bases() {
        assert_eq!(CYW43_D11_CORE_BASES, [0x1810_1000]);
        assert_eq!(CYW43_ARMCR4_CORE_BASE, 0x1810_2000);
        assert_eq!(CYW43_SOCRAM_CORE_BASE, 0x1810_4000);
        assert_eq!(D11_BCMA_IOCTL_PHYRESET | D11_BCMA_IOCTL_PHYCLOCKEN, 0x0c);
        assert_eq!(
            cyw43_core_reset_prepare_hold_value(ARMCR4_BCMA_IOCTL_CPUHALT),
            0x23
        );
        assert!(!cyw43_socram_core_reset_required_before_armcr4_upload());
        assert!(CYW43_ARMCR4_CONTROL_SETTLE_SPINS < CYW43_CORE_CONTROL_SETTLE_SPINS);
    }

    #[test]
    fn sdio_transfer_mode_sets_multi_for_multiblock_firmware_chunks() {
        let byte_write = sdio_transfer_mode(true, 1);
        assert_ne!(byte_write & SDHCI_TRNS_BLK_CNT_EN, 0);
        assert_eq!(byte_write & SDHCI_TRNS_MULTI, 0);
        assert_eq!(byte_write & SDHCI_TRNS_READ, 0);

        let byte_read = sdio_transfer_mode(false, 1);
        assert_ne!(byte_read & SDHCI_TRNS_BLK_CNT_EN, 0);
        assert_ne!(byte_read & SDHCI_TRNS_READ, 0);

        let single_write = sdio_transfer_mode(true, 1);
        assert_ne!(single_write & SDHCI_TRNS_BLK_CNT_EN, 0);
        assert_eq!(single_write & SDHCI_TRNS_MULTI, 0);
        assert_eq!(single_write & SDHCI_TRNS_READ, 0);

        let firmware_write = sdio_transfer_mode(true, 23);
        assert_ne!(firmware_write & SDHCI_TRNS_BLK_CNT_EN, 0);
        assert_ne!(firmware_write & SDHCI_TRNS_MULTI, 0);
        assert_eq!(firmware_write & SDHCI_TRNS_READ, 0);

        let firmware_read = sdio_transfer_mode(false, 23);
        assert_ne!(firmware_read & SDHCI_TRNS_MULTI, 0);
        assert_ne!(firmware_read & SDHCI_TRNS_READ, 0);
    }

