    #[test]
    fn usb_keyboard_arms_deep_first_report_queue() {
        let descriptor = descriptor_for(HOT_PATH_USB_KEYBOARD, ROLE_USB);
        let mut state = UsbRuntimeState::new();
        state.db_offset = 0x1000;
        state.keyboard_slot = 2;
        state.keyboard_endpoint_id = 3;

        assert!(USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH >= 128);
        assert!(xhci_arm_keyboard_interrupt_queue(&mut state, &descriptor));
        assert_eq!(
            usize::from(state.keyboard_reports_queued),
            USB_KEYBOARD_FIRST_REPORT_QUEUE_DEPTH
        );
        for slot in 0..USB_KEYBOARD_FIRST_REPORT_QUEUE_DEPTH {
            assert!(state.keyboard_report_in_use[slot]);
            assert_eq!(state.keyboard_report_trb_indices[slot], slot as u16);
            assert_eq!(
                xhci_keyboard_report_buffer_offset(slot),
                XHCI_DMA_REPORT_BUFFER_OFFSET + slot * USB_KEYBOARD_REPORT_BUFFER_BYTES
            );
        }

        state.keyboard_transfer_events = 1;
        assert!(xhci_arm_keyboard_interrupt_queue(&mut state, &descriptor));
        assert_eq!(
            usize::from(state.keyboard_reports_queued),
            USB_KEYBOARD_INTERRUPT_QUEUE_DEPTH
        );
        assert!(!xhci_queue_keyboard_interrupt_in(&mut state, &descriptor));
    }

    #[test]
    fn usb_keyboard_interrupt_trbs_request_bounded_endpoint_packet_len() {
        let descriptor = descriptor_for(HOT_PATH_USB_KEYBOARD, ROLE_USB);
        let mut state = UsbRuntimeState::new();
        state.db_offset = 0x1000;
        state.keyboard_slot = 2;
        state.keyboard_endpoint_id = 3;
        state.keyboard_ep_max_packet = 9;

        assert_eq!(usb_keyboard_report_request_len(&state), 9);
        assert!(xhci_queue_keyboard_interrupt_in(&mut state, &descriptor));
        assert_eq!(state.kbd_enqueue, 1);
        assert_eq!(state.keyboard_reports_queued, 1);

        state.keyboard_ep_max_packet = 512;
        assert_eq!(
            usb_keyboard_report_request_len(&state),
            USB_KEYBOARD_REPORT_BUFFER_BYTES
        );

        state.keyboard_attach_rank = USB_KEYBOARD_ATTACH_RANK_STRICT_BOOT;
        assert_eq!(
            usb_keyboard_report_request_len(&state),
            USB_BOOT_REPORT_BYTES
        );

        state.keyboard_attach_rank = USB_KEYBOARD_ATTACH_RANK_PROTOCOL_NONE;
        state.keyboard_ep_max_packet = 9;
        assert_eq!(usb_keyboard_report_request_len(&state), 9);
    }

    #[test]
    fn usb_enumeration_result_encodes_frontier_snapshot() {
        let mut state = UsbRuntimeState::new();
        state.initialized = true;
        state.command_path_proven = true;
        state.enumeration_root_powered = true;
        state.enumeration_root_scan_pass = 2;
        state.port_event_candidate_mask = 0b1010;
        state.port_event_count = 3;
        state.keyboard_slot = 4;
        state.keyboard_endpoint_id = 3;
        state.keyboard_endpoint_address = 0x81;
        state.keyboard_preserved_event_count = 1;
        state.keyboard_transfer_events = 2;

        let result = usb_runtime_enumeration_result(&state);

        assert_eq!(result & USB_ENUM_RESULT_ROOT_PORT_MASK, 0);
        assert_eq!((result >> USB_ENUM_RESULT_SLOT_SHIFT) & 0xff, 4);
        assert_eq!((result >> USB_ENUM_RESULT_ENDPOINT_SHIFT) & 0x1f, 3);
        assert_eq!(
            (result >> USB_ENUM_RESULT_SCAN_PASS_SHIFT) & USB_ENUM_RESULT_SCAN_PASS_MASK,
            2
        );
        assert_ne!(result & USB_ENUM_RESULT_SNAPSHOT, 0);
        assert_ne!(result & USB_ENUM_RESULT_ROOT_POWERED, 0);
        assert_ne!(result & USB_ENUM_RESULT_COMMAND_PATH, 0);
        assert_ne!(result & USB_ENUM_RESULT_PORT_EVENT, 0);
        assert_ne!(result & USB_ENUM_RESULT_HID_ENDPOINT, 0);
        assert_ne!(result & USB_ENUM_RESULT_PRESERVED_EVENT, 0);
        assert_ne!(result & USB_ENUM_RESULT_TRANSFER_EVENT, 0);
        assert_ne!(result & USB_ENUM_RESULT_ENDPOINT_READY, 0);
    }

    #[test]
    fn usb_command_proof_snapshot_uses_event_count_without_portsc_sampling() {
        let mut state = UsbRuntimeState::new();
        state.initialized = true;
        state.max_ports = 4;
        state.init_detail = DRIVER_RUNTIME_USB_INIT_DETAIL_COMMAND_RING_PENDING;
        state.command_proof_pending = true;
        state.command_proof_poll_slices = 5;
        state.command_proof_events_seen = 2;
        state.command_proof_last_event_type = XHCI_TRB_TYPE_PORT_STATUS_CHANGE_EVENT as u8;
        state.command_proof_ack_failures = 3;

        let result = usb_runtime_enumeration_result(&state);

        assert_eq!(result & USB_ENUM_RESULT_ROOT_PORT_MASK, 2);
        assert_eq!((result >> USB_ENUM_RESULT_SLOT_SHIFT) & 0xff, 5);
        assert_eq!(
            (result >> USB_ENUM_RESULT_ENDPOINT_SHIFT) & 0x1f,
            u32::from(USB_COMMAND_PROOF_EVENT_PORT_STATUS)
        );
        assert_eq!(
            (result >> USB_ENUM_RESULT_SCAN_PASS_SHIFT) & USB_ENUM_RESULT_SCAN_PASS_MASK,
            3
        );
        assert_eq!(
            usb_command_proof_event_code(XHCI_TRB_TYPE_COMMAND_COMPLETION as u8),
            USB_COMMAND_PROOF_EVENT_COMMAND_COMPLETION
        );
        assert_eq!(
            usb_command_proof_event_code(XHCI_TRB_TYPE_TRANSFER_EVENT as u8),
            USB_COMMAND_PROOF_EVENT_TRANSFER
        );
        assert_eq!(
            usb_command_proof_event_code(0x3f),
            USB_COMMAND_PROOF_EVENT_OTHER
        );
    }

    #[test]
    fn usb_keyboard_decodes_report_buffer_from_transfer_event_trb() {
        let descriptor = descriptor_for(HOT_PATH_USB_KEYBOARD, ROLE_USB);
        let dma_range = runtime_resource_range(
            &descriptor,
            DRIVER_RUNTIME_RESOURCE_KIND_DMA,
            DRIVER_RUNTIME_RESOURCE_TAG_DMA_ARENA,
        )
        .expect("USB descriptor has DMA arena");
        let kbd_ring = xhci_dma_bus_addr(&descriptor, dma_range, XHCI_DMA_KBD_RING_OFFSET).unwrap();
        let mut state = UsbRuntimeState::new();
        state.db_offset = 0x1000;
        state.keyboard_slot = 4;
        state.keyboard_endpoint_id = 3;
        assert!(xhci_queue_keyboard_interrupt_in(&mut state, &descriptor));
        assert!(xhci_queue_keyboard_interrupt_in(&mut state, &descriptor));

        let event = XhciTrb {
            parameter: kbd_ring + XHCI_TRB_BYTES as u64 + 0x08,
            status: XHCI_COMPLETION_SHORT_PACKET << 24,
            control: (XHCI_TRB_TYPE_TRANSFER_EVENT << 10)
                | (u32::from(state.keyboard_endpoint_id) << 16)
                | (u32::from(state.keyboard_slot) << 24),
        };
        assert_eq!(
            xhci_complete_keyboard_report_slot(&mut state, &descriptor, dma_range, event),
            Some(1)
        );
        assert!(!state.keyboard_report_in_use[1]);
        assert!(state.keyboard_report_in_use[0]);
        assert_eq!(state.keyboard_reports_queued, 1);
    }

    #[test]
    fn usb_command_wait_can_preserve_keyboard_transfer_event() {
        let mut state = UsbRuntimeState::new();
        state.keyboard_slot = 4;
        state.keyboard_endpoint_id = 3;
        let event = XhciTrb {
            parameter: 0x2000_0000,
            status: XHCI_COMPLETION_SUCCESS << 24,
            control: (XHCI_TRB_TYPE_TRANSFER_EVENT << 10)
                | (u32::from(state.keyboard_endpoint_id) << 16)
                | (u32::from(state.keyboard_slot) << 24),
        };
        assert!(xhci_keyboard_transfer_event_matches(&state, event));
        assert!(xhci_preserve_keyboard_transfer_event(&mut state, event));
        assert_eq!(state.keyboard_preserved_event_count, 1);
        assert_eq!(
            xhci_take_preserved_keyboard_transfer_event(&mut state),
            Some(event)
        );
        assert_eq!(state.keyboard_preserved_event_count, 0);
    }

